import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
  calculateBeliefFragility,
  calculateEvidenceAgreement,
  createBeliefReason,
  evaluateBelief,
  evaluateEvidence,
} from "./engine";
import {
  evaluateBelief as exportedEvaluateBelief,
  evaluateEvidence as exportedEvaluateEvidence,
} from "../index";

function expect<T>(actual: T) {
  return {
    toBe: (expected: unknown) => assert.equal(actual, expected),
    toEqual: (expected: unknown) => assert.deepEqual(actual, expected),
    toContain: (expected: unknown) => assert.ok((actual as any).includes(expected)),
    toHaveLength: (expected: number) => assert.equal((actual as any).length, expected),
    toMatchObject: (expected: unknown) => assert.partialDeepStrictEqual(actual, expected),
    toBeGreaterThan: (expected: number) => assert.ok(Number(actual) > expected),
    toBeGreaterThanOrEqual: (expected: number) => assert.ok(Number(actual) >= expected),
    toBeLessThan: (expected: number) => assert.ok(Number(actual) < expected),
    toBeLessThanOrEqual: (expected: number) => assert.ok(Number(actual) <= expected),
    not: {
      toBe: (expected: unknown) => assert.notEqual(actual, expected),
    },
  };
}

const support = (
  name: string,
  strength = 90,
  confidence = 90,
  source = name,
  weight = 1,
) => ({
  name,
  direction: "support" as const,
  strength,
  confidence,
  source,
  weight,
  reason: `${name} supports the claim.`,
});

const contradict = (
  name: string,
  strength = 80,
  confidence = 90,
  source = name,
  weight = 1,
) => ({
  name,
  direction: "contradict" as const,
  strength,
  confidence,
  source,
  weight,
  reason: `${name} contradicts the claim.`,
});

const neutral = (name: string, strength = 55, confidence = 80) => ({
  name,
  direction: "neutral" as const,
  strength,
  confidence,
  reason: `${name} adds context.`,
});

describe("Signal Belief", () => {
  it("returns a justified belief when strong support is covered, trusted, and stable", () => {
    const result = evaluateBelief({
      claim: "The route should proceed.",
      priorConfidence: 60,
      uncertainty: 5,
      evidence: [
        support("direct observation", 92, 95, "sensor-a"),
        support("historical match", 88, 92, "memory"),
        support("independent check", 86, 90, "validator"),
      ],
    });

    expect(result.verdict).toBe("justified");
    expect(result.confidence).toBeGreaterThanOrEqual(70);
    expect(result.trustworthiness).toBeGreaterThanOrEqual(70);
    expect(result.fragility).toBeLessThanOrEqual(35);
    expect(result.blockers).toEqual([]);
    expect(result.supportingEvidence.map((item) => item.name)).toEqual([
      "direct observation",
      "historical match",
      "independent check",
    ]);
    expect(result.reason).toContain("Belief is justified");
  });

  it("returns weak when support exists but does not clear justified coverage", () => {
    const result = evaluateBelief({
      claim: "The route may proceed.",
      evidence: [
        support("moderate observation", 64, 72),
        support("moderate memory", 62, 70),
        support("moderate validator", 60, 70),
      ],
    });

    expect(result.verdict).toBe("weak");
    expect(result.confidence).toBeGreaterThanOrEqual(55);
    expect(result.blockers).toEqual([]);
    expect(createBeliefReason(result)).toContain("Belief is weak");
  });

  it("returns contradicted when contradiction is stronger than support", () => {
    const result = evaluateBelief({
      claim: "The route should proceed.",
      evidence: [
        support("small support", 35, 80),
        contradict("large contradiction", 88, 95),
        contradict("independent contradiction", 82, 90),
      ],
    });

    expect(result.verdict).toBe("contradicted");
    expect(result.contradictionStrength).toBeGreaterThan(result.supportStrength);
    expect(result.blockers).toContain(
      "Contradictory evidence is stronger than supporting evidence.",
    );
    expect(result.blockers).toContain("Contradictory evidence is strong.");
  });

  it("returns uncertain when evidence is too thin and fragile", () => {
    const result = evaluateBelief({
      claim: "The route should proceed.",
      uncertainty: 100,
      evidence: [support("weak low-confidence support", 10, 0)],
    });

    expect(result.verdict).toBe("uncertain");
    expect(result.fragility).toBeGreaterThan(65);
    expect(result.blockers).toContain("Belief is too fragile.");
    expect(result.blockers).toContain("Evidence coverage is insufficient.");
  });

  it("handles empty evidence as uncertain with a deterministic no-evidence reason", () => {
    const result = evaluateBelief({
      claim: "The route should proceed.",
      evidence: [],
    });

    expect(result.verdict).toBe("uncertain");
    expect(result.evidenceCoverage).toBe(0);
    expect(result.evidenceAgreement).toBe(0);
    expect(result.fragility).toBe(100);
    expect(result.blockers).toEqual(["No evidence was supplied."]);
    expect(result.reason).toContain("No directional evidence is available.");
  });

  it("scores strong support above weak support", () => {
    const strong = evaluateBelief({
      claim: "Strongly supported.",
      evidence: [
        support("trend", 95, 95),
        support("quality", 92, 92),
        support("agreement", 90, 90),
      ],
    });
    const weak = evaluateBelief({
      claim: "Weakly supported.",
      evidence: [
        support("trend", 55, 60),
        support("quality", 52, 60),
        support("agreement", 50, 60),
      ],
    });

    expect(strong.confidence).toBeGreaterThan(weak.confidence);
    expect(strong.supportStrength).toBeGreaterThan(weak.supportStrength);
  });

  it("strong contradiction prevents a justified verdict", () => {
    const result = evaluateBelief({
      claim: "The route should proceed.",
      contradictionTolerance: 30,
      evidence: [
        support("excellent support", 95, 95),
        support("second support", 92, 95),
        contradict("serious contradiction", 85, 90),
      ],
    });

    expect(result.verdict).not.toBe("justified");
    expect(result.warnings.some((warning) => warning.includes("exceeds tolerance"))).toBe(true);
  });

  it("mixed evidence lowers agreement and increases fragility", () => {
    const supportOnly = evaluateBelief({
      claim: "Support only.",
      evidence: [
        support("support a", 80, 85, "a"),
        support("support b", 78, 85, "b"),
        support("support c", 76, 85, "c"),
      ],
    });
    const mixed = evaluateBelief({
      claim: "Mixed.",
      evidence: [
        support("support a", 80, 85, "a"),
        support("support b", 78, 85, "b"),
        contradict("contradiction", 70, 85, "c"),
      ],
    });

    expect(mixed.evidenceAgreement).toBeLessThan(supportOnly.evidenceAgreement);
    expect(mixed.fragility).toBeGreaterThan(supportOnly.fragility);
    expect(mixed.warnings).toContain("Supporting and contradictory evidence are close.");
  });

  it("neutral evidence contributes coverage without directional confidence", () => {
    const result = evaluateBelief({
      claim: "Neutral context only.",
      evidence: [
        neutral("watchlist presence", 70, 80),
        neutral("lifecycle stage", 60, 70),
        neutral("age", 50, 60),
      ],
    });

    expect(result.verdict).toBe("uncertain");
    expect(result.evidenceCoverage).toBeGreaterThan(0);
    expect(result.evidenceAgreement).toBe(50);
    expect(result.supportStrength).toBe(0);
    expect(result.contradictionStrength).toBe(0);
    expect(result.neutralEvidence).toHaveLength(3);
  });

  it("high uncertainty reduces trustworthiness and increases fragility", () => {
    const certain = evaluateBelief({
      claim: "Certain.",
      uncertainty: 0,
      evidence: [
        support("support a", 90, 90, "a"),
        support("support b", 90, 90, "b"),
        support("support c", 90, 90, "c"),
      ],
    });
    const uncertain = evaluateBelief({
      claim: "Uncertain.",
      uncertainty: 85,
      evidence: [
        support("support a", 90, 90, "a"),
        support("support b", 90, 90, "b"),
        support("support c", 90, 90, "c"),
      ],
    });

    expect(uncertain.trustworthiness).toBeLessThan(certain.trustworthiness);
    expect(uncertain.fragility).toBeGreaterThan(certain.fragility);
    expect(uncertain.verdict).not.toBe("justified");
    expect(uncertain.warnings.some((warning) => warning.includes("Uncertainty is high"))).toBe(true);
  });

  it("low evidence count reduces coverage and prevents a justified verdict", () => {
    const result = evaluateBelief({
      claim: "One piece of evidence.",
      minimumEvidenceCount: 4,
      evidence: [support("single support", 95, 95, "single")],
    });

    expect(result.evidenceCoverage).toBeLessThan(60);
    expect(result.verdict).not.toBe("justified");
    expect(result.warnings[0]).toContain("Evidence count 1 is below minimum 4.");
  });

  it("low evidence confidence reduces trust and is surfaced as a warning", () => {
    const result = evaluateBelief({
      claim: "Low confidence evidence.",
      evidence: [
        support("support a", 90, 30, "a"),
        support("support b", 90, 35, "b"),
        support("support c", 90, 40, "c"),
      ],
    });

    expect(result.trustworthiness).toBeLessThan(80);
    expect(result.warnings.some((warning) => warning.includes("Average evidence confidence is low"))).toBe(true);
  });

  it("one dominant source increases fragility", () => {
    const independent = evaluateBelief({
      claim: "Independent sources.",
      evidence: [
        support("support a", 80, 90, "a"),
        support("support b", 80, 90, "b"),
        support("support c", 80, 90, "c"),
      ],
    });
    const dominated = evaluateBelief({
      claim: "Dominated source.",
      evidence: [
        support("support a", 80, 90, "same"),
        support("support b", 80, 90, "same"),
        support("support c", 80, 90, "same"),
      ],
    });

    expect(dominated.fragility).toBeGreaterThan(independent.fragility);
    expect(dominated.warnings.some((warning) => warning.includes("One evidence source dominates"))).toBe(true);
  });

  it("prior confidence influences final confidence without overriding evidence", () => {
    const lowPrior = evaluateBelief({
      claim: "Prior low.",
      priorConfidence: 20,
      evidence: [
        support("support a", 75, 85, "a"),
        support("support b", 75, 85, "b"),
        support("support c", 75, 85, "c"),
      ],
    });
    const highPrior = evaluateBelief({
      claim: "Prior high.",
      priorConfidence: 90,
      evidence: [
        support("support a", 75, 85, "a"),
        support("support b", 75, 85, "b"),
        support("support c", 75, 85, "c"),
      ],
    });

    expect(highPrior.confidence).toBeGreaterThan(lowPrior.confidence);
    expect(highPrior.supportStrength).toBe(lowPrior.supportStrength);
  });

  it("produces deterministic audit output", () => {
    const input = {
      claim: "Audit determinism.",
      evidence: [
        support("support", 80, 90, "source-a"),
        contradict("contradiction", 40, 70, "source-b"),
        neutral("neutral", 55, 60),
      ],
    };
    const first = evaluateBelief(input);
    const second = evaluateBelief(input);

    expect(first.audit).toEqual(second.audit);
    expect(first.audit.steps).toEqual(second.audit.steps);
    expect(first.audit.normalized).toEqual(second.audit.normalized);
  });

  it("clamps invalid numeric values and normalizes invalid directions", () => {
    const evidence = evaluateEvidence({
      name: "",
      direction: "invalid" as any,
      strength: -10,
      confidence: Number.POSITIVE_INFINITY,
      weight: Number.NaN,
      metadata: { kept: true },
    });
    const result = evaluateBelief({
      claim: "",
      priorConfidence: Number.POSITIVE_INFINITY,
      uncertainty: 200,
      minimumEvidenceCount: -5,
      minimumCoverage: 120,
      contradictionTolerance: -1,
      evidence: [evidence as any],
    });

    expect(evidence).toMatchObject({
      name: "evidence",
      direction: "neutral",
      strength: 0,
      confidence: 50,
      weight: 1,
      weightedStrength: 0,
      metadata: { kept: true },
    });
    expect(result.claim).toBe("Unspecified claim");
    expect(result.uncertainty).toBe(100);
    expect(result.audit.normalized.priorConfidence).toBe(50);
    expect(result.audit.normalized.minimumEvidenceCount).toBe(1);
    expect(result.audit.normalized.minimumCoverage).toBe(100);
    expect(result.audit.normalized.contradictionTolerance).toBe(0);
  });

  it("exports the public Belief API from the framework index", () => {
    expect(exportedEvaluateEvidence(support("exported"))).toMatchObject({
      name: "exported",
      direction: "support",
    });
    expect(exportedEvaluateBelief({
      claim: "Exported belief works.",
      evidence: [
        support("support a", 90, 90, "a"),
        support("support b", 90, 90, "b"),
        support("support c", 90, 90, "c"),
      ],
    }).verdict).toBe("justified");
  });

  it("calculates agreement and fragility for direct helper calls", () => {
    const supportResult = evaluateEvidence(support("support", 80, 90));
    const contradictionResult = evaluateEvidence(contradict("contradiction", 80, 90));
    const neutralResult = evaluateEvidence(neutral("neutral", 80, 90));

    expect(calculateEvidenceAgreement([])).toBe(0);
    expect(calculateEvidenceAgreement(undefined as any)).toBe(0);
    expect(calculateEvidenceAgreement([neutralResult])).toBe(50);
    expect(calculateEvidenceAgreement([supportResult])).toBe(100);
    expect(calculateEvidenceAgreement([supportResult, contradictionResult])).toBe(50);

    const fragile = calculateBeliefFragility(
      { claim: "Fragile.", uncertainty: 80, evidence: [support("support", 20, 10)] },
      [evaluateEvidence(support("support", 20, 10))],
    );
    const fallbackFragile = calculateBeliefFragility(
      { claim: "Fallback fragile.", evidence: [] },
      undefined as any,
    );
    expect(fragile).toBeGreaterThan(50);
    expect(fallbackFragile).toBe(100);
  });

  it("normalizes missing runtime fields defensively", () => {
    const evidence = evaluateEvidence({} as any);
    const result = evaluateBelief({} as any);

    expect(evidence).toMatchObject({
      name: "evidence",
      direction: "neutral",
      strength: 0,
      confidence: 50,
      weight: 1,
      reason: "evidence provides neutral evidence with strength 0/100.",
    });
    expect(result.claim).toBe("Unspecified claim");
    expect(result.audit.inputs.claim).toBe("");
    expect(result.audit.inputs.evidence).toEqual([]);
  });
});

import { clamp, mean } from "../math/statistics";

export type BeliefVerdict = "justified" | "weak" | "contradicted" | "uncertain";

export type EvidenceDirection = "support" | "contradict" | "neutral";

export interface EvidenceInput {
  name: string;
  direction: EvidenceDirection;
  strength: number;
  confidence?: number;
  weight?: number;
  source?: string;
  reason?: string;
  metadata?: Record<string, unknown>;
}

export interface EvidenceResult {
  name: string;
  direction: EvidenceDirection;
  strength: number;
  confidence: number;
  weight: number;
  weightedStrength: number;
  source?: string;
  reason: string;
  metadata?: Record<string, unknown>;
}

export interface BeliefInput {
  claim: string;
  priorConfidence?: number;
  evidence: EvidenceInput[];
  uncertainty?: number;
  minimumEvidenceCount?: number;
  minimumCoverage?: number;
  contradictionTolerance?: number;
  metadata?: Record<string, unknown>;
}

export interface BeliefResult {
  claim: string;
  verdict: BeliefVerdict;
  confidence: number;
  trustworthiness: number;
  evidenceStrength: number;
  evidenceAgreement: number;
  evidenceCoverage: number;
  supportStrength: number;
  contradictionStrength: number;
  uncertainty: number;
  fragility: number;
  supportingEvidence: EvidenceResult[];
  contradictoryEvidence: EvidenceResult[];
  neutralEvidence: EvidenceResult[];
  blockers: string[];
  warnings: string[];
  reason: string;
  audit: {
    formula: string;
    inputs: BeliefInput;
    normalized: Record<string, number>;
    steps: string[];
  };
}

type BeliefMetrics = {
  priorConfidence: number;
  uncertainty: number;
  minimumEvidenceCount: number;
  minimumCoverage: number;
  contradictionTolerance: number;
  evidenceStrength: number;
  evidenceAgreement: number;
  evidenceCoverage: number;
  supportStrength: number;
  contradictionStrength: number;
  neutralStrength: number;
  averageEvidenceConfidence: number;
  sourceDominance: number;
  confidence: number;
  trustworthiness: number;
  fragility: number;
};

const DEFAULT_PRIOR_CONFIDENCE = 50;
const DEFAULT_EVIDENCE_CONFIDENCE = 50;
const DEFAULT_EVIDENCE_WEIGHT = 1;
const DEFAULT_UNCERTAINTY = 0;
const DEFAULT_MINIMUM_EVIDENCE_COUNT = 3;
const DEFAULT_MINIMUM_COVERAGE = 60;
const DEFAULT_CONTRADICTION_TOLERANCE = 35;

export function evaluateBelief(input: BeliefInput): BeliefResult {
  const evidence = safeEvidence(input.evidence).map(evaluateEvidence);
  const supportingEvidence = evidenceByDirection(evidence, "support");
  const contradictoryEvidence = evidenceByDirection(evidence, "contradict");
  const neutralEvidence = evidenceByDirection(evidence, "neutral");
  const metrics = calculateBeliefMetrics(input, evidence);
  const warnings = collectWarnings(metrics, evidence);
  const verdict = resolveVerdict(metrics, evidence);
  const blockers = collectBlockers(verdict, metrics, evidence);
  const result: BeliefResult = {
    claim: String(input.claim ?? "").trim() || "Unspecified claim",
    verdict,
    confidence: metrics.confidence,
    trustworthiness: metrics.trustworthiness,
    evidenceStrength: metrics.evidenceStrength,
    evidenceAgreement: metrics.evidenceAgreement,
    evidenceCoverage: metrics.evidenceCoverage,
    supportStrength: metrics.supportStrength,
    contradictionStrength: metrics.contradictionStrength,
    uncertainty: metrics.uncertainty,
    fragility: metrics.fragility,
    supportingEvidence,
    contradictoryEvidence,
    neutralEvidence,
    blockers,
    warnings,
    reason: "",
    audit: {
      formula:
        "confidence = prior*0.25 + support*0.8 - contradiction*0.65 - uncertainty*0.3 + (coverage-50)*0.15 + (agreement-50)*0.1; trustworthiness = agreement*0.25 + coverage*0.25 + averageEvidenceConfidence*0.35 + (100-uncertainty)*0.15; fragility = lowCoverage*0.4 + conflict*0.2 + uncertainty*0.2 + lowEvidenceConfidence*0.1 + sourceDominance*0.1",
      inputs: {
        ...input,
        claim: String(input.claim ?? ""),
        evidence: safeEvidence(input.evidence),
      },
      normalized: normalizedAudit(metrics),
      steps: [
        `Evaluated ${evidence.length} evidence item(s).`,
        `Support ${formatScore(metrics.supportStrength)} vs contradiction ${formatScore(metrics.contradictionStrength)}.`,
        `Coverage ${formatScore(metrics.evidenceCoverage)}, agreement ${formatScore(metrics.evidenceAgreement)}, uncertainty ${formatScore(metrics.uncertainty)}.`,
        `Confidence ${formatScore(metrics.confidence)}, trustworthiness ${formatScore(metrics.trustworthiness)}, fragility ${formatScore(metrics.fragility)}.`,
      ],
    },
  };

  return {
    ...result,
    reason: createBeliefReason(result),
  };
}

export function evaluateEvidence(input: EvidenceInput): EvidenceResult {
  const name = String(input.name ?? "").trim() || "evidence";
  const direction = normalizeDirection(input.direction);
  const strength = score(input.strength);
  const confidence = score(input.confidence, DEFAULT_EVIDENCE_CONFIDENCE);
  const weight = score(input.weight, DEFAULT_EVIDENCE_WEIGHT);
  const weightedStrength = roundScore(strength * (confidence / 100) * weight);
  const reason = String(input.reason ?? "").trim() || defaultEvidenceReason(name, direction, strength);

  return {
    name,
    direction,
    strength,
    confidence,
    weight,
    weightedStrength,
    ...(input.source ? { source: String(input.source) } : {}),
    reason,
    ...(input.metadata ? { metadata: input.metadata } : {}),
  };
}

export function calculateEvidenceAgreement(results: EvidenceResult[]): number {
  const evidence = Array.isArray(results) ? results : [];
  if (!evidence.length) return 0;

  const support = directionalStrength(evidence, "support");
  const contradiction = directionalStrength(evidence, "contradict");
  const directionalTotal = support + contradiction;

  if (directionalTotal <= 0) return 50;

  return roundScore((Math.max(support, contradiction) / directionalTotal) * 100);
}

export function calculateBeliefFragility(
  input: BeliefInput,
  evidence: EvidenceResult[],
): number {
  return calculateBeliefMetrics(input, Array.isArray(evidence) ? evidence : []).fragility;
}

export function createBeliefReason(result: BeliefResult): string {
  const support = topEvidenceName(result.supportingEvidence);
  const contradiction = topEvidenceName(result.contradictoryEvidence);
  const suffix = result.blockers.length
    ? ` Blockers: ${result.blockers.join("; ")}.`
    : result.warnings.length
      ? ` Warnings: ${result.warnings.slice(0, 2).join("; ")}.`
      : "";
  const evidencePhrase = [
    support ? `top support: ${support}` : "",
    contradiction ? `top contradiction: ${contradiction}` : "",
  ].filter(Boolean).join("; ");

  return [
    `Belief is ${result.verdict} for "${result.claim}"`,
    `with confidence ${formatScore(result.confidence)}, trustworthiness ${formatScore(result.trustworthiness)}, and fragility ${formatScore(result.fragility)}.`,
    evidencePhrase ? `Evidence ${evidencePhrase}.` : "No directional evidence is available.",
    suffix.trim(),
  ].filter(Boolean).join(" ");
}

function calculateBeliefMetrics(input: BeliefInput, evidence: EvidenceResult[]): BeliefMetrics {
  const priorConfidence = score(input.priorConfidence, DEFAULT_PRIOR_CONFIDENCE);
  const uncertainty = score(input.uncertainty, DEFAULT_UNCERTAINTY);
  const minimumEvidenceCount = Math.max(
    1,
    Math.round(score(input.minimumEvidenceCount, DEFAULT_MINIMUM_EVIDENCE_COUNT)),
  );
  const minimumCoverage = score(input.minimumCoverage, DEFAULT_MINIMUM_COVERAGE);
  const contradictionTolerance = score(
    input.contradictionTolerance,
    DEFAULT_CONTRADICTION_TOLERANCE,
  );
  const supportStrength = directionalStrength(evidence, "support");
  const contradictionStrength = directionalStrength(evidence, "contradict");
  const neutralStrength = directionalStrength(evidence, "neutral");
  const evidenceAgreement = calculateEvidenceAgreement(evidence);
  const averageEvidenceConfidence = roundScore(mean(evidence.map((item) => item.confidence)));
  const evidenceStrength = roundScore(
    Math.max(supportStrength, contradictionStrength, neutralStrength),
  );
  const evidenceCoverage = evidenceCoverageScore(
    evidence.length,
    minimumEvidenceCount,
    averageEvidenceConfidence,
  );
  const sourceDominance = sourceDominanceScore(evidence);
  const confidence = roundScore(
    priorConfidence * 0.25 +
      supportStrength * 0.8 -
      contradictionStrength * 0.65 -
      uncertainty * 0.3 +
      (evidenceCoverage - 50) * 0.15 +
      (evidenceAgreement - 50) * 0.1,
  );
  const trustworthiness = roundScore(
    evidenceAgreement * 0.25 +
      evidenceCoverage * 0.25 +
      averageEvidenceConfidence * 0.35 +
      (100 - uncertainty) * 0.15,
  );
  const conflictFragility =
    supportStrength + contradictionStrength <= 0
      ? 80
      : clamp(100 - Math.abs(supportStrength - contradictionStrength) * 2);
  const dominanceFragility = clamp(Math.max(0, sourceDominance - 50) * 2);
  const fragility = evidence.length
    ? roundScore(
        (100 - evidenceCoverage) * 0.4 +
          conflictFragility * 0.2 +
          uncertainty * 0.2 +
          (100 - averageEvidenceConfidence) * 0.1 +
          dominanceFragility * 0.1,
      )
    : 100;

  return {
    priorConfidence,
    uncertainty,
    minimumEvidenceCount,
    minimumCoverage,
    contradictionTolerance,
    evidenceStrength,
    evidenceAgreement,
    evidenceCoverage,
    supportStrength,
    contradictionStrength,
    neutralStrength,
    averageEvidenceConfidence,
    sourceDominance,
    confidence: clamp(confidence),
    trustworthiness: clamp(trustworthiness),
    fragility: clamp(fragility),
  };
}

function resolveVerdict(metrics: BeliefMetrics, evidence: EvidenceResult[]): BeliefVerdict {
  if (!evidence.length) return "uncertain";

  if (
    metrics.confidence >= 70 &&
    metrics.trustworthiness >= 70 &&
    metrics.contradictionStrength <= metrics.contradictionTolerance &&
    metrics.fragility <= 35 &&
    metrics.evidenceCoverage >= metrics.minimumCoverage
  ) {
    return "justified";
  }

  if (
    metrics.contradictionStrength > metrics.supportStrength ||
    metrics.contradictionStrength >= 60
  ) {
    return "contradicted";
  }

  if (
    metrics.confidence >= 55 &&
    metrics.trustworthiness >= 50 &&
    metrics.contradictionStrength <= 45
  ) {
    return "weak";
  }

  return "uncertain";
}

function collectWarnings(metrics: BeliefMetrics, evidence: EvidenceResult[]) {
  const warnings: string[] = [];

  if (evidence.length > 0 && evidence.length < metrics.minimumEvidenceCount) {
    warnings.push(
      `Evidence count ${evidence.length} is below minimum ${metrics.minimumEvidenceCount}.`,
    );
  }

  if (evidence.length > 0 && metrics.evidenceCoverage < metrics.minimumCoverage) {
    warnings.push(
      `Evidence coverage ${formatScore(metrics.evidenceCoverage)} is below minimum ${formatScore(metrics.minimumCoverage)}.`,
    );
  }

  if (metrics.uncertainty >= 60) {
    warnings.push(`Uncertainty is high at ${formatScore(metrics.uncertainty)}.`);
  }

  if (evidence.length > 0 && metrics.averageEvidenceConfidence < 50) {
    warnings.push(
      `Average evidence confidence is low at ${formatScore(metrics.averageEvidenceConfidence)}.`,
    );
  }

  if (metrics.sourceDominance >= 70) {
    warnings.push(`One evidence source dominates ${formatScore(metrics.sourceDominance)} of source weight.`);
  }

  if (
    metrics.supportStrength > 0 &&
    metrics.contradictionStrength > 0 &&
    Math.abs(metrics.supportStrength - metrics.contradictionStrength) <= 15
  ) {
    warnings.push("Supporting and contradictory evidence are close.");
  }

  if (metrics.contradictionStrength > metrics.contradictionTolerance) {
    warnings.push(
      `Contradiction ${formatScore(metrics.contradictionStrength)} exceeds tolerance ${formatScore(metrics.contradictionTolerance)}.`,
    );
  }

  return unique(warnings);
}

function collectBlockers(
  verdict: BeliefVerdict,
  metrics: BeliefMetrics,
  evidence: EvidenceResult[],
) {
  if (verdict === "justified" || verdict === "weak") return [];

  const blockers: string[] = [];

  if (!evidence.length) {
    blockers.push("No evidence was supplied.");
  }

  if (
    verdict === "contradicted" &&
    metrics.contradictionStrength > metrics.supportStrength
  ) {
    blockers.push("Contradictory evidence is stronger than supporting evidence.");
  }

  if (metrics.contradictionStrength >= 60) {
    blockers.push("Contradictory evidence is strong.");
  }

  if (evidence.length > 0 && metrics.confidence < 55) {
    blockers.push(`Confidence ${formatScore(metrics.confidence)} is below weak-belief threshold.`);
  }

  if (evidence.length > 0 && metrics.trustworthiness < 50) {
    blockers.push(`Trustworthiness ${formatScore(metrics.trustworthiness)} is below minimum.`);
  }

  if (evidence.length > 0 && metrics.evidenceCoverage < metrics.minimumCoverage) {
    blockers.push("Evidence coverage is insufficient.");
  }

  if (evidence.length > 0 && metrics.fragility > 65) {
    blockers.push("Belief is too fragile.");
  }

  return unique(blockers);
}

function evidenceByDirection(evidence: EvidenceResult[], direction: EvidenceDirection) {
  return evidence
    .filter((item) => item.direction === direction)
    .sort((a, b) => b.weightedStrength - a.weightedStrength || a.name.localeCompare(b.name));
}

function directionalStrength(evidence: EvidenceResult[], direction: EvidenceDirection) {
  const directional = evidence.filter((item) => item.direction === direction);
  const totalWeight = directional.reduce((sum, item) => sum + item.weight, 0);
  if (totalWeight <= 0) return 0;

  return roundScore(
    directional.reduce((sum, item) => sum + item.weightedStrength, 0) / totalWeight,
  );
}

function evidenceCoverageScore(
  evidenceCount: number,
  minimumEvidenceCount: number,
  averageEvidenceConfidence: number,
) {
  if (evidenceCount <= 0) return 0;

  const countCoverage = clamp((evidenceCount / minimumEvidenceCount) * 100);
  return roundScore(countCoverage * 0.85 + averageEvidenceConfidence * 0.15);
}

function sourceDominanceScore(evidence: EvidenceResult[]) {
  const sourceWeights = new Map<string, number>();
  let totalWeight = 0;

  for (const item of evidence) {
    const sourceKey = String(item.source ?? `evidence:${item.name}`);
    const sourceWeight = item.weight * (item.confidence / 100);
    sourceWeights.set(sourceKey, (sourceWeights.get(sourceKey) ?? 0) + sourceWeight);
    totalWeight += sourceWeight;
  }

  if (totalWeight <= 0 || sourceWeights.size === 0) return 0;

  return roundScore((Math.max(...sourceWeights.values()) / totalWeight) * 100);
}

function normalizedAudit(metrics: BeliefMetrics): Record<string, number> {
  return {
    priorConfidence: metrics.priorConfidence,
    uncertainty: metrics.uncertainty,
    minimumEvidenceCount: metrics.minimumEvidenceCount,
    minimumCoverage: metrics.minimumCoverage,
    contradictionTolerance: metrics.contradictionTolerance,
    evidenceStrength: metrics.evidenceStrength,
    evidenceAgreement: metrics.evidenceAgreement,
    evidenceCoverage: metrics.evidenceCoverage,
    supportStrength: metrics.supportStrength,
    contradictionStrength: metrics.contradictionStrength,
    neutralStrength: metrics.neutralStrength,
    averageEvidenceConfidence: metrics.averageEvidenceConfidence,
    sourceDominance: metrics.sourceDominance,
    confidence: metrics.confidence,
    trustworthiness: metrics.trustworthiness,
    fragility: metrics.fragility,
  };
}

function topEvidenceName(evidence: EvidenceResult[]) {
  const top = evidence[0];
  return top ? `${top.name} (${formatScore(top.weightedStrength)})` : "";
}

function defaultEvidenceReason(name: string, direction: EvidenceDirection, strength: number) {
  return `${name} provides ${direction} evidence with strength ${formatScore(strength)}.`;
}

function safeEvidence(evidence: EvidenceInput[] | undefined) {
  return Array.isArray(evidence) ? evidence : [];
}

function normalizeDirection(direction: EvidenceDirection): EvidenceDirection {
  if (direction === "support" || direction === "contradict" || direction === "neutral") {
    return direction;
  }

  return "neutral";
}

function score(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return clamp(Number.isFinite(numberValue) ? numberValue : fallback);
}

function roundScore(value: number) {
  return Number(clamp(value).toFixed(2));
}

function formatScore(value: number) {
  return `${Number(value.toFixed(2))}/100`;
}

function unique(values: string[]) {
  return Array.from(new Set(values));
}

export function clamp(value: number, min = 0, max = 100) {
  return Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));
}

export function numeric(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

export function mean(values: number[]) {
  const usable = values.filter(Number.isFinite);
  return usable.length ? usable.reduce((sum, value) => sum + value, 0) / usable.length : 0;
}

export function stdev(values: number[]) {
  const usable = values.filter(Number.isFinite);
  if (usable.length < 2) return 0;
  const average = mean(usable);
  return Math.sqrt(mean(usable.map((value) => (value - average) ** 2)));
}

export function percentileRank(values: number[], value: number) {
  const usable = values.filter(Number.isFinite);
  if (!usable.length) return clamp(value);
  return clamp((usable.filter((item) => item <= value).length / usable.length) * 100);
}

export function signRatio(values: number[], direction: "positive" | "negative") {
  const usable = values.filter(Number.isFinite);
  if (!usable.length) return 0;
  return usable.filter((value) => (direction === "positive" ? value >= 0 : value < 0)).length / usable.length;
}

export function immutable<T>(value: T): Readonly<T> {
  return deepFreeze(structuredClone(value));
}

function deepFreeze<T>(value: T): Readonly<T> {
  if (value && typeof value === "object") {
    Object.freeze(value);
    for (const child of Object.values(value as Record<string, unknown>)) {
      deepFreeze(child);
    }
  }
  return value as Readonly<T>;
}

