export function buildStocksOptimizerMetrics(input: StocksOptimizerMetricSource): MetricInput[] {
  const stocks = Array.isArray(input.stocks) ? input.stocks : [];
  const count = Math.max(1, stocks.length);
  const changes = stocks.map(latestChange);
  const absChanges = changes.map((value) => Math.abs(value));
  const expectedMoves = stocks.map((stock) => numeric(stock.expectedMove, latestChange(stock)));
  const setupQualities = stocks.map((stock) => numeric(stock.setupQuality, input.avgQuality ?? 50));
  const trendQualities = stocks.map((stock) => numeric(stock.trendQuality, input.avgQuality ?? 50));
  const timingQualities = stocks.map((stock) => numeric(stock.timingQuality, input.avgQuality ?? 50));
  const riskPressures = stocks.map((stock) => numeric(stock.riskPressure, input.avgRisk ?? 50));
  const exposures = stocks.map((stock) => numeric(stock.suggestedExposure));
  const historyVolatility = stocks.map((stock) => stdev(historyReturns(stock.history).slice(-30)));
  const avgRisk = numeric(input.avgRisk, mean(riskPressures));
  const avgQuality = numeric(input.avgQuality, mean(setupQualities));
  const confidence = numeric(input.confidence, 50);
  const avgChange = mean(changes);
  const avgAbsChange = mean(absChanges);
  const returnDispersion = stdev(changes);
  const avgVolatility = mean(historyVolatility);
  const positiveRatio = signRatio(changes, "positive");
  const negativeRatio = signRatio(changes, "negative");
  const quoteCoverage = (stocks.filter((stock) => stock.quoteStatus === "available" || numeric(stock.price, NaN) > 0).length / count) * 100;
  const signalCoverage = (stocks.filter((stock) => stock.signalStatus === "provided" || Boolean(stock.signalAction)).length / count) * 100;
  const buyRatio = stocks.filter((stock) => stock.signalAction === "Buy" || stock.allocationAction === "Buy").length / count;
  const sellRatio = stocks.filter((stock) => stock.signalAction === "Sell" || stock.allocationAction === "Sell").length / count;
  const holdRatio = Math.max(0, 1 - buyRatio - sellRatio);
  const signalConsensusRatio = Math.max(buyRatio, sellRatio, holdRatio);
  const exposureConcentration = concentrationScore(exposures);
  const qualityDispersion = stdev([...setupQualities, ...trendQualities, ...timingQualities]);
  const maxAbsChange = absChanges.length ? Math.max(...absChanges) : 0;
  const spreadBps = numeric(input.executionProfile?.spreadBps, 4);
  const slippageBps = numeric(input.executionProfile?.slippageBps, 2);
  const rebalanceThresholdBps = numeric(input.executionProfile?.rebalanceThresholdBps, 50);
  const drawdown = numeric(input.backtestMaxDrawdownPct, avgRisk / 2);
  const sharpe = numeric(input.backtestSharpe, 0);
  const profitFactor = numeric(input.backtestProfitFactor, 0);
  const winRate = numeric(input.backtestWinRatePct, 0);
  const totalReturn = numeric(input.backtestReturnPct, 0);
  const validationPenalty = input.failureFlags.length * 8;
  const freshnessScore = input.staleData ? 25 : 100;
  const backtestEvidence = input.hasBacktestData ? clamp(Math.min(input.backtestTradeCount, 120) / 1.2) : 0;
  const fallbackOverfitRisk = clamp(
    100 -
      backtestEvidence * 0.72 +
      validationPenalty +
      (profitFactor > 4 ? 12 : 0) +
      (winRate > 92 ? 10 : 0) +
      (totalReturn === 0 ? 6 : 0),
  );
  const robustnessScore = numeric(input.robustnessScore, 100 - fallbackOverfitRisk);
  const deploymentReadinessScore = numeric(input.deploymentReadinessScore, robustnessScore);
  const reportedOverfitRisk = numeric(input.robustnessOverfitRisk, fallbackOverfitRisk);
  const robustnessImpliedRisk = clamp(100 - Math.max(robustnessScore, deploymentReadinessScore));
  const diagnosticOverfitRisk = clamp(Math.min(reportedOverfitRisk, fallbackOverfitRisk, robustnessImpliedRisk));
  const overfitRiskTolerance = 30;
  const residualOverfitRisk = clamp(Math.max(0, diagnosticOverfitRisk - overfitRiskTolerance));
  const favorableRegime = clamp(avgQuality * 0.42 + (100 - avgRisk) * 0.34 + input.targetExposure * 0.24);
  const transitionConflict = Math.abs(avgRisk - avgQuality) * 0.45 + Math.abs(input.breadth - input.targetExposure) * 0.35;
  const dataConfidence = clamp((quoteCoverage + signalCoverage + freshnessScore + backtestEvidence) / 4);
  const calibrationSampleSize = Math.max(0, numeric(input.calibrationSampleSize, 0));
  const calibrationCoverage = clamp((calibrationSampleSize / 30) * 100);
  const calibrationRawConfidence = numeric(input.calibrationRawConfidence, confidence);
  const calibrationCalibratedConfidence = numeric(input.calibrationCalibratedConfidence, calibrationRawConfidence);
  const calibrationHistoricalAccuracy = numeric(input.calibrationHistoricalAccuracy, input.hasBacktestData ? winRate : 50);
  const calibrationError = numeric(input.calibrationError, calibrationRawConfidence - calibrationHistoricalAccuracy);
  const calibrationQuality = clamp(100 - Math.abs(calibrationError));
  const calibrationTrustworthiness = numeric(
    input.calibrationTrustworthiness,
    calibrationHistoricalAccuracy * 0.34 + calibrationQuality * 0.34 + calibrationCoverage * 0.18 + (100 - residualOverfitRisk) * 0.14,
  );
  const calibrationDataConfidence = calibrationSampleSize >= 12
    ? dataConfidence
    : Math.min(dataConfidence, 40 + calibrationCoverage * 0.5);
  const decisionConsistency = clamp(
    100 -
      validationPenalty -
      residualOverfitRisk * 0.45 -
      Math.max(0, calibrationRawConfidence - calibrationCalibratedConfidence) * 0.35,
  );
  const outcomeAlignment = clamp(calibrationHistoricalAccuracy * 0.62 + calibrationQuality * 0.38);

  return [
    metric("liquidityStress", avgRisk * 0.58 + (sellRatio * 2800) / 100 + (input.staleData ? 12 : 0) + (input.marketStatus === "Closed" ? 4 : 0), avgRisk, `Risk pressure ${pct(avgRisk)}, sell pressure ${pct(sellRatio * 100)}, freshness ${input.staleData ? "stale" : "fresh"}.`, dataConfidence),
    metric("tailRisk", drawdown * 2.2 + negativeRatio * 24 + Math.max(0, -avgChange) * 3, drawdown, `Drawdown ${drawdown.toFixed(1)}%, negative breadth ${pct(negativeRatio * 100)}, average change ${avgChange.toFixed(2)}%.`, input.hasBacktestData ? dataConfidence : dataConfidence * 0.72),
    metric("volatilityExpansion", avgVolatility * 12 + returnDispersion * 7 + avgAbsChange * 3, avgVolatility.toFixed(2), `30-sample volatility ${avgVolatility.toFixed(2)}, dispersion ${returnDispersion.toFixed(2)}, absolute move ${avgAbsChange.toFixed(2)}%.`, dataConfidence),
    metric("spreadInstability", (spreadBps + slippageBps) * 5 + rebalanceThresholdBps * 0.24 + (100 - quoteCoverage) * 0.22, `${spreadBps + slippageBps} bps`, `Execution cost ${spreadBps + slippageBps} bps, rebalance threshold ${rebalanceThresholdBps} bps, quote coverage ${pct(quoteCoverage)}.`, dataConfidence),
    metric("emotionalVelocity", avgAbsChange * 8 + returnDispersion * 4 + Math.abs(buyRatio - sellRatio) * 24, avgAbsChange.toFixed(2), `Absolute move ${avgAbsChange.toFixed(2)}%, dispersion ${returnDispersion.toFixed(2)}, buy/sell imbalance ${pct(Math.abs(buyRatio - sellRatio) * 100)}.`, dataConfidence),
    metric("momentumOverextension", mean(expectedMoves.map(Math.abs)) * 9 + Math.max(0, avgQuality - 75) * 1.4 + avgAbsChange * 4, mean(expectedMoves.map(Math.abs)).toFixed(2), `Expected-move stretch ${mean(expectedMoves.map(Math.abs)).toFixed(2)}%, quality stretch ${Math.max(0, avgQuality - 75).toFixed(1)}.`, dataConfidence),
    metric("narrativeConcentration", exposureConcentration * 100 + concentrationScore(setupQualities.slice(0, 12)) * 30, exposureConcentration.toFixed(2), `Exposure concentration ${exposureConcentration.toFixed(2)} across suggested positions.`, dataConfidence),
    metric("crowdInstability", sellRatio * 48 + negativeRatio * 35 + avgRisk * 0.25, sellRatio * 100, `Sell pressure ${pct(sellRatio * 100)}, negative breadth ${pct(negativeRatio * 100)}, risk pressure ${pct(avgRisk)}.`, dataConfidence),
    metric("signalConsensus", signalConsensusRatio * 75 + signalCoverage * 0.25, signalConsensusRatio * 100, `Dominant signal share ${pct(signalConsensusRatio * 100)} with signal coverage ${pct(signalCoverage)}.`, dataConfidence),
    metric("signalStability", 100 - qualityDispersion * 1.35 - returnDispersion * 1.4, qualityDispersion.toFixed(2), `Quality dispersion ${qualityDispersion.toFixed(2)} and return dispersion ${returnDispersion.toFixed(2)}.`, dataConfidence),
    metric("trendStrength", mean(trendQualities) * 0.62 + avgQuality * 0.38, mean(trendQualities), `Trend quality ${pct(mean(trendQualities))}, setup quality ${pct(avgQuality)}.`, dataConfidence),
    metric("weightedConfidence", confidence * 0.7 + input.survivalScore * 0.3, confidence, `Live confidence ${pct(confidence)}, strategy reliability ${pct(input.survivalScore)}.`, dataConfidence),
    metric("breadthHealth", input.breadth * 0.68 + positiveRatio * 32, input.breadth, `Participation ${pct(input.breadth)}, positive breadth ${pct(positiveRatio * 100)}.`, dataConfidence),
    metric("crossAssetAlignment", positiveRatio * 52 + Math.max(0, 100 - returnDispersion * 8) * 0.48, positiveRatio * 100, `Positive alignment ${pct(positiveRatio * 100)}, dispersion control ${pct(Math.max(0, 100 - returnDispersion * 8))}.`, dataConfidence),
    metric("portfolioSymmetry", 100 - exposureConcentration * 120, exposureConcentration.toFixed(2), `Suggested exposure concentration ${exposureConcentration.toFixed(2)}.`, dataConfidence),
    metric("informationShock", avgAbsChange * 10 + returnDispersion * 6 + (input.staleData ? 22 : 0), avgAbsChange.toFixed(2), `Absolute move ${avgAbsChange.toFixed(2)}%, dispersion ${returnDispersion.toFixed(2)}, freshness ${input.staleData ? "stale" : "fresh"}.`, dataConfidence),
    metric("informationEfficiency", quoteCoverage * 0.46 + signalCoverage * 0.3 + freshnessScore * 0.24, quoteCoverage, `Quote coverage ${pct(quoteCoverage)}, signal coverage ${pct(signalCoverage)}, freshness ${pct(freshnessScore)}.`, dataConfidence),
    metric("volumeConfirmation", quoteCoverage * 0.42 + signalCoverage * 0.24 + mean(trendQualities) * 0.34, quoteCoverage, `Quote confirmation ${pct(quoteCoverage)}, signal coverage ${pct(signalCoverage)}, trend quality ${pct(mean(trendQualities))}.`, dataConfidence),
    metric("regimeTransitionProbability", transitionConflict + Math.max(0, avgRisk - input.breadth) * 0.35 + returnDispersion * 5, transitionConflict.toFixed(2), `Risk/quality conflict ${Math.abs(avgRisk - avgQuality).toFixed(1)}, breadth/exposure conflict ${Math.abs(input.breadth - input.targetExposure).toFixed(1)}.`, dataConfidence),
    metric("anomalyScore", maxAbsChange * 6 + returnDispersion * 8 + validationPenalty, maxAbsChange.toFixed(2), `Largest move ${maxAbsChange.toFixed(2)}%, dispersion ${returnDispersion.toFixed(2)}, validation flags ${input.failureFlags.length}.`, dataConfidence),
    metric("latentStructureDetection", Math.max(0, 100 - qualityDispersion) * 0.28 + positiveRatio * 26 + avgQuality * 0.32 + signalConsensusRatio * 14, avgQuality, `Quality coherence ${pct(Math.max(0, 100 - qualityDispersion))}, alignment ${pct(positiveRatio * 100)}, consensus ${pct(signalConsensusRatio * 100)}.`, dataConfidence),
    metric("macroPressure", avgRisk * 0.34 + (100 - input.targetExposure) * 0.24 + drawdown * 1.15 + validationPenalty * 0.55, avgRisk, `Risk ${pct(avgRisk)}, target exposure ${pct(input.targetExposure)}, drawdown ${drawdown.toFixed(1)}%, flags ${input.failureFlags.length}.`, dataConfidence),
    metric("capitalRotation", Math.abs(buyRatio - sellRatio) * 45 + returnDispersion * 5 + exposureConcentration * 28, Math.abs(buyRatio - sellRatio) * 100, `Buy/sell rotation ${pct(Math.abs(buyRatio - sellRatio) * 100)}, dispersion ${returnDispersion.toFixed(2)}, concentration ${exposureConcentration.toFixed(2)}.`, dataConfidence),
    metric("regimeEnvironment", favorableRegime, favorableRegime, `Environment blend: quality ${pct(avgQuality)}, risk control ${pct(100 - avgRisk)}, target exposure ${pct(input.targetExposure)}.`, dataConfidence),
    metric("modelConfidence", input.survivalScore * 0.42 + confidence * 0.34 + deploymentReadinessScore * 0.16 + Math.max(0, sharpe) * 5 - validationPenalty * 0.6, input.survivalScore, `Reliability ${pct(input.survivalScore)}, confidence ${pct(confidence)}, Sharpe ${sharpe.toFixed(2)}, deployment readiness ${pct(deploymentReadinessScore)}, flags ${input.failureFlags.length}.`, dataConfidence),
    metric("dataReliability", quoteCoverage * 0.34 + signalCoverage * 0.24 + freshnessScore * 0.22 + backtestEvidence * 0.2, quoteCoverage, `Quote ${pct(quoteCoverage)}, signal ${pct(signalCoverage)}, freshness ${pct(freshnessScore)}, backtest evidence ${pct(backtestEvidence)}.`, dataConfidence),
    metric("historicalAccuracy", calibrationHistoricalAccuracy, calibrationHistoricalAccuracy, `Historical accuracy ${pct(calibrationHistoricalAccuracy)} from ${Math.round(calibrationSampleSize)} calibrated samples.`, calibrationDataConfidence),
    metric("calibrationQuality", calibrationQuality, calibrationError, `Calibration error ${calibrationError.toFixed(1)} points; raw confidence ${pct(calibrationRawConfidence)}, calibrated confidence ${pct(calibrationCalibratedConfidence)}.`, calibrationDataConfidence),
    metric("trustworthiness", calibrationTrustworthiness, calibrationTrustworthiness, `Trustworthiness ${pct(calibrationTrustworthiness)} after calibration, consistency, and uncertainty checks.`, calibrationDataConfidence),
    metric("memoryDepth", calibrationCoverage, calibrationSampleSize, `Calibration memory contains ${Math.round(calibrationSampleSize)} evaluated samples.`, calibrationDataConfidence),
    metric("decisionConsistency", decisionConsistency, decisionConsistency, `Decision consistency after readiness flags, residual overfit risk, and confidence calibration.`, dataConfidence),
    metric("outcomeAlignment", outcomeAlignment, outcomeAlignment, `Outcome alignment combines historical accuracy ${pct(calibrationHistoricalAccuracy)} and calibration quality ${pct(calibrationQuality)}.`, calibrationDataConfidence),
    metric(
      "overfitRisk",
      residualOverfitRisk,
      residualOverfitRisk,
      `Residual risk ${pct(residualOverfitRisk)} after ${pct(overfitRiskTolerance)} production tolerance. Diagnostic risk ${pct(diagnosticOverfitRisk)}; reported risk ${pct(reportedOverfitRisk)}, trades ${input.backtestTradeCount}, flags ${input.failureFlags.length}, profit factor ${profitFactor.toFixed(2)}, win rate ${winRate.toFixed(1)}%, robustness ${pct(robustnessScore)}.`,
      dataConfidence,
    ),
  ];
}

export function buildStocksSynchronization(input: StocksOptimizerMetricSource): SynchronizationInput {
  const quoteAgeMs = input.staleData ? 15 * 60_000 : 10_000;
  const spreadBps = numeric(input.executionProfile?.spreadBps, 4) + numeric(input.executionProfile?.slippageBps, 2);
  const venueState: VenueState = input.staleData ? "STALE" : input.marketStatus === "Closed" ? "CLOSED" : "OPEN";
  return {
    venueState,
    quoteAgeMs,
    websocketLatencyMs: input.staleData ? 900 : 120,
    candleIntegrity: input.hasProvidedSignals ? 92 : 76,
    missingIntervals: input.staleData ? 2 : 0,
    staleTimestamps: input.staleData ? 1 : 0,
    spreadBps,
    liquidityScore: clamp(100 - spreadBps * 4),
  };
}

export function buildStocksLeadershipObservations(stocks: Array<Record<string, any>>, timestamp = Date.now()): ObservationPoint[] {
  return stocks.flatMap((stock) => {
    const id = String(stock.ticker ?? stock.symbol ?? stock.name ?? "unknown");
    const history = Array.isArray(stock.history) ? stock.history.slice(-20) : [numeric(stock.price, 0)];
    return history.map((value, index) => ({
      id,
      timestamp: timestamp - (history.length - index) * 60_000,
      value: numeric(value),
      dimensions: {
        volumeExpansion: numeric(stock.volumeExpansion, 50),
        liquidityQuality: stock.quoteStatus === "available" ? 82 : 48,
        breadthParticipation: numeric(stock.setupQuality, 50),
        sectorSynchronization: numeric(stock.trendQuality, 50),
      },
    }));
  });
}

function historyReturns(history: unknown) {
  if (!Array.isArray(history) || history.length < 2) return [];
  const returns: number[] = [];
  for (let index = 1; index < history.length; index += 1) {
    const previous = numeric(history[index - 1], NaN);
    const current = numeric(history[index], NaN);
    if (previous > 0 && current > 0) returns.push(((current - previous) / previous) * 100);
  }
  return returns;
}

function latestChange(stock: Record<string, any>) {
  const explicit = numeric(stock.changePercent, NaN);
  if (Number.isFinite(explicit)) return explicit;
  const returns = historyReturns(stock.history);
  return returns.length ? returns[returns.length - 1] : 0;
}

function concentrationScore(values: number[]) {
  const positives = values.map((value) => Math.max(0, numeric(value))).filter((value) => value > 0);
  const total = positives.reduce((sum, value) => sum + value, 0);
  if (total <= 0) return 0;
  return positives.reduce((sum, value) => sum + (value / total) ** 2, 0);
}

function pct(value: number) {
  return `${clamp(value).toFixed(0)}%`;
}

function metric(key: string, value: number, raw: number | string | null, detail: string, confidence = 100, unit?: string): MetricInput {
  return { key, value: clamp(value), raw, unit, confidence: clamp(confidence), detail };
}

import type { MetricDescriptor } from "../types";

export class MetricRegistry {
  private readonly descriptors = new Map<string, MetricDescriptor>();

  register(descriptor: MetricDescriptor) {
    this.descriptors.set(descriptor.key, descriptor);
    return this;
  }

  get(key: string) {
    return this.descriptors.get(key);
  }

  all() {
    return Array.from(this.descriptors.values());
  }
}

import { clamp, mean, stdev } from "../math/statistics";

export type CalibrationInput = {
  id?: string;
  timestamp?: string;
  prediction: unknown;
  confidence: number;
  outcome?: unknown;
  metadata?: Record<string, unknown>;
};

export type ReliabilityBucket = {
  minConfidence: number;
  maxConfidence: number;
  sampleSize: number;
  averageConfidence: number;
  actualAccuracy: number;
  calibrationGap: number;
};

export type CalibrationResult = {
  rawConfidence: number;
  calibratedConfidence: number;
  historicalAccuracy: number;
  calibrationError: number;
  brierScore?: number;
  trustworthiness: number;
  sampleSize: number;
  reliabilityBuckets: ReliabilityBucket[];
  warnings: string[];
};

export type CalibrationOptions = {
  minimumSamples?: number;
  sufficientSamples?: number;
  poorCalibrationThreshold?: number;
  overconfidenceThreshold?: number;
  lowTrustworthinessThreshold?: number;
};

export type CalibrationRunInput = {
  current: CalibrationInput;
  history?: CalibrationInput[];
  options?: CalibrationOptions;
};

type EvaluatedRecord = {
  confidence: number;
  correctness: number;
  binaryOutcome?: number;
};

const DEFAULT_OPTIONS = {
  minimumSamples: 5,
  sufficientSamples: 20,
  poorCalibrationThreshold: 20,
  overconfidenceThreshold: 10,
  lowTrustworthinessThreshold: 50,
};

const POSITIVE_LABELS = new Set([
  "success",
  "succeeded",
  "true",
  "correct",
  "positive",
  "passed",
  "pass",
  "approved",
  "yes",
  "win",
  "winning",
]);

const NEGATIVE_LABELS = new Set([
  "failure",
  "failed",
  "false",
  "incorrect",
  "negative",
  "denied",
  "rejected",
  "no",
  "loss",
  "losing",
]);

const PARTIAL_LABELS = new Set(["partial", "mixed", "neutral"]);

export function calibrate(input: CalibrationRunInput): CalibrationResult {
  const options = { ...DEFAULT_OPTIONS, ...(input.options ?? {}) };
  const rawConfidence = normalizeConfidence(input.current.confidence);
  const evaluated = safeArray(input.history).flatMap(evaluateRecord);
  const sampleSize = evaluated.length;
  const historicalAccuracy = roundScore(
    sampleSize ? mean(evaluated.map((record) => record.correctness)) * 100 : 50,
  );
  const averageConfidence = roundScore(
    sampleSize ? mean(evaluated.map((record) => record.confidence)) : 50,
  );
  const calibrationError = roundSignedScore(
    averageConfidence - historicalAccuracy,
  );
  const binaryOutcomes = evaluated.filter(
    (record): record is EvaluatedRecord & { binaryOutcome: number } =>
      record.binaryOutcome === 0 || record.binaryOutcome === 1,
  );
  const brierScore = binaryOutcomes.length
    ? roundRatio(
        mean(
          binaryOutcomes.map(
            (record) => (record.confidence / 100 - record.binaryOutcome) ** 2,
          ),
        ),
      )
    : undefined;
  const reliabilityBuckets = buildReliabilityBuckets(evaluated);
  const trustworthiness = trustworthinessScore({
    evaluated,
    historicalAccuracy,
    calibrationError,
    brierScore,
    sufficientSamples: options.sufficientSamples,
  });
  const calibratedConfidence = calibratedScore({
    rawConfidence,
    historicalAccuracy,
    calibrationError,
    trustworthiness,
    sampleSize,
    minimumSamples: options.minimumSamples,
    sufficientSamples: options.sufficientSamples,
  });
  const warnings = warningsFor({
    evaluated,
    sampleSize,
    calibrationError,
    trustworthiness,
    minimumSamples: options.minimumSamples,
    poorCalibrationThreshold: options.poorCalibrationThreshold,
    overconfidenceThreshold: options.overconfidenceThreshold,
    lowTrustworthinessThreshold: options.lowTrustworthinessThreshold,
  });

  return {
    rawConfidence,
    calibratedConfidence,
    historicalAccuracy,
    calibrationError,
    ...(brierScore == null ? {} : { brierScore }),
    trustworthiness,
    sampleSize,
    reliabilityBuckets,
    warnings,
  };
}

export const calibrateConfidence = calibrate;

function evaluateRecord(record: CalibrationInput): EvaluatedRecord[] {
  const correctness = correctnessFor(record);
  if (correctness == null) return [];
  const binaryOutcome = binaryOutcomeFor(record.outcome);
  return [
    {
      confidence: normalizeConfidence(record.confidence),
      correctness,
      ...(binaryOutcome == null ? {} : { binaryOutcome }),
    },
  ];
}

function correctnessFor(record: CalibrationInput): number | null {
  const explicit = explicitCorrectness(record.outcome);
  if (explicit != null) return explicit;

  const predictionLabel = labelFor(record.prediction);
  const outcomeLabel = labelFor(record.outcome);
  if (predictionLabel && outcomeLabel) {
    if (predictionLabel === outcomeLabel) return 1;
    if (PARTIAL_LABELS.has(outcomeLabel)) return 0.5;
    return 0;
  }

  if (record.outcome !== undefined && primitive(record.prediction)) {
    return Object.is(record.prediction, record.outcome) ? 1 : 0;
  }

  return null;
}

function explicitCorrectness(outcome: unknown): number | null {
  if (typeof outcome === "boolean") return outcome ? 1 : 0;
  if (!outcome || typeof outcome !== "object") return null;
  const object = outcome as Record<string, unknown>;
  const value = object.correct ?? object.success;
  if (typeof value === "boolean") return value ? 1 : 0;
  if (typeof value === "number" && Number.isFinite(value))
    return clamp(value, 0, 1);
  return null;
}

function binaryOutcomeFor(outcome: unknown): number | null {
  if (typeof outcome === "boolean") return outcome ? 1 : 0;
  const label = labelFor(outcome);
  if (!label) return null;
  if (POSITIVE_LABELS.has(label)) return 1;
  if (NEGATIVE_LABELS.has(label)) return 0;
  return null;
}

function labelFor(value: unknown): string | null {
  if (typeof value === "string") return normalizeLabel(value);
  if (!value || typeof value !== "object") return null;
  const object = value as Record<string, unknown>;
  const candidate =
    object.label ??
    object.outcomeLabel ??
    object.expectedOutcome ??
    object.value ??
    object.kind;
  return typeof candidate === "string" ? normalizeLabel(candidate) : null;
}

function normalizeLabel(value: string) {
  const normalized = value.trim().toLowerCase();
  return normalized.length ? normalized : null;
}

function primitive(value: unknown) {
  return (
    value == null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

function buildReliabilityBuckets(evaluated: EvaluatedRecord[]) {
  return Array.from({ length: 10 }, (_, index) => {
    const minConfidence = index * 10;
    const maxConfidence = index === 9 ? 100 : minConfidence + 10;
    const bucketRecords = evaluated.filter((record) =>
      index === 9
        ? record.confidence >= minConfidence && record.confidence <= maxConfidence
        : record.confidence >= minConfidence && record.confidence < maxConfidence,
    );
    const averageConfidence = roundScore(
      bucketRecords.length
        ? mean(bucketRecords.map((record) => record.confidence))
        : 0,
    );
    const actualAccuracy = roundScore(
      bucketRecords.length
        ? mean(bucketRecords.map((record) => record.correctness)) * 100
        : 0,
    );
    return {
      minConfidence,
      maxConfidence,
      sampleSize: bucketRecords.length,
      averageConfidence,
      actualAccuracy,
      calibrationGap: roundSignedScore(averageConfidence - actualAccuracy),
    };
  });
}

function trustworthinessScore(input: {
  evaluated: EvaluatedRecord[];
  historicalAccuracy: number;
  calibrationError: number;
  brierScore?: number;
  sufficientSamples: number;
}) {
  if (!input.evaluated.length) return 35;
  const sampleScore = clamp(
    (input.evaluated.length / Math.max(1, input.sufficientSamples)) * 100,
  );
  const calibrationQuality = clamp(100 - Math.abs(input.calibrationError));
  const consistency = clamp(
    100 - stdev(input.evaluated.map((record) => record.correctness)) * 100,
  );
  const confidenceStability = clamp(
    100 - stdev(input.evaluated.map((record) => record.confidence)),
  );
  const brierQuality =
    input.brierScore == null ? calibrationQuality : clamp(100 - input.brierScore * 100);

  return roundScore(
    input.historicalAccuracy * 0.28 +
      calibrationQuality * 0.24 +
      sampleScore * 0.18 +
      consistency * 0.12 +
      confidenceStability * 0.08 +
      brierQuality * 0.1,
  );
}

function calibratedScore(input: {
  rawConfidence: number;
  historicalAccuracy: number;
  calibrationError: number;
  trustworthiness: number;
  sampleSize: number;
  minimumSamples: number;
  sufficientSamples: number;
}) {
  if (input.sampleSize === 0) return roundScore(input.rawConfidence * 0.85);
  const sampleScore = clamp(
    (input.sampleSize / Math.max(1, input.sufficientSamples)) * 100,
  );
  const evidenceCap = clamp(input.historicalAccuracy + sampleScore * 0.15);
  const overconfidencePenalty = Math.max(0, input.calibrationError) * 0.65;
  const weakHistoryPenalty = Math.max(0, 60 - input.historicalAccuracy) * 0.25;
  const trustPenalty = Math.max(0, 50 - input.trustworthiness) * 0.25;
  let adjusted =
    input.rawConfidence -
    overconfidencePenalty -
    weakHistoryPenalty -
    trustPenalty;
  adjusted = Math.min(adjusted, evidenceCap);
  if (input.sampleSize < input.minimumSamples) {
    adjusted = Math.min(adjusted, input.rawConfidence * 0.85);
  }
  return roundScore(Math.min(input.rawConfidence, clamp(adjusted)));
}

function warningsFor(input: {
  evaluated: EvaluatedRecord[];
  sampleSize: number;
  calibrationError: number;
  trustworthiness: number;
  minimumSamples: number;
  poorCalibrationThreshold: number;
  overconfidenceThreshold: number;
  lowTrustworthinessThreshold: number;
}) {
  const warnings: string[] = [];
  if (input.sampleSize < input.minimumSamples)
    warnings.push("insufficient history");
  if (Math.abs(input.calibrationError) >= input.poorCalibrationThreshold)
    warnings.push("poor calibration");
  if (input.calibrationError >= input.overconfidenceThreshold)
    warnings.push("overconfidence");
  if (
    input.evaluated.length > 1 &&
    stdev(input.evaluated.map((record) => record.correctness)) >= 0.4
  )
    warnings.push("unstable outcomes");
  if (input.trustworthiness < input.lowTrustworthinessThreshold)
    warnings.push("low trustworthiness");
  return warnings;
}

function normalizeConfidence(value: number) {
  if (!Number.isFinite(value)) return 0;
  return roundScore(value <= 1 ? clamp(value * 100) : clamp(value));
}

function safeArray<T>(value: T[] | undefined) {
  return Array.isArray(value) ? value.filter((item) => item != null) : [];
}

function roundScore(value: number) {
  return Math.round(clamp(value) * 100) / 100;
}

function roundSignedScore(value: number) {
  return Math.round(value * 100) / 100;
}

function roundRatio(value: number) {
  return Math.round(Math.max(0, value) * 1_000_000) / 1_000_000;
}

