export type EngineModule = {
  name: string;
  dependencies?: string[];
  run(snapshot: SignalSnapshot): SignalSnapshot | Promise<SignalSnapshot>;
};

export class SignalFrameworkEngine {
  private readonly perception: PerceptionEngine;
  private readonly regimes = new RegimeEngine();
  private readonly journal = new SignalJournal();
  private readonly store: SnapshotStore;
  private readonly modules = new Map<string, EngineModule>();
  private cycle = 0;

  constructor(
    registry: MetricRegistry,
    options: { maxSnapshots?: number; maxMetricHistory?: number } = {},
  ) {
    this.perception = new PerceptionEngine(registry, {
      maxMetricHistory: options.maxMetricHistory,
    });
    this.store = new SnapshotStore(options.maxSnapshots);
  }

  register(module: EngineModule) {
    this.modules.set(module.name, module);
    return this;
  }

  async cycleOnce(context: SignalContext): Promise<Readonly<SignalSnapshot>> {
    const timestamp = context.timestamp ?? Date.now();
    for (const signal of context.signals ?? []) this.journal.record(signal);
    for (const outcome of context.outcomes ?? [])
      this.journal.evaluate(outcome);

    const synchronization = evaluateSynchronization(context.synchronization);
    const rawPerception = this.perception.evaluate(context.metrics, 1);
    const validation = this.journal.snapshot();
    const reflection = reflect(
      buildReflectionInput({
        context,
        timestamp,
        perception: rawPerception,
        synchronization,
        validation,
        metrics: rawPerception.metrics,
        history: this.store.history(),
      }),
    );
    const decision = context.agency?.decision ?? context.decision ?? null;
    const calibration = calibrate(
      buildCalibrationInput({
        context,
        timestamp,
        perception: rawPerception,
        reflection,
        decision,
      }),
    );
    const judgement = context.judgement
      ? evaluateJudgement(
          buildJudgementInput({
            context,
            perception: rawPerception,
            reflection,
            calibration,
            decision,
          }),
        )
      : undefined;
    const discovery = discover(
      buildDiscoveryInput({
        context,
        timestamp,
        perception: rawPerception,
        reflection,
        calibration,
        judgement,
        decision,
      }),
    );
    const recognition = recognizeState(
      buildRecognitionInput({
        context,
        perception: rawPerception,
        reflection,
        calibration,
        discovery,
        judgement,
        decision,
      }),
    );
    const agencyDecision =
      judgement && decision
        ? {
            ...decision,
            confidence: Math.min(decision.confidence ?? judgement.rawConfidence, judgement.adjustedConfidence),
            metadata: {
              ...(decision.metadata ?? {}),
              judgementStatus: judgement.status,
              judgementTrust: judgement.trust,
              judgementAdjustedConfidence: judgement.adjustedConfidence,
            },
          }
        : decision;
    const agency = authorize({
      ...context.agency,
      decision: agencyDecision,
      reflection: context.agency?.reflection ?? reflection,
      calibration: context.agency?.calibration ?? calibration,
    });
    const viability = context.viability || decision
      ? evaluateViability(
          buildViabilityInput({
            context,
            decision,
            calibration,
            agency,
          }),
        )
      : undefined;
    const perception = applyLifecycleSelfAwareness(
      rawPerception,
      reflection,
      calibration,
      agency,
      viability,
    );
    const regime = this.regimes.evaluate(perception.layers, synchronization);
    const diagnostics = evaluateDiagnostics(
      perception.layers,
      synchronization,
      validation,
    );
    const executionReadiness = evaluateExecutionReadiness({
      perceptionScore: perception.compositeScore,
      perceptionConfidence: perception.confidence,
      agreement: perception.agreement,
      regime,
      synchronization,
      diagnostics,
    });
    const rankings = rankLeadership(context.observations);
    const needs = detectNeeds({
      perception: {
        layers: perception.layers,
        compositeScore: perception.compositeScore,
        confidence: perception.confidence,
        agreement: perception.agreement,
      },
      diagnostics,
      synchronization,
      executionReadiness,
      rankings,
    });
    const observationSeries = observationsToSeries(context.observations);
    const opportunities = discoverOpportunities({
      perception: {
        layers: perception.layers,
        compositeScore: perception.compositeScore,
        confidence: perception.confidence,
        agreement: perception.agreement,
      },
      intelligence: {
        readinessScore: executionReadiness.readinessScore,
        trust: diagnostics.trust,
        contradictions: diagnostics.contradictions.length,
        transitionDetected: regime.transitionDetected,
      },
      needs,
      observationSeries,
    });
    const opportunityDensity = evaluateOpportunityDensity({
      candidates: opportunities,
    });
    const events: SignalSnapshot["events"] = [
      {
        type: "cycle.completed",
        timestamp,
        payload: { regime: regime.name, readiness: executionReadiness.state },
      },
      {
        type: "reflection.completed",
        timestamp,
        payload: { reflectionScore: reflection.reflectionScore },
      },
      {
        type: "calibration.completed",
        timestamp,
        payload: {
          calibratedConfidence: calibration.calibratedConfidence,
          trustworthiness: calibration.trustworthiness,
        },
      },
      {
        type: `agency.${agency.status}`,
        timestamp,
        payload: { agencyScore: agency.agencyScore, status: agency.status },
      },
    ];
    events.push({
      type: `discovery.${discovery.status}`,
      timestamp,
      payload: {
        confidence: discovery.confidence,
        maturity: discovery.maturity,
        opportunities: discovery.opportunities.length,
      },
    });
    events.push({
      type: `recognition.${recognition.verdict}`,
      timestamp,
      payload: {
        recognitionScore: recognition.recognitionScore,
        recurrenceConfidence: recognition.recurrenceConfidence,
        noveltyScore: recognition.noveltyScore,
        archetype: recognition.archetype,
      },
    });
    if (judgement) {
      events.push({
        type: `judgement.${judgement.status}`,
        timestamp,
        payload: {
          status: judgement.status,
          trust: judgement.trust,
          adjustedConfidence: judgement.adjustedConfidence,
        },
      });
    }
    if (viability) {
      events.push({
        type: `viability.${viability.verdict}`,
        timestamp,
        payload: {
          score: viability.score,
          verdict: viability.verdict,
          marginOfSafety: viability.marginOfSafety,
        },
      });
    }
    if (regime.transitionDetected) {
      events.push({
        type: "regime.transition",
        timestamp,
        payload: { previous: regime.previous, current: regime.name },
      });
    }
    for (const contradiction of diagnostics.contradictions) {
      events.push({
        type: "diagnostic.contradiction",
        timestamp,
        payload: contradiction,
      });
    }
    for (const need of needs) {
      events.push({ type: "need.detected", timestamp, payload: need });
    }
    for (const opportunity of opportunities.slice(0, 5)) {
      events.push({
        type: "opportunity.discovered",
        timestamp,
        payload: opportunity,
      });
    }

    let snapshot: SignalSnapshot = {
      id: context.id ?? `${timestamp}-${this.cycle + 1}`,
      cycle: ++this.cycle,
      timestamp,
      domain: context.domain ?? "generic",
      context: context.metadata ?? {},
      perception: {
        layers: perception.layers,
        timeframes: perception.timeframes,
        compositeScore: perception.compositeScore,
        confidence: perception.confidence,
        agreement: perception.agreement,
        dominantLayer: perception.dominantLayer,
      },
      reflection,
      calibration,
      judgement,
      discovery,
      recognition,
      decision,
      agency,
      viability,
      regime,
      synchronization,
      diagnostics,
      needs,
      opportunities,
      opportunityDensity,
      confidence: Math.max(
        0,
        Math.min(
          100,
          (perception.confidence + diagnostics.trust + synchronization.score) /
            3,
        ),
      ),
      rankings,
      validation,
      executionReadiness,
      metrics: perception.metrics,
      events,
    };

    for (const module of this.orderedModules()) {
      snapshot = await module.run(snapshot);
    }

    const frozen = immutable(snapshot);
    this.store.append(frozen);
    return frozen;
  }

  history() {
    return this.store.history();
  }

  latest() {
    return this.store.latest();
  }

  private orderedModules() {
    const pending = new Map(this.modules);
    const ordered: EngineModule[] = [];

    while (pending.size) {
      const ready = Array.from(pending.values()).find((module) =>
        (module.dependencies ?? []).every((dependency) =>
          ordered.some((item) => item.name === dependency),
        ),
      );
      if (!ready)
        throw new Error(
          "SignalFrameworkEngine module dependency cycle detected.",
        );
      ordered.push(ready);
      pending.delete(ready.name);
    }

    return ordered;
  }
}

function observationsToSeries(
  observations: SignalContext["observations"] = [],
) {
  const grouped = new Map<string, number[]>();
  for (const observation of observations) {
    const values = grouped.get(observation.id) ?? [];
    values.push(observation.value);
    grouped.set(observation.id, values);
  }
  return Array.from(grouped.entries()).map(([id, values]) => ({ id, values }));
}

type PerceptionEvaluation = ReturnType<PerceptionEngine["evaluate"]>;

function buildReflectionInput(args: {
  context: SignalContext;
  timestamp: number;
  perception: PerceptionEvaluation;
  synchronization: ReturnType<typeof evaluateSynchronization>;
  validation: ReturnType<SignalJournal["snapshot"]>;
  metrics: Record<string, MetricState>;
  history: Readonly<SignalSnapshot>[];
}) {
  const signalById = new Map(
    (args.context.signals ?? []).map((signal) => [signal.id, signal]),
  );
  const derivedPredictions = (args.context.signals ?? []).map((signal) => ({
    id: signal.id,
    timestamp: signal.timestamp,
    confidence: signal.confidence,
    expectedOutcome: signal.expectedDirection,
  }));
  const derivedOutcomes = (args.context.outcomes ?? []).map((outcome) => {
    const signal = signalById.get(outcome.signalId);
    return {
      predictionId: outcome.signalId,
      timestamp: outcome.evaluatedAt,
      label: outcome.realizedDirection,
      ...(signal
        ? { correct: signal.expectedDirection === outcome.realizedDirection }
        : {}),
    };
  });
  const timestampByMetric = metricTimestampByKey(args.context);
  const derivedInputs = Object.values(args.metrics).map((metric) => ({
    key: metric.key,
    value: metric.raw ?? metric.score,
    quality: metric.confidence,
    timestamp:
      metric.key in timestampByMetric
        ? timestampByMetric[metric.key]
        : args.timestamp,
    known: metric.raw != null && metric.confidence > 0,
    status: metric.raw == null || metric.confidence <= 0 ? "unknown" : "known",
  }));
  const supplied = args.context.reflection ?? {};

  return {
    ...supplied,
    predictions: [...derivedPredictions, ...safeArray(supplied.predictions)],
    decisions: [
      ...(args.context.decision ? [args.context.decision] : []),
      ...safeArray(supplied.decisions),
    ],
    outcomes: [...derivedOutcomes, ...safeArray(supplied.outcomes)],
    history: [...snapshotHistory(args.history), ...safeArray(supplied.history)],
    currentState:
      supplied.currentState ??
      reflectionState(args.perception, args.synchronization, args.validation),
    perceptionLayers:
      supplied.perceptionLayers ?? perceptionLayers(args.perception.layers),
    inputs: [...derivedInputs, ...safeArray(supplied.inputs)],
    requiredInputs: supplied.requiredInputs,
    candidateDecisions: supplied.candidateDecisions,
    now: supplied.now ?? args.timestamp,
  };
}

function buildCalibrationInput(args: {
  context: SignalContext;
  timestamp: number;
  perception: PerceptionEvaluation;
  reflection: NonNullable<SignalSnapshot["reflection"]>;
  decision: SignalContext["decision"];
}): CalibrationRunInput {
  const supplied = args.context.calibration ?? {};
  const outcomeBySignalId = new Map(
    (args.context.outcomes ?? []).map((outcome) => [outcome.signalId, outcome]),
  );
  const signalHistory = (args.context.signals ?? []).flatMap((signal) => {
    const outcome = outcomeBySignalId.get(signal.id);
    if (!outcome) return [];
    return [
      {
        id: signal.id,
        timestamp: new Date(signal.timestamp).toISOString(),
        prediction: {
          expectedOutcome: signal.expectedDirection,
          magnitude: signal.expectedMagnitude,
        },
        confidence: signal.confidence,
        outcome: { label: outcome.realizedDirection },
        metadata: { source: "signal-journal" },
      },
    ];
  });

  return {
    current: {
      id: supplied.id ?? args.context.id ?? `calibration-${args.timestamp}`,
      timestamp:
        supplied.timestamp ?? new Date(args.timestamp).toISOString(),
      prediction:
        supplied.prediction ??
        args.decision ??
        {
          compositeScore: args.perception.compositeScore,
          reflectionScore: args.reflection.reflectionScore,
        },
      confidence:
        supplied.confidence ??
        args.decision?.confidence ??
        args.perception.confidence,
      ...(supplied.outcome === undefined ? {} : { outcome: supplied.outcome }),
      metadata: {
        domain: args.context.domain ?? "generic",
        ...(supplied.metadata ?? {}),
      },
    },
    history: [...signalHistory, ...safeArray(supplied.history)],
  };
}

function buildJudgementInput(args: {
  context: SignalContext;
  perception: PerceptionEvaluation;
  reflection: NonNullable<SignalSnapshot["reflection"]>;
  calibration: NonNullable<SignalSnapshot["calibration"]>;
  decision: SignalContext["decision"];
}) {
  const supplied = args.context.judgement ?? {};
  const outcomeBySignalId = new Map(
    (args.context.outcomes ?? []).map((outcome) => [outcome.signalId, outcome]),
  );
  const journalOutcomes = (args.context.signals ?? []).flatMap((signal) => {
    const outcome = outcomeBySignalId.get(signal.id);
    if (!outcome) return [];

    return [
      {
        id: signal.id,
        state: {
          domain: args.context.domain ?? "generic",
          expectedDirection: signal.expectedDirection,
          regime: signal.regime,
        },
        decision: {
          confidence: signal.confidence,
          expectedMagnitude: signal.expectedMagnitude,
        },
        outcome: {
          label: outcome.realizedDirection,
          value: outcome.realizedMagnitude,
          success: outcome.realizedDirection === signal.expectedDirection,
        },
        confidence: signal.confidence,
        metadata: { source: "signal-journal" },
      },
    ];
  });
  const decision = args.decision;

  return {
    currentState: supplied.currentState ?? {
      domain: args.context.domain ?? "generic",
      compositeScore: args.perception.compositeScore,
      perceptionConfidence: args.perception.confidence,
      agreement: args.perception.agreement,
      dominantLayer: args.perception.dominantLayer,
      reflectionScore: args.reflection.reflectionScore,
      calibratedConfidence: args.calibration.calibratedConfidence,
    },
    proposedDecision: supplied.proposedDecision ?? {
      ...(decision ?? {}),
      rawConfidence: decision?.confidence ?? args.calibration.rawConfidence,
      calibratedConfidence: args.calibration.calibratedConfidence,
    },
    proposedAction: supplied.proposedAction,
    historicalOutcomes: [...journalOutcomes, ...safeArray(supplied.historicalOutcomes)],
    traces: safeArray(supplied.traces),
    context: {
      domain: args.context.domain ?? "generic",
      rawConfidence: decision?.confidence ?? args.calibration.rawConfidence,
      calibratedConfidence: args.calibration.calibratedConfidence,
      ...(supplied.context ?? {}),
    },
  };
}

function buildDiscoveryInput(args: {
  context: SignalContext;
  timestamp: number;
  perception: PerceptionEvaluation;
  reflection: NonNullable<SignalSnapshot["reflection"]>;
  calibration: NonNullable<SignalSnapshot["calibration"]>;
  judgement?: SignalSnapshot["judgement"];
  decision: SignalContext["decision"];
}): DiscoveryInput {
  const supplied = args.context.discovery ?? {};
  const decision = args.decision;
  const state = {
    domain: args.context.domain ?? "generic",
    compositeScore: args.perception.compositeScore,
    perceptionConfidence: args.perception.confidence,
    agreement: args.perception.agreement,
    dominantLayer: args.perception.dominantLayer,
    reflectionScore: args.reflection.reflectionScore,
    calibratedConfidence: args.calibration.calibratedConfidence,
    judgementStatus: args.judgement?.status ?? "not-provided",
    judgementTrust: args.judgement?.trust ?? 0,
    ...(supplied.state ?? {}),
  };
  const candidates = [
    ...(decision
      ? [{
          id: decision.id ?? args.context.id ?? "candidate:decision",
          label: decision.intent ?? decision.type ?? "Proposed decision",
          score: decision.confidence ?? args.calibration.calibratedConfidence,
          confidence: args.calibration.calibratedConfidence,
          evidence: ["Decision candidate supplied to the framework cycle."],
        }]
      : []),
    ...safeArray(supplied.candidates),
  ];
  const evidence = [
    {
      id: "perception:agreement",
      label: "Perception agreement",
      direction: "support" as const,
      strength: args.perception.agreement,
      confidence: args.perception.confidence,
      group: "perception",
    },
    {
      id: "calibration:confidence",
      label: "Calibrated confidence",
      direction: "support" as const,
      strength: args.calibration.calibratedConfidence,
      confidence: args.calibration.trustworthiness,
      group: "calibration",
    },
    ...(args.judgement
      ? [{
          id: "judgement:trust",
          label: "Judgement trust",
          direction: args.judgement.status === "blocked" ? "contradict" as const : "support" as const,
          strength: args.judgement.trust,
          confidence: args.judgement.reliability,
          group: "judgement",
        }]
      : []),
    ...safeArray(supplied.evidence),
  ];
  const priorOutcomes = [
    ...safeArray(supplied.priorOutcomes),
    ...safeArray(args.context.judgement?.historicalOutcomes).map((outcome) => ({
      id: outcome.id,
      state: outcome.state ?? outcome.currentState,
      outcome: outcome.success === true ? "positive" : outcome.success === false ? "negative" : "neutral",
      score: outcome.score ?? outcome.value,
      confidence: outcome.confidence,
    })),
  ];

  return {
    subjectId: supplied.subjectId ?? args.context.id,
    domain: supplied.domain ?? args.context.domain ?? "generic",
    state,
    candidates,
    evidence,
    historicalStates: safeArray(supplied.historicalStates),
    priorOutcomes,
    constraints: safeArray(supplied.constraints),
    now: supplied.now ?? new Date(args.timestamp).toISOString(),
  };
}

function buildRecognitionInput(args: {
  context: SignalContext;
  perception: PerceptionEvaluation;
  reflection: NonNullable<SignalSnapshot["reflection"]>;
  calibration: NonNullable<SignalSnapshot["calibration"]>;
  discovery: NonNullable<SignalSnapshot["discovery"]>;
  judgement?: SignalSnapshot["judgement"];
  decision: SignalContext["decision"];
}): RecognitionInput {
  const supplied = args.context.recognition ?? {};
  const outcomeBySignalId = new Map(
    (args.context.outcomes ?? []).map((outcome) => [outcome.signalId, outcome]),
  );
  const signalOutcomeSamples = (args.context.signals ?? []).flatMap((signal) => {
    const outcome = outcomeBySignalId.get(signal.id);
    if (!outcome) return [];

    return [{
      id: signal.id,
      state: {
        domain: args.context.domain ?? "generic",
        expectedDirection: signal.expectedDirection,
        regime: signal.regime,
      },
      features: {
        confidence: signal.confidence,
        expectedMagnitude: signal.expectedMagnitude,
      },
      outcome: outcome.realizedDirection === signal.expectedDirection ? "positive" : "negative",
      value: outcome.realizedMagnitude,
      confidence: signal.confidence,
    }];
  });
  const judgementOutcomeSamples = safeArray(args.context.judgement?.historicalOutcomes).map((outcome) => ({
    id: outcome.id,
    state: outcome.state ?? outcome.currentState,
    features: outcome.decision ?? outcome.proposedDecision,
    context: outcome.context,
    outcome: outcome.outcome,
    result: outcome.result,
    value: outcome.value ?? outcome.score ?? outcome.returnPct,
    success: outcome.success,
    confidence: outcome.confidence,
  }));

  return {
    ...supplied,
    currentState: supplied.currentState ?? {
      domain: args.context.domain ?? "generic",
      compositeScore: args.perception.compositeScore,
      perceptionConfidence: args.perception.confidence,
      agreement: args.perception.agreement,
      dominantLayer: args.perception.dominantLayer,
      reflectionScore: args.reflection.reflectionScore,
      calibratedConfidence: args.calibration.calibratedConfidence,
      decisionType: args.decision?.type,
      decisionConfidence: args.decision?.confidence,
    },
    perception: supplied.perception ?? {
      compositeScore: args.perception.compositeScore,
      confidence: args.perception.confidence,
      agreement: args.perception.agreement,
    },
    discovery: supplied.discovery ?? args.discovery,
    judgement: supplied.judgement ?? args.judgement,
    historicalStates: [
      ...safeArray(supplied.historicalStates),
      ...safeArray(args.context.discovery?.historicalStates),
    ],
    outcomeSamples: [
      ...safeArray(supplied.outcomeSamples),
      ...signalOutcomeSamples,
      ...judgementOutcomeSamples,
    ],
  };
}

function buildViabilityInput(args: {
  context: SignalContext;
  decision: SignalContext["decision"];
  calibration: NonNullable<SignalSnapshot["calibration"]>;
  agency: NonNullable<SignalSnapshot["agency"]>;
}): ViabilityInput {
  const supplied = args.context.viability ?? {};
  const decision = args.decision;
  const metadata = decision?.metadata ?? {};
  const constraints = supplied.constraints ?? agencyConstraints(args.agency);

  return {
    targetRef:
      supplied.targetRef ??
      decision?.id ??
      args.context.id ??
      `${args.context.domain ?? "generic"}:action`,
    actionRef: supplied.actionRef ?? decision?.intent ?? decision?.type,
    decisionRef: supplied.decisionRef ?? decision?.id,
    expectedBenefit:
      supplied.expectedBenefit ??
      firstFinite(metadata.expectedBenefit, decision?.expectedValue, decision?.impact, decision?.confidence, args.agency.commitmentConfidence),
    expectedCost:
      supplied.expectedCost ??
      firstFinite(metadata.expectedCost, metadata.cost, Math.max(0, 100 - args.agency.executionReadiness), 0),
    expectedRisk:
      supplied.expectedRisk ??
      firstFinite(decision?.risk, metadata.expectedRisk, metadata.risk, 100 - args.agency.constraintEvaluation.score),
    uncertainty:
      supplied.uncertainty ??
      firstFinite(decision?.uncertainty, metadata.uncertainty, 100 - args.agency.commitmentConfidence),
    confidence:
      supplied.confidence ??
      firstFinite(args.agency.commitmentConfidence, args.calibration.calibratedConfidence, decision?.confidence),
    constraints,
    minMarginOfSafety: supplied.minMarginOfSafety,
    thresholds: supplied.thresholds,
    weights: supplied.weights,
    context: {
      domain: args.context.domain ?? "generic",
      ...(supplied.context ?? {}),
    },
  };
}

function agencyConstraints(agency: NonNullable<SignalSnapshot["agency"]>): ViabilityConstraintInput[] {
  return agency.constraintEvaluation.constraints.map((constraint) => ({
    id: constraint.id,
    label: constraint.label,
    type: constraint.hard ? "hard" : "soft",
    hard: constraint.hard,
    passed: constraint.passed,
    severity: constraint.severity,
    reason: constraint.reason,
  }));
}

function applyLifecycleSelfAwareness(
  perception: PerceptionEvaluation,
  reflection: NonNullable<SignalSnapshot["reflection"]>,
  calibration: NonNullable<SignalSnapshot["calibration"]>,
  agency: NonNullable<SignalSnapshot["agency"]>,
  viability?: ViabilityResult,
): PerceptionEvaluation {
  const baseLayer = perception.layers.selfAwareness;
  const lifecycleContributors = [
    lifecycleContribution(
      "reflectionScore",
      "Reflection score",
      reflection.reflectionScore,
    ),
    lifecycleContribution(
      "calibration",
      "Reflection calibration",
      reflection.calibration.score,
    ),
    lifecycleContribution(
      "historicalAccuracy",
      "Historical accuracy",
      calibration.historicalAccuracy,
    ),
    lifecycleContribution(
      "calibrationQuality",
      "Calibration quality",
      100 - Math.abs(calibration.calibrationError),
    ),
    lifecycleContribution(
      "trustworthiness",
      "Trustworthiness",
      calibration.trustworthiness,
    ),
    lifecycleContribution(
      "memoryDepth",
      "Memory depth",
      Math.min(100, calibration.sampleSize * 5),
    ),
    lifecycleContribution(
      "knowledgeCompleteness",
      "Knowledge completeness",
      reflection.knowledgeCompleteness.score,
    ),
    lifecycleContribution("agencyScore", "Agency score", agency.agencyScore),
    lifecycleContribution(
      "commitmentConfidence",
      "Commitment confidence",
      agency.commitmentConfidence,
    ),
    lifecycleContribution(
      "executionReadiness",
      "Execution readiness",
      agency.executionReadiness,
    ),
    ...(viability
      ? [
          lifecycleContribution("viabilityScore", "Viability score", viability.score),
          lifecycleContribution(
            "viabilityMarginOfSafety",
            "Viability margin of safety",
            clamp(50 + viability.marginOfSafety * 100),
          ),
        ]
      : []),
  ];
  const lifecycleScore = mean(
    lifecycleContributors.map((item) => item.contribution),
  );
  const score = clamp(baseLayer.score * 0.34 + lifecycleScore * 0.66);
  const confidence = clamp(
    mean([
      baseLayer.confidence,
      reflection.reflectionScore,
      calibration.trustworthiness,
      agency.commitmentConfidence,
    ]),
  );
  const selfAwareness: PerceptionLayerState = {
    ...baseLayer,
    score,
    confidence,
    uncertainty: clamp(100 - confidence),
    classification: classifyPerceptionLayer("selfAwareness", score),
    contributors: [...lifecycleContributors, ...baseLayer.contributors],
  };
  const layers = { ...perception.layers, selfAwareness };
  const layerScores = PERCEPTION_LAYER_ORDER.map((key) => layers[key].score);
  const timeframes = {
    intraday: timeframe("intraday", "Intraday", [
      layers.survival.score,
      layers.emotion.score,
      layers.information.score,
      layers.selfAwareness.score,
    ]),
    swing: timeframe("swing", "Swing", [
      layers.conviction.score,
      layers.harmony.score,
      layers.intuition.score,
      layers.selfAwareness.score,
    ]),
    macro: timeframe("macro", "Macro", [
      layers.macroContext.score,
      layers.survival.score,
      layers.harmony.score,
      layers.selfAwareness.score,
    ]),
  };
  const dominantLayer = PERCEPTION_LAYER_ORDER.reduce(
    (best, key) => (layers[key].score > layers[best].score ? key : best),
    "survival",
  );

  return {
    ...perception,
    layers,
    timeframes,
    compositeScore: clamp(mean(layerScores)),
    confidence: clamp(
      mean(PERCEPTION_LAYER_ORDER.map((key) => layers[key].confidence)),
    ),
    agreement: clamp(100 - stdev(layerScores) * 1.35),
    dominantLayer,
  };
}

function reflectionState(
  perception: PerceptionEvaluation,
  synchronization: ReturnType<typeof evaluateSynchronization>,
  validation: ReturnType<SignalJournal["snapshot"]>,
) {
  return {
    compositeScore: perception.compositeScore,
    confidence: perception.confidence,
    agreement: perception.agreement,
    synchronization: synchronization.score,
    calibrationAccuracy: validation.calibrationAccuracy,
    confidenceRealism: validation.confidenceRealism,
    evaluatedSignals: validation.evaluatedSignals,
    ...Object.fromEntries(
      PERCEPTION_LAYER_ORDER.map((key) => [
        `layer.${key}`,
        perception.layers[key].score,
      ]),
    ),
  };
}

function snapshotHistory(history: Readonly<SignalSnapshot>[]) {
  return history.map((snapshot) => ({
    id: snapshot.id,
    timestamp: snapshot.timestamp,
    state: {
      compositeScore: snapshot.perception.compositeScore,
      confidence: snapshot.perception.confidence,
      agreement: snapshot.perception.agreement,
      synchronization: snapshot.synchronization.score,
          reflectionScore: snapshot.reflection?.reflectionScore,
          calibratedConfidence: snapshot.calibration?.calibratedConfidence,
          trustworthiness: snapshot.calibration?.trustworthiness,
          agencyScore: snapshot.agency?.agencyScore,
      ...Object.fromEntries(
        PERCEPTION_LAYER_ORDER.map((key) => [
          `layer.${key}`,
          snapshot.perception.layers[key].score,
        ]),
      ),
    },
  }));
}

function perceptionLayers(layers: Record<string, PerceptionLayerState>) {
  return Object.fromEntries(
    Object.entries(layers).map(([key, layer]) => [
      key,
      {
        key,
        score: layer.score,
        confidence: layer.confidence,
        uncertainty: layer.uncertainty,
      },
    ]),
  );
}

function metricTimestampByKey(context: SignalContext) {
  return Object.fromEntries(
    (context.metrics ?? []).map((metric) => [metric.key, metric.timestamp]),
  );
}

function lifecycleContribution(
  metricKey: string,
  label: string,
  value: number,
) {
  return {
    metricKey,
    label,
    value,
    contribution: clamp(value),
    weight: 1,
    raw: value,
    detail: `${label} from the generic Reflection/Agency lifecycle.`,
    polarity: "direct" as const,
  };
}

function timeframe(
  key: "intraday" | "swing" | "macro",
  label: string,
  values: number[],
): TimeframeState {
  return {
    key,
    label,
    score: clamp(mean(values)),
    agreement: clamp(100 - stdev(values) * 1.25),
  };
}

function safeArray<T>(value: T[] | undefined) {
  return Array.isArray(value) ? value.filter((item) => item != null) : [];
}

function firstFinite(...values: unknown[]) {
  for (const value of values) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

import { clamp, mean } from "../math/statistics";
import type { CalibrationResult } from "../calibration/engine";
import type { ReflectionResult } from "../reflection/engine";

export type AgencyStatus =
  | "approved"
  | "denied"
  | "deferred"
  | "escalated"
  | "requires-review"
  | "limited"
  | "rollback"
  | string;

export type AuthorityLevelName =
  | "none"
  | "observer"
  | "operator"
  | "supervisor"
  | "autonomous"
  | string;

export type DecisionResult = {
  id?: string;
  type?: string;
  intent?: string;
  confidence?: number;
  uncertainty?: number;
  risk?: number;
  expectedValue?: number;
  impact?: number;
  metadata?: Record<string, unknown>;
};

export type AgencyAuthorityInput = {
  level?: AuthorityLevelName;
  score?: number;
  metadata?: Record<string, unknown>;
};

export type AuthorityModel =
  | Record<AuthorityLevelName, number>
  | Array<{ level: AuthorityLevelName; score: number }>;

export type AgencyConstraint = {
  id: string;
  label?: string;
  type?:
    | "risk-budget"
    | "resource-budget"
    | "execution-limit"
    | "time-limit"
    | "rate-limit"
    | "quality-requirement"
    | string;
  value?: number;
  limit?: number;
  min?: number;
  max?: number;
  operator?: "<" | "<=" | ">" | ">=" | "==" | "!=";
  passed?: boolean;
  hard?: boolean;
  severity?: "low" | "medium" | "high" | "critical" | string;
  weight?: number;
  reason?: string;
  statusOnViolation?: AgencyStatus;
  metadata?: Record<string, unknown>;
};

export type HumanReviewPolicy = {
  mode?:
    | "always-review"
    | "review-above-threshold"
    | "review-when-confidence-low"
    | "review-when-uncertainty-high"
    | "fully-autonomous"
    | "never"
    | string;
  threshold?: number;
  confidenceThreshold?: number;
  uncertaintyThreshold?: number;
  statusWhenRequired?: AgencyStatus;
  reason?: string;
};

export type AgencyInput = {
  decision?: DecisionResult | null;
  calibration?: Partial<CalibrationResult> & {
    warnings?: string[];
  };
  reflection?:
    | Partial<ReflectionResult>
    | { reflectionScore?: number; recommendedConfidenceCap?: number };
  authority?: AgencyAuthorityInput | AuthorityLevelName;
  requiredAuthority?: AuthorityLevelName | number;
  authorityModel?: AuthorityModel;
  constraints?: AgencyConstraint[];
  reviewPolicy?: HumanReviewPolicy;
  execution?: {
    readiness?: number;
    available?: boolean;
    blocked?: boolean;
    rollbackRequested?: boolean;
    reasons?: string[];
    metadata?: Record<string, unknown>;
  };
  thresholds?: {
    minDecisionConfidence?: number;
    maxUncertainty?: number;
    minReflectionScore?: number;
    minAgencyScore?: number;
  };
  statusOnInsufficientAuthority?: AgencyStatus;
  statusOnConstraintViolation?: AgencyStatus;
  statusOnLowConfidence?: AgencyStatus;
};

export type AuthorityEvaluation = {
  providedLevel: AuthorityLevelName;
  requiredLevel: AuthorityLevelName | number;
  providedScore: number;
  requiredScore: number;
  sufficient: boolean;
  score: number;
  reason: string;
};

export type ConstraintEvaluation = {
  score: number;
  passed: boolean;
  violations: Array<{
    id: string;
    label: string;
    type: string;
    severity: string;
    hard: boolean;
    reason: string;
    statusOnViolation?: AgencyStatus;
  }>;
  constraints: Array<{
    id: string;
    label: string;
    type: string;
    passed: boolean;
    severity: string;
    hard: boolean;
    score: number;
    reason: string;
  }>;
};

export type ReviewRequirement = {
  required: boolean;
  mode: string;
  status: AgencyStatus;
  reason: string;
};

export type AgencyResult = {
  agencyScore: number;
  commitmentConfidence: number;
  executionReadiness: number;
  status: AgencyStatus;
  rawConfidence: number;
  calibratedConfidence: number;
  trustworthiness: number;
  calibrationWarnings: string[];
  agency: {
    action: AgencyStatus;
    rawConfidence: number;
    calibratedConfidence: number;
    trustworthiness: number;
    calibrationWarnings: string[];
  };
  authorityEvaluation: AuthorityEvaluation;
  constraintEvaluation: ConstraintEvaluation;
  reviewRequirement: ReviewRequirement;
  reasons: string[];
  audit: {
    componentScores: Record<string, number>;
    weights: Record<string, number>;
    thresholds: Record<string, number>;
    formulas: string[];
    statusResolution: string[];
  };
};

type EvaluatedConstraint = ConstraintEvaluation["constraints"][number] & {
  weight: number;
  statusOnViolation?: AgencyStatus;
};

const DEFAULT_AUTHORITY: Record<string, number> = {
  none: 0,
  observer: 25,
  operator: 50,
  supervisor: 75,
  autonomous: 100,
};

const DEFAULT_WEIGHTS = {
  authority: 0.18,
  constraints: 0.22,
  uncertaintyControl: 0.16,
  reflectionQuality: 0.18,
  decisionConfidence: 0.14,
  executionReadiness: 0.12,
};

export function authorize(input: AgencyInput): AgencyResult {
  const rawDecision = normalizeDecision(input.decision);
  const calibration = normalizeCalibration(input.calibration, rawDecision.confidence);
  const decision = {
    ...rawDecision,
    confidence: Math.min(rawDecision.confidence, calibration.calibratedConfidence),
  };
  const thresholds = normalizeThresholds(input.thresholds);
  const reflectionScore = normalizeReflectionScore(input.reflection);
  const uncertainty = normalizeScore(
    decision.uncertainty,
    Math.max(0, 100 - decision.confidence),
  );
  const authorityEvaluation = evaluateAuthority(
    input.authority,
    input.requiredAuthority,
    input.authorityModel,
  );
  const constraintEvaluation = evaluateConstraints(input.constraints);
  const reviewRequirement = evaluateReviewRequirement(
    input.reviewPolicy,
    decision,
    reflectionScore,
    uncertainty,
  );
  const baseExecutionReadiness = normalizeScore(
    input.execution?.readiness,
    mean([
      authorityEvaluation.score,
      constraintEvaluation.score,
      reflectionScore,
      decision.confidence,
      100 - uncertainty,
    ]),
  );
  const executionReadiness = capReadiness(baseExecutionReadiness, {
    reviewRequired: reviewRequirement.required,
    constraintEvaluation,
    executionBlocked: input.execution?.blocked === true,
  });
  const componentScores = {
    authority: authorityEvaluation.score,
    constraints: constraintEvaluation.score,
    uncertaintyControl: clamp(100 - uncertainty),
    reflectionQuality: reflectionScore,
    decisionConfidence: decision.confidence,
    executionReadiness,
  };
  const agencyScore = weightedScore(componentScores, DEFAULT_WEIGHTS);
  const commitmentConfidence = clamp(
    mean([
      decision.confidence,
      reflectionScore,
      authorityEvaluation.score,
      constraintEvaluation.score,
      100 - uncertainty,
    ]),
  );
  const statusResolution: string[] = [];
  const status = resolveStatus({
    input,
    decision,
    thresholds,
    reflectionScore,
    uncertainty,
    agencyScore,
    executionReadiness,
    authorityEvaluation,
    constraintEvaluation,
    reviewRequirement,
    statusResolution,
  });

  return {
    agencyScore,
    commitmentConfidence,
    executionReadiness,
    status,
    rawConfidence: calibration.rawConfidence,
    calibratedConfidence: decision.confidence,
    trustworthiness: calibration.trustworthiness,
    calibrationWarnings: calibration.warnings,
    agency: {
      action: status,
      rawConfidence: calibration.rawConfidence,
      calibratedConfidence: decision.confidence,
      trustworthiness: calibration.trustworthiness,
      calibrationWarnings: calibration.warnings,
    },
    authorityEvaluation,
    constraintEvaluation,
    reviewRequirement,
    reasons: reasonsFor({
      input,
      decision,
      thresholds,
      reflectionScore,
      uncertainty,
      agencyScore,
      executionReadiness,
      authorityEvaluation,
      constraintEvaluation,
      reviewRequirement,
      status,
    }),
    audit: {
      componentScores,
      weights: DEFAULT_WEIGHTS,
      thresholds,
      formulas: [
        "calibrated decision confidence = min(raw decision confidence, calibrated confidence)",
        "commitmentConfidence = mean(calibrated decision confidence, reflection quality, authority score, constraint compliance, uncertainty control)",
        "executionReadiness = readiness input or mean core governance components, capped by review and blocking conditions",
        "agencyScore = weighted mean of authority, constraints, uncertainty control, reflection quality, calibrated decision confidence, and execution readiness",
      ],
      statusResolution,
    },
  };
}

export function commit(input: AgencyInput): AgencyResult {
  return authorize(input);
}

function normalizeDecision(decision: DecisionResult | null | undefined) {
  return {
    id: decision?.id ?? "decision",
    type: decision?.type ?? "generic",
    intent: decision?.intent ?? "",
    confidence: normalizeScore(decision?.confidence, 0),
    uncertainty: decision?.uncertainty,
    risk: normalizeScore(decision?.risk, 0),
    impact: normalizeScore(decision?.impact ?? decision?.expectedValue, 0),
    present: decision != null,
  };
}

function normalizeCalibration(
  calibration: AgencyInput["calibration"],
  fallbackConfidence: number,
) {
  const rawConfidence = normalizeScore(
    calibration?.rawConfidence,
    fallbackConfidence,
  );
  const calibratedConfidence = normalizeScore(
    calibration?.calibratedConfidence,
    rawConfidence,
  );
  return {
    rawConfidence,
    calibratedConfidence,
    trustworthiness: normalizeScore(calibration?.trustworthiness, 100),
    warnings: safeArray(calibration?.warnings),
  };
}

function normalizeThresholds(thresholds: AgencyInput["thresholds"] = {}) {
  return {
    minDecisionConfidence: normalizeScore(thresholds.minDecisionConfidence, 0),
    maxUncertainty: normalizeScore(thresholds.maxUncertainty, 100),
    minReflectionScore: normalizeScore(thresholds.minReflectionScore, 0),
    minAgencyScore: normalizeScore(thresholds.minAgencyScore, 0),
  };
}

function normalizeReflectionScore(reflection: AgencyInput["reflection"]) {
  return normalizeScore(reflection?.reflectionScore, 50);
}

function evaluateAuthority(
  authority: AgencyInput["authority"],
  requiredAuthority: AgencyInput["requiredAuthority"],
  authorityModel: AuthorityModel | undefined,
): AuthorityEvaluation {
  const model = normalizeAuthorityModel(authorityModel);
  const providedLevel =
    typeof authority === "string" ? authority : (authority?.level ?? "none");
  const providedScore = normalizeScore(
    typeof authority === "string"
      ? model[providedLevel]
      : (authority?.score ?? model[providedLevel]),
    model[providedLevel] ?? 0,
  );
  const requiredLevel = requiredAuthority ?? "observer";
  const requiredScore =
    typeof requiredLevel === "number"
      ? normalizeScore(requiredLevel, 0)
      : normalizeScore(model[requiredLevel], 0);
  const sufficient = providedScore >= requiredScore;
  const score =
    requiredScore === 0 ? 100 : clamp((providedScore / requiredScore) * 100);

  return {
    providedLevel,
    requiredLevel,
    providedScore,
    requiredScore,
    sufficient,
    score,
    reason: sufficient
      ? `Authority ${providedLevel} satisfies required authority ${String(requiredLevel)}.`
      : `Authority ${providedLevel} is below required authority ${String(requiredLevel)}.`,
  };
}

function normalizeAuthorityModel(authorityModel: AuthorityModel | undefined) {
  const model = { ...DEFAULT_AUTHORITY };
  if (Array.isArray(authorityModel)) {
    for (const entry of authorityModel)
      model[entry.level] = normalizeScore(entry.score, 0);
  } else if (authorityModel && typeof authorityModel === "object") {
    for (const [level, score] of Object.entries(authorityModel))
      model[level] = normalizeScore(score, 0);
  }
  return model;
}

function evaluateConstraints(
  constraints: AgencyConstraint[] = [],
): ConstraintEvaluation {
  const evaluated = safeArray(constraints).map(evaluateConstraint);
  if (evaluated.length === 0) {
    return {
      score: 100,
      passed: true,
      violations: [],
      constraints: [],
    };
  }

  const weightedTotal = evaluated.reduce((sum, item) => sum + item.weight, 0);
  const score = clamp(
    evaluated.reduce((sum, item) => sum + item.score * item.weight, 0) /
      weightedTotal,
  );
  const violations = evaluated
    .filter((item) => !item.passed)
    .map((item) => ({
      id: item.id,
      label: item.label,
      type: item.type,
      severity: item.severity,
      hard: item.hard,
      reason: item.reason,
      ...(item.statusOnViolation
        ? { statusOnViolation: item.statusOnViolation }
        : {}),
    }));

  return {
    score,
    passed: violations.length === 0,
    violations,
    constraints: evaluated.map(
      ({ weight: _weight, statusOnViolation: _statusOnViolation, ...item }) =>
        item,
    ),
  };
}

function evaluateConstraint(constraint: AgencyConstraint): EvaluatedConstraint {
  const id = String(constraint.id || "constraint");
  const label = constraint.label ?? id;
  const type = constraint.type ?? "custom";
  const severity = normalizeSeverity(constraint.severity);
  const hard =
    constraint.hard ?? (severity === "high" || severity === "critical");
  const passed = constraint.passed ?? compareConstraint(constraint);
  const score = passed ? 100 : violationScore(severity, hard);
  const reason =
    constraint.reason ?? (passed ? `${label} passed.` : `${label} failed.`);

  return {
    id,
    label,
    type,
    passed,
    severity,
    hard,
    score,
    reason,
    weight: Math.max(0.1, numeric(constraint.weight, severityWeight(severity))),
    ...(constraint.statusOnViolation
      ? { statusOnViolation: constraint.statusOnViolation }
      : {}),
  };
}

function compareConstraint(constraint: AgencyConstraint) {
  const hasValue = Number.isFinite(Number(constraint.value));
  const value = numeric(constraint.value, 0);
  const operator = constraint.operator ?? defaultOperator(constraint);

  if (
    !hasValue &&
    constraint.limit == null &&
    constraint.min == null &&
    constraint.max == null
  )
    return false;
  if (constraint.min != null && value < numeric(constraint.min, value))
    return false;
  if (constraint.max != null && value > numeric(constraint.max, value))
    return false;
  if (constraint.limit == null) return true;

  const limit = numeric(constraint.limit, value);
  if (operator === "<") return value < limit;
  if (operator === "<=") return value <= limit;
  if (operator === ">") return value > limit;
  if (operator === ">=") return value >= limit;
  if (operator === "==") return value === limit;
  if (operator === "!=") return value !== limit;
  return value <= limit;
}

function defaultOperator(constraint: AgencyConstraint) {
  return constraint.type === "quality-requirement" ? ">=" : "<=";
}

function evaluateReviewRequirement(
  policy: HumanReviewPolicy | undefined,
  decision: ReturnType<typeof normalizeDecision>,
  reflectionScore: number,
  uncertainty: number,
): ReviewRequirement {
  const mode = normalizeMode(policy?.mode ?? "review-when-confidence-low");
  const status = policy?.statusWhenRequired ?? "requires-review";
  const confidenceThreshold = normalizeScore(
    policy?.confidenceThreshold ?? policy?.threshold,
    50,
  );
  const uncertaintyThreshold = normalizeScore(
    policy?.uncertaintyThreshold ?? policy?.threshold,
    60,
  );
  const impactThreshold = normalizeScore(policy?.threshold, 80);
  const required =
    mode === "always-review" ||
    (mode === "review-above-threshold" &&
      Math.max(decision.risk, decision.impact) >= impactThreshold) ||
    (mode === "review-when-confidence-low" &&
      decision.confidence < confidenceThreshold) ||
    (mode === "review-when-uncertainty-high" &&
      uncertainty > uncertaintyThreshold) ||
    (mode === "default-review" &&
      (decision.confidence < confidenceThreshold ||
        uncertainty > uncertaintyThreshold ||
        reflectionScore < 50));

  return {
    required,
    mode,
    status,
    reason:
      policy?.reason ??
      (required
        ? `Human review required by ${mode}.`
        : `Human review not required by ${mode}.`),
  };
}

function normalizeMode(mode: string) {
  const normalized = mode
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
  if (normalized === "always-review" || normalized === "always")
    return "always-review";
  if (
    normalized === "review-above-threshold" ||
    normalized === "above-threshold"
  )
    return "review-above-threshold";
  if (
    normalized === "review-when-confidence-low" ||
    normalized === "confidence-low" ||
    normalized === "low-confidence"
  )
    return "review-when-confidence-low";
  if (
    normalized === "review-when-uncertainty-high" ||
    normalized === "uncertainty-high" ||
    normalized === "high-uncertainty"
  )
    return "review-when-uncertainty-high";
  if (
    normalized === "fully-autonomous" ||
    normalized === "autonomous" ||
    normalized === "never"
  )
    return "fully-autonomous";
  return "default-review";
}

function capReadiness(
  readiness: number,
  input: {
    reviewRequired: boolean;
    constraintEvaluation: ConstraintEvaluation;
    executionBlocked: boolean;
  },
) {
  let capped = readiness;
  if (input.reviewRequired) capped = Math.min(capped, 70);
  if (input.constraintEvaluation.violations.some((violation) => violation.hard))
    capped = Math.min(capped, 35);
  if (input.executionBlocked) capped = 0;
  return clamp(capped);
}

function resolveStatus(input: {
  input: AgencyInput;
  decision: ReturnType<typeof normalizeDecision>;
  thresholds: ReturnType<typeof normalizeThresholds>;
  reflectionScore: number;
  uncertainty: number;
  agencyScore: number;
  executionReadiness: number;
  authorityEvaluation: AuthorityEvaluation;
  constraintEvaluation: ConstraintEvaluation;
  reviewRequirement: ReviewRequirement;
  statusResolution: string[];
}): AgencyStatus {
  if (input.input.execution?.rollbackRequested === true) {
    input.statusResolution.push("Execution requested rollback.");
    return "rollback";
  }

  if (!input.decision.present) {
    input.statusResolution.push("No decision was supplied.");
    return "deferred";
  }

  if (!input.authorityEvaluation.sufficient) {
    const status = input.input.statusOnInsufficientAuthority ?? "denied";
    input.statusResolution.push("Authority is insufficient.");
    return status;
  }

  const overrideViolation = input.constraintEvaluation.violations.find(
    (violation) => violation.statusOnViolation,
  );
  if (overrideViolation?.statusOnViolation) {
    input.statusResolution.push(
      `Constraint ${overrideViolation.id} requested ${overrideViolation.statusOnViolation}.`,
    );
    return overrideViolation.statusOnViolation;
  }

  const hardViolation = input.constraintEvaluation.violations.find(
    (violation) => violation.hard,
  );
  if (hardViolation) {
    const status = input.input.statusOnConstraintViolation ?? "denied";
    input.statusResolution.push(`Hard constraint ${hardViolation.id} failed.`);
    return status;
  }

  if (input.decision.confidence < input.thresholds.minDecisionConfidence) {
    const status = input.input.statusOnLowConfidence ?? "deferred";
    input.statusResolution.push("Decision confidence is below threshold.");
    return status;
  }

  if (
    input.uncertainty > input.thresholds.maxUncertainty ||
    input.reflectionScore < input.thresholds.minReflectionScore
  ) {
    input.statusResolution.push("Uncertainty or reflection threshold failed.");
    return "deferred";
  }

  if (input.reviewRequirement.required) {
    input.statusResolution.push("Human review policy requires review.");
    return input.reviewRequirement.status;
  }

  if (!input.constraintEvaluation.passed) {
    input.statusResolution.push(
      "Only non-hard constraints failed; proceeding with limits.",
    );
    return "limited";
  }

  if (
    input.executionReadiness <= 0 ||
    input.agencyScore < input.thresholds.minAgencyScore
  ) {
    input.statusResolution.push(
      "Execution readiness or agency score is insufficient.",
    );
    return "deferred";
  }

  input.statusResolution.push("All agency gates passed.");
  return "approved";
}

function reasonsFor(input: {
  input: AgencyInput;
  decision: ReturnType<typeof normalizeDecision>;
  thresholds: ReturnType<typeof normalizeThresholds>;
  reflectionScore: number;
  uncertainty: number;
  agencyScore: number;
  executionReadiness: number;
  authorityEvaluation: AuthorityEvaluation;
  constraintEvaluation: ConstraintEvaluation;
  reviewRequirement: ReviewRequirement;
  status: AgencyStatus;
}) {
  const reasons = [
    input.authorityEvaluation.reason,
    input.reviewRequirement.reason,
    `Decision confidence is ${formatPercent(input.decision.confidence)} after calibration.`,
    `Reflection quality is ${formatPercent(input.reflectionScore)}.`,
    `Uncertainty is ${formatPercent(input.uncertainty)}.`,
    `Execution readiness is ${formatPercent(input.executionReadiness)}.`,
  ];

  if (input.input.calibration) {
    const rawConfidence = normalizeScore(
      input.input.calibration.rawConfidence,
      input.decision.confidence,
    );
    const calibratedConfidence = input.decision.confidence;
    if (rawConfidence - calibratedConfidence >= 10) {
      reasons.push(
        "Agency became more conservative because calibrated confidence is materially below raw confidence.",
      );
    }
    for (const warning of safeArray(input.input.calibration.warnings))
      reasons.push(`Calibration warning: ${warning}.`);
  }

  for (const violation of input.constraintEvaluation.violations)
    reasons.push(violation.reason);
  for (const reason of input.input.execution?.reasons ?? [])
    reasons.push(reason);
  if (input.status === "approved") reasons.push("Agency approved commitment.");
  if (input.status === "limited")
    reasons.push("Agency limited commitment due to non-hard constraints.");
  if (input.status === "denied") reasons.push("Agency denied commitment.");
  if (input.status === "deferred") reasons.push("Agency deferred commitment.");
  if (input.status === "escalated")
    reasons.push("Agency escalated commitment.");
  if (input.status === "rollback") reasons.push("Agency requested rollback.");
  return unique(reasons);
}

function weightedScore(
  scores: Record<keyof typeof DEFAULT_WEIGHTS, number>,
  weights: Record<keyof typeof DEFAULT_WEIGHTS, number>,
) {
  const entries = Object.entries(weights) as Array<
    [keyof typeof DEFAULT_WEIGHTS, number]
  >;
  const totalWeight = entries.reduce((sum, [, weight]) => sum + weight, 0);
  return clamp(
    entries.reduce((sum, [key, weight]) => sum + scores[key] * weight, 0) /
      totalWeight,
  );
}

function normalizeSeverity(value: unknown) {
  const severity = String(value ?? "medium").toLowerCase();
  if (
    severity === "low" ||
    severity === "medium" ||
    severity === "high" ||
    severity === "critical"
  )
    return severity;
  return "medium";
}

function severityWeight(severity: string) {
  if (severity === "critical") return 1.5;
  if (severity === "high") return 1.25;
  if (severity === "low") return 0.75;
  return 1;
}

function violationScore(severity: string, hard: boolean) {
  if (hard && (severity === "critical" || severity === "high")) return 0;
  if (severity === "critical") return 10;
  if (severity === "high") return 35;
  if (severity === "low") return 75;
  return 55;
}

function normalizeScore(value: unknown, fallback: number) {
  const numberValue = numeric(value, fallback);
  return clamp(
    numberValue >= 0 && numberValue <= 1 ? numberValue * 100 : numberValue,
  );
}

function numeric(value: unknown, fallback: number) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

function safeArray<T>(value: T[] | undefined) {
  return Array.isArray(value) ? value.filter((item) => item != null) : [];
}

function unique<T>(values: T[]) {
  return Array.from(new Set(values));
}

function formatPercent(value: number) {
  return `${Math.round(clamp(value))}%`;
}

import { clamp, mean } from "../math/statistics";
import type { Contradiction, DiagnosticsState, PerceptionLayerState, SynchronizationState, ValidationState } from "../types";

export function evaluateDiagnostics(
  layers: Record<string, PerceptionLayerState>,
  synchronization: SynchronizationState,
  validation: ValidationState,
): DiagnosticsState {
  const contradictions = detectContradictions(layers, synchronization);
  const contradictionDensity = clamp(contradictions.reduce((sum, item) => sum + item.severity, 0) / 4);
  const historicalReliability = clamp(mean([validation.calibrationAccuracy, validation.confidenceRealism, synchronization.score]));
  const overfitMetric = layers.selfAwareness.contributors.find((item) => item.metricKey === "overfitRisk");
  const overfitProbability = clamp(Number(overfitMetric?.raw ?? overfitMetric?.value ?? 50));
  const uncertainty = clamp(mean(Object.values(layers).map((layer) => layer.uncertainty)) + contradictionDensity * 0.22);
  const confidenceDecay = clamp((100 - synchronization.dataFreshness) * 0.38 + contradictionDensity * 0.24 + overfitProbability * 0.18);
  const predictionCalibration = validation.evaluatedSignals > 0 ? validation.calibrationAccuracy : clamp(100 - overfitProbability * 0.45);
  const modelConfidence = clamp(layers.selfAwareness.score - confidenceDecay * 0.35);
  const trust = clamp(mean([modelConfidence, predictionCalibration, historicalReliability, synchronization.score]) - contradictionDensity * 0.38);

  return {
    modelConfidence,
    predictionCalibration,
    overfitProbability,
    contradictionDensity,
    uncertainty,
    confidenceDecay,
    historicalReliability,
    trust,
    contradictions,
  };
}

function detectContradictions(layers: Record<string, PerceptionLayerState>, sync: SynchronizationState): Contradiction[] {
  const contradictions: Contradiction[] = [];
  addIf(contradictions, layers.harmony.score > 68 && lowMetric(layers.harmony, "breadthHealth"), {
    key: "harmony_without_participation",
    description: "High harmony conflicts with weak participation evidence.",
    severity: 68,
    evidence: { harmony: layers.harmony.score, breadthHealth: metricValue(layers.harmony, "breadthHealth") },
  });
  addIf(contradictions, layers.conviction.score > 68 && lowMetric(layers.information, "volumeConfirmation"), {
    key: "trend_without_volume_confirmation",
    description: "Strong conviction lacks information confirmation.",
    severity: 62,
    evidence: { conviction: layers.conviction.score, volumeConfirmation: metricValue(layers.information, "volumeConfirmation") },
  });
  addIf(contradictions, highMetric(layers.conviction, "signalConsensus") && lowMetric(layers.harmony, "breadthHealth"), {
    key: "consensus_without_breadth",
    description: "High consensus is not supported by broad participation.",
    severity: 58,
    evidence: { signalConsensus: metricValue(layers.conviction, "signalConsensus"), breadthHealth: metricValue(layers.harmony, "breadthHealth") },
  });
  addIf(contradictions, layers.survival.score < 35 && sync.spreadIrregularity > 55, {
    key: "low_volatility_unstable_spreads",
    description: "Low structural stress conflicts with unstable spread conditions.",
    severity: 54,
    evidence: { survival: layers.survival.score, spreadIrregularity: sync.spreadIrregularity },
  });
  return contradictions.map((item) => ({
    ...item,
    confidenceImpact: clamp(item.severity * 0.34),
    readinessImpact: clamp(item.severity * 0.42),
  }));
}

function addIf(items: Contradiction[], condition: boolean, item: Omit<Contradiction, "confidenceImpact" | "readinessImpact">) {
  if (condition) items.push({ ...item, confidenceImpact: 0, readinessImpact: 0 });
}

function metricValue(layer: PerceptionLayerState, key: string) {
  return layer.contributors.find((item) => item.metricKey === key)?.contribution ?? 0;
}

function lowMetric(layer: PerceptionLayerState, key: string) {
  return metricValue(layer, key) < 42;
}

function highMetric(layer: PerceptionLayerState, key: string) {
  return metricValue(layer, key) > 68;
}

/* c8 ignore start */
export type DiscoveryStatus =
  | "none"
  | "detected"
  | "emerging"
  | "strengthening"
  | "eligible"
  | "sized"
  | "active"
  | "closed";
/* c8 ignore stop */

export type DiscoveryEvidenceDirection = "support" | "contradict" | "neutral";

export type DiscoveryCandidate = {
  id?: string;
  candidateId?: string;
  subjectId?: string;
  label?: string;
  kind?: string;
  score?: number;
  strength?: number;
  confidence?: number;
  trust?: number;
  maturity?: number;
  readiness?: number;
  lifecycleStatus?: DiscoveryStatus | string;
  status?: DiscoveryStatus | string;
  previousScore?: number | null;
  velocity?: number;
  persistence?: number;
  evidenceIds?: string[];
  evidence?: string[];
  missingEvidence?: string[];
  invalidationConditions?: string[];
  metadata?: Record<string, unknown>;
};

export type DiscoveryEvidence = {
  id?: string;
  candidateId?: string;
  label?: string;
