const CONCEPT_LABEL: Record<OpportunityType, string> = {
  emergence: "Emergence",
  acceleration: "Acceleration",
  compression: "Compression",
  expansion: "Expansion",
  alignment: "Alignment",
  divergence: "Divergence",
  persistence: "Persistence",
  transition: "Transition",
};

/**
 * Opportunity Discovery surfaces candidates before a domain adapter decides
 * what to do with them.
 *
 * The framework is built around reusable structural concepts: emergence,
 * acceleration, compression, expansion, alignment, divergence, persistence,
 * and transition. It does not contain trading terms or domain assumptions.
 */
export function discoverOpportunities(input: OpportunityDiscoveryInput): OpportunityCandidate[] {
  const candidates: OpportunityCandidate[] = [];

  for (const seed of input.seeds ?? []) {
    candidates.push(fromSeed(seed, input.explorerFindings));
  }

  for (const series of input.observationSeries ?? []) {
    const candidate = fromSeries(series.id, series.values, input.explorerFindings);
    if (candidate) candidates.push(candidate);
  }

  const global = globalCandidates(input);
  for (const candidate of global) {
    candidates.push(applyFindings(candidate, input.explorerFindings));
  }

  return dedupe(candidates)
    .filter((candidate) => candidate.strength > 0)
    .sort((left, right) => {
      const strengthDelta = right.strength - left.strength;
      /* c8 ignore next */
      return strengthDelta === 0 ? left.opportunityId.localeCompare(right.opportunityId) : strengthDelta;
    });
}

function fromSeed(seed: OpportunitySeed, findings: DiscoveryFinding[] | undefined): OpportunityCandidate {
  return applyFindings({
    opportunityId: seed.opportunityId,
    type: seed.type,
    strength: round(clamp(seed.strength)),
    confidence: round(clamp(seed.confidence)),
    evidence: seed.evidence.slice(),
    emerging: seed.emerging ?? seed.strength >= 45,
    persistent: seed.persistent ?? false,
  }, findings);
}

function fromSeries(
  id: string,
  values: number[],
  findings: DiscoveryFinding[] | undefined,
): OpportunityCandidate | null {
  const usable = values.filter(Number.isFinite);
  if (usable.length < 3) return null;

  const first = usable[0];
  const latest = usable[usable.length - 1];
  const previous = usable[usable.length - 2];
  const beforePrevious = usable[usable.length - 3];
  const totalMove = latest - first;
  const latestMove = latest - previous;
  const priorMove = previous - beforePrevious;
  const acceleration = latestMove - priorMove;
  const variability = stdev(usable);
  const positiveSteps = usable.slice(1).filter((value, index) => value >= usable[index]).length;
  const persistence = positiveSteps / (usable.length - 1);
  const type = typeForSeries(totalMove, acceleration, variability, persistence);
  const strength = clamp(Math.abs(totalMove) * 3 + Math.max(0, acceleration) * 4 + persistence * 28 + Math.max(0, 18 - variability));
  const evidence = [
    `${CONCEPT_LABEL[type]} detected across ${usable.length} observations.`,
    `Latest value ${latest.toFixed(2)} versus starting value ${first.toFixed(2)}.`,
  ];

  return applyFindings({
    opportunityId: `${id}:${type}`,
    type,
    strength: round(strength),
    confidence: round(clamp(45 + usable.length * 4 - variability)),
    evidence,
    emerging: totalMove > 0 || acceleration > 0,
    persistent: persistence >= 0.66,
  }, findings);
}

function typeForSeries(totalMove: number, acceleration: number, variability: number, persistence: number): OpportunityType {
  if (acceleration >= 3) return "acceleration";
  if (variability <= 2.5 && totalMove >= 0) return "compression";
  if (persistence >= 0.75) return "persistence";
  if (totalMove > 0) return "emergence";
  return "divergence";
}

function globalCandidates(input: OpportunityDiscoveryInput): OpportunityCandidate[] {
  const perception = input.perception;
  const intelligence = input.intelligence;
  const candidates: OpportunityCandidate[] = [];
  const composite = score(perception?.compositeScore, 50);
  const confidence = score(perception?.confidence, 50);
  const agreement = score(perception?.agreement, 50);
  const layerScores = Object.values(perception?.layers ?? {}).map((layer) => score(layer.score, 50));
  const layerMomentum = Object.values(perception?.layers ?? {}).map((layer) => number(layer.momentum));
  const averageMomentum = mean(layerMomentum);
  const dispersion = stdev(layerScores);
  const needs = input.needs ?? [];

  if (composite >= 62 && agreement >= 58) {
    candidates.push(candidate("system:alignment", "alignment", mean([composite, agreement, confidence]), confidence, [
      "Perception score, confidence, and agreement are aligned.",
    ]));
  }

  if (composite >= 68 && averageMomentum > 0) {
    candidates.push(candidate("system:expansion", "expansion", composite + averageMomentum * 0.4, confidence, [
      "Composite perception is expanding with positive layer momentum.",
    ]));
  }

  if (dispersion <= 8 && agreement >= 55) {
    candidates.push(candidate("system:compression", "compression", 70 - dispersion * 2 + agreement * 0.2, confidence, [
      "Layer dispersion is compressed while agreement remains constructive.",
    ]));
  }

  if ((intelligence?.contradictions ?? 0) > 0 || hasNeed(needs, "wait")) {
    /* c8 ignore next */
    candidates.push(candidate("system:divergence", "divergence", 45 + (intelligence?.contradictions ?? 0) * 8, confidence, [
      "Contradictory evidence is active and may resolve into a transition.",
    ], false));
  }

  if (intelligence?.transitionDetected || hasNeed(needs, "discover-opportunities")) {
    candidates.push(candidate("system:transition", "transition", mean([composite, confidence, 60]), confidence, [
      "The system is moving through a detectable state transition.",
    ]));
  }

  return candidates;
}

function candidate(
  opportunityId: string,
  type: OpportunityType,
  strength: number,
  confidence: number,
  evidence: string[],
  emerging = true,
): OpportunityCandidate {
  return {
    opportunityId,
    type,
    strength: round(clamp(strength)),
    confidence: round(clamp(confidence)),
    evidence,
    emerging,
    persistent: type === "persistence" || type === "alignment",
  };
}

function applyFindings(
  candidate: OpportunityCandidate,
  findings: DiscoveryFinding[] | undefined,
): OpportunityCandidate {
  const matching = (findings ?? []).filter((finding) => finding.feedsOpportunityTypes.includes(candidate.type));
  if (!matching.length) return candidate;

  const boost = Math.min(12, mean(matching.map((finding) => finding.confidence)) * 0.08);
  return {
    ...candidate,
    strength: round(clamp(candidate.strength + boost)),
    confidence: round(clamp(candidate.confidence + boost * 0.6)),
    evidence: [
      ...candidate.evidence,
      ...matching.map((finding) => `Explorer finding: ${finding.pattern}.`),
    ],
  };
}

function dedupe(candidates: OpportunityCandidate[]) {
  const best = new Map<string, OpportunityCandidate>();
  for (const candidate of candidates) {
    const existing = best.get(candidate.opportunityId);
    if (!existing || candidate.strength > existing.strength) best.set(candidate.opportunityId, candidate);
  }
  return Array.from(best.values());
}

function hasNeed(needs: DetectedNeed[], category: DetectedNeed["category"]) {
  return needs.some((need) => need.category === category);
}

function score(value: unknown, fallback: number) {
  const parsed = Number(value);
  return clamp(Number.isFinite(parsed) ? parsed : fallback);
}

function number(value: unknown) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

/* c8 ignore start */
function round(value: number) {
  return Number(value.toFixed(2));
}
/* c8 ignore stop */

import { clamp, mean, numeric, stdev } from "../math/statistics";
import { normalizeMetric, type NormalizationMemory } from "../metrics/normalization";
import type { MetricInput, MetricState, PerceptionLayerKey, PerceptionLayerState, TimeframeState } from "../types";
import { classifyPerceptionLayer, PERCEPTION_LAYER_DEFINITIONS, PERCEPTION_LAYER_ORDER } from "./layers";
import { MetricRegistry } from "../metrics/registry";

export type PerceptionEngineOptions = {
  maxMetricHistory?: number;
};

export class PerceptionEngine {
  private readonly metricHistory: NormalizationMemory = new Map();
  private readonly previousLayers = new Map<PerceptionLayerKey, number>();
  private readonly maxMetricHistory: number;

  constructor(private readonly registry: MetricRegistry, options: PerceptionEngineOptions = {}) {
    this.maxMetricHistory = options.maxMetricHistory ?? 180;
  }

  evaluate(inputs: MetricInput[], regimeVolatilityScale = 1) {
    const inputMap = new Map(inputs.map((input) => [input.key, input]));
    const metrics: Record<string, MetricState> = {};

    for (const descriptor of this.registry.all()) {
      const input = inputMap.get(descriptor.key) ?? {
        key: descriptor.key,
        value: 0,
        raw: null,
        confidence: 0,
        detail: "Metric unavailable.",
      };
      const score = clamp(numeric(input.value));
      const normalization = normalizeMetric(
        descriptor.key,
        score,
        this.metricHistory,
        this.maxMetricHistory,
        regimeVolatilityScale,
      );

      metrics[descriptor.key] = {
        key: descriptor.key,
        label: descriptor.label,
        description: descriptor.description,
        raw: input.raw ?? score,
        unit: input.unit ?? descriptor.unit,
        score: normalization.boundedScore,
        confidence: clamp(input.confidence ?? 100),
        detail: input.detail,
        normalization,
        layers: descriptor.layerMappings,
      };
    }

    const layers = {} as Record<PerceptionLayerKey, PerceptionLayerState>;

    for (const layerKey of PERCEPTION_LAYER_ORDER) {
      const definition = PERCEPTION_LAYER_DEFINITIONS[layerKey];
      const contributors = Object.values(metrics)
        .flatMap((metricState) =>
          metricState.layers
            .filter((mapping) => mapping.layer === layerKey)
            .map((mapping) => {
              const polarity = mapping.polarity ?? "direct";
              const contribution = polarity === "inverse" ? 100 - metricState.score : metricState.score;
              return {
                metricKey: metricState.key,
                label: metricState.label,
                value: metricState.score,
                contribution,
                weight: mapping.weight,
                raw: metricState.raw,
                unit: metricState.unit,
                detail: metricState.detail,
                polarity,
              };
            }),
        )
        .sort((a, b) => b.weight * b.contribution - a.weight * a.contribution);

      const weightTotal = contributors.reduce((sum, item) => sum + item.weight, 0) || 1;
      const score = clamp(contributors.reduce((sum, item) => sum + item.contribution * item.weight, 0) / weightTotal);
      const confidence = clamp(
        contributors.reduce((sum, item) => sum + metrics[item.metricKey].confidence * item.weight, 0) / weightTotal,
      );
      const previousScore = this.previousLayers.get(layerKey) ?? score;
      this.previousLayers.set(layerKey, score);

      layers[layerKey] = {
        ...definition,
        score,
        confidence,
        uncertainty: clamp(100 - confidence),
        momentum: score - previousScore,
        classification: classifyPerceptionLayer(layerKey, score),
        contributors,
      };
    }

    const layerScores = PERCEPTION_LAYER_ORDER.map((key) => layers[key].score);
    const compositeScore = clamp(mean(layerScores));
    const confidence = clamp(mean(PERCEPTION_LAYER_ORDER.map((key) => layers[key].confidence)));
    const dominantLayer = PERCEPTION_LAYER_ORDER.reduce(
      (best, key) => (layers[key].score > layers[best].score ? key : best),
      "survival",
    );
    const agreement = clamp(100 - stdev(layerScores) * 1.35);

    const timeframes: Record<"intraday" | "swing" | "macro", TimeframeState> = {
      intraday: timeframe("intraday", "Intraday", [layers.survival.score, layers.emotion.score, layers.information.score, layers.selfAwareness.score]),
      swing: timeframe("swing", "Swing", [layers.conviction.score, layers.harmony.score, layers.intuition.score, layers.selfAwareness.score]),
      macro: timeframe("macro", "Macro", [layers.macroContext.score, layers.survival.score, layers.harmony.score, layers.selfAwareness.score]),
    };

    return {
      layers,
      timeframes,
      compositeScore,
      confidence,
      agreement,
      dominantLayer,
      metrics,
    };
  }
}

function timeframe(key: "intraday" | "swing" | "macro", label: string, values: number[]): TimeframeState {
  return {
    key,
    label,
    score: clamp(mean(values)),
    agreement: clamp(100 - stdev(values) * 1.25),
  };
}

import { clamp, mean, percentileRank, stdev } from "../math/statistics";
import type { NormalizationState } from "../types";

export type NormalizationMemory = Map<string, number[]>;

export function normalizeMetric(
  key: string,
  score: number,
  memory: NormalizationMemory,
  maxHistory: number,
  regimeVolatilityScale = 1,
): NormalizationState {
  const history = memory.get(key) ?? [];
  const nextHistory = [...history, clamp(score)].slice(-maxHistory);
  memory.set(key, nextHistory);

  const average = mean(nextHistory);
  const sigma = stdev(nextHistory);
  const zScore = sigma > 0 ? (score - average) / sigma : 0;
  const percentileScore = nextHistory.length > 1 ? percentileRank(nextHistory, score) : clamp(score);
  const zScoreNormalized = clamp(50 + zScore * 14);
  const volatilityAdjustedScore = clamp(score - sigma * 0.16 * regimeVolatilityScale + Math.abs(score - average) * 0.08);
  const boundedScore = clamp(
    score * 0.46 +
      percentileScore * 0.24 +
      zScoreNormalized * 0.18 +
      volatilityAdjustedScore * 0.12,
  );

  return {
    zScore,
    zScoreNormalized,
    percentileScore,
    volatilityAdjustedScore,
    boundedScore,
  };
}

