export function resolveCommitment(input: ResolveInput = {}): ResolveOutput {
  const thresholds = { ...DEFAULT_THRESHOLDS, ...(input.thresholds ?? {}) };
  const normalized = normalizeInput(input);
  const traces = buildTraces(normalized, thresholds);
  const resolveScore = roundScore(weightedScore(traces));
  const requiredScore = roundScore(clamp(thresholds.minCommitScore));
  const missingEvidence = missingEvidenceFor(input, normalized, thresholds);
  const unlockConditions = unlockConditionsFor(input, normalized, thresholds);
  const invalidationConditions = invalidationConditionsFor(input, normalized, thresholds);
  const humanReviewRequired = humanReviewRequiredFor(input, normalized);
  const context: ResolveContext = {
    input,
    normalized,
    thresholds,
    resolveScore,
    requiredScore,
    traces,
    missingEvidence,
    unlockConditions,
    invalidationConditions,
    humanReviewRequired,
  };
  const decision = decisionFor(context);
  const commitmentLevel = commitmentLevelFor(input, decision, resolveScore, requiredScore);

  return {
    decision,
    commitmentLevel,
    resolveScore,
    requiredScore,
    humanReviewRequired,
    missingEvidence,
    unlockConditions,
    invalidationConditions,
    explanation: explanationFor(input, decision, commitmentLevel, context),
    traces,
    metadata: {
      module: "resolve",
      version: "v1",
      createdAt: createdAtFor(input),
    },
  };
}

export const evaluateResolve = resolveCommitment;
export const resolveActionCommitment = resolveCommitment;

function buildTraces(input: NormalizedResolveInput, thresholds: ResolveThresholds): ResolveTrace[] {
  const recommendationScore = recommendationScoreFor(input.agencyRecommendation);
  const agencyTrust = valueOrFallback(input.agencyTrust, 40);
  const agencyScore = Math.min(agencyTrust, recommendationScore);
  const overfitSafety = 100 - valueOrFallback(input.overfitRisk, thresholds.maxOverfitRisk);
  const riskSafety = 100 - valueOrFallback(input.riskScore, thresholds.maxRiskScore);
  const beliefStability = 100 - valueOrFallback(input.beliefFragility, thresholds.maxBeliefFragility);

  return [
    trace("agency", "Agency approval", input.agencyTrust, agencyScore, TRACE_WEIGHTS.agency, thresholds.minAgencyTrust, agencyScore >= thresholds.minAgencyTrust, input.agencyRecommendation || "missing"),
    trace("trust", "Trust score", input.trustScore, valueOrFallback(input.trustScore, 40), TRACE_WEIGHTS.trust, thresholds.minTrustScore, valueOrFallback(input.trustScore, 0) >= thresholds.minTrustScore, "Trust must already permit commitment."),
    trace("confidence", "Calibrated confidence", input.calibratedConfidence, confidenceScore(input), TRACE_WEIGHTS.confidence, thresholds.minCalibratedConfidence, valueOrFallback(input.calibratedConfidence, 0) >= thresholds.minCalibratedConfidence, "Raw confidence cannot outrun calibrated confidence."),
    trace("judgement", "Judgement reliability", input.judgementReliability, valueOrFallback(input.judgementReliability, 40), TRACE_WEIGHTS.judgement, thresholds.minJudgementReliability, valueOrFallback(input.judgementReliability, 0) >= thresholds.minJudgementReliability, "Similar states must justify the action."),
    trace("stability", "Outcome stability", input.outcomeStability, valueOrFallback(input.outcomeStability, 40), TRACE_WEIGHTS.stability, 60, valueOrFallback(input.outcomeStability, 0) >= 60, "Outcomes should be stable enough to rely on."),
    trace("data", "Data reliability", input.dataReliability, valueOrFallback(input.dataReliability, 40), TRACE_WEIGHTS.data, thresholds.minDataReliability, valueOrFallback(input.dataReliability, 0) >= thresholds.minDataReliability, "Weak data cannot support commitment."),
    trace("risk", "Risk safety", input.riskScore, riskSafety, TRACE_WEIGHTS.risk, 100 - thresholds.maxRiskScore, valueOrFallback(input.riskScore, 100) <= thresholds.maxRiskScore, "Risk must stay inside the commitment boundary."),
    trace("overfit", "Overfit safety", input.overfitRisk, overfitSafety, TRACE_WEIGHTS.overfit, 100 - thresholds.maxOverfitRisk, valueOrFallback(input.overfitRisk, 100) <= thresholds.maxOverfitRisk, "Overfit risk must stay below the policy cap."),
    trace("belief", "Belief stability", input.beliefFragility, beliefStability, TRACE_WEIGHTS.belief, 100 - thresholds.maxBeliefFragility, valueOrFallback(input.beliefFragility, 100) <= thresholds.maxBeliefFragility, "Fragile belief should not be treated as commitment."),
  ];
}

function normalizeInput(input: ResolveInput): NormalizedResolveInput {
  return {
    agencyRecommendation: normalizeToken(input.agencyRecommendation),
    agencyTrust: optionalScore(input.agencyTrust),
    trustScore: optionalScore(input.trustScore),
    calibratedConfidence: optionalScore(input.calibratedConfidence),
    rawConfidence: optionalScore(input.rawConfidence),
    judgementReliability: optionalScore(input.judgementReliability),
    outcomeStability: optionalScore(input.outcomeStability),
    overfitRisk: optionalScore(input.overfitRisk),
    riskScore: optionalScore(input.riskScore),
    dataReliability: optionalScore(input.dataReliability),
    beliefConfidence: optionalScore(input.beliefConfidence),
    beliefFragility: optionalScore(input.beliefFragility),
    suggestedExposure: optionalNonNegative(input.suggestedExposure),
    maxTrustedExposure: optionalNonNegative(input.maxTrustedExposure),
    blockedActions: Math.max(0, Math.round(optionalNonNegative(input.blockedActions) ?? 0)),
    missingOutcomes: Math.max(0, Math.round(optionalNonNegative(input.missingOutcomes) ?? 0)),
    similarSamples: optionalNonNegative(input.similarSamples),
    positiveOutcomes: Math.max(0, Math.round(optionalNonNegative(input.positiveOutcomes) ?? 0)),
    negativeOutcomes: Math.max(0, Math.round(optionalNonNegative(input.negativeOutcomes) ?? 0)),
  };
}

function confidenceScore(input: NormalizedResolveInput) {
  const calibrated = valueOrFallback(input.calibratedConfidence, 40);
  const raw = valueOrFallback(input.rawConfidence, calibrated);
  const gapPenalty = Math.max(0, raw - calibrated) * 0.35;
  return clamp(calibrated - gapPenalty);
}

function recommendationScoreFor(recommendation: string) {
  if (COMMIT_RECOMMENDATIONS.has(recommendation)) return 100;
  if (REVIEW_RECOMMENDATIONS.has(recommendation)) return 45;
  if (REJECT_RECOMMENDATIONS.has(recommendation)) return 0;
  if (WAIT_RECOMMENDATIONS.has(recommendation)) return 60;
  return 50;
}

function missingEvidenceFor(input: ResolveInput, normalized: NormalizedResolveInput, thresholds: ResolveThresholds) {
  const missing: string[] = [];

  if (normalized.agencyRecommendation === "") missing.push("Agency recommendation");
  if (normalized.agencyTrust == null || normalized.agencyTrust < thresholds.minAgencyTrust) missing.push("Agency trust");
  if (normalized.trustScore == null) missing.push("Trust score");
  if (normalized.calibratedConfidence == null) missing.push("Calibrated confidence");
  if (normalized.judgementReliability == null) missing.push("Judgement reliability");
  if (normalized.outcomeStability == null) missing.push("Outcome stability");
  if (normalized.dataReliability == null) missing.push("Data reliability");
  if (normalized.similarSamples == null || normalized.similarSamples < thresholds.minSimilarSamples) {
    missing.push("Similar outcome sample");
  }
  if (normalized.missingOutcomes > 0) missing.push("Closed outcomes");
  if (normalized.blockedActions > 0) missing.push("Unblocked agency action");
  if (sizingBlocksCommitment(input, normalized)) missing.push("Trusted sizing capacity");

  return unique([...missing, ...stringArray(input.evidence?.missingEvidence)]);
}

function unlockConditionsFor(input: ResolveInput, normalized: NormalizedResolveInput, thresholds: ResolveThresholds) {
  const conditions: string[] = [];

  if (humanReviewRequiredFor(input, normalized)) conditions.push("Resolve the human review requirement before commitment.");
  if (normalized.agencyTrust == null || normalized.agencyTrust < thresholds.minAgencyTrust) conditions.push(`Raise agency trust to at least ${formatScore(thresholds.minAgencyTrust)}.`);
  if (normalized.trustScore == null || normalized.trustScore < thresholds.minTrustScore) conditions.push(`Raise trust score to at least ${formatScore(thresholds.minTrustScore)}.`);
  if (normalized.calibratedConfidence == null || normalized.calibratedConfidence < thresholds.minCalibratedConfidence) conditions.push(`Raise calibrated confidence to at least ${formatScore(thresholds.minCalibratedConfidence)}.`);
  if (normalized.judgementReliability == null || normalized.judgementReliability < thresholds.minJudgementReliability) conditions.push(`Raise judgement reliability to at least ${formatScore(thresholds.minJudgementReliability)}.`);
  if (normalized.dataReliability == null || normalized.dataReliability < thresholds.minDataReliability) conditions.push(`Restore data reliability to at least ${formatScore(thresholds.minDataReliability)}.`);
  if (normalized.riskScore != null && normalized.riskScore > thresholds.maxRiskScore) conditions.push(`Reduce risk score to ${formatScore(thresholds.maxRiskScore)} or lower.`);
  if (normalized.overfitRisk != null && normalized.overfitRisk > thresholds.maxOverfitRisk) conditions.push(`Reduce overfit risk to ${formatScore(thresholds.maxOverfitRisk)} or lower.`);
  if (normalized.beliefFragility != null && normalized.beliefFragility > thresholds.maxBeliefFragility) conditions.push(`Reduce belief fragility to ${formatScore(thresholds.maxBeliefFragility)} or lower.`);
  if (normalized.similarSamples == null || normalized.similarSamples < thresholds.minSimilarSamples) conditions.push(`Observe at least ${thresholds.minSimilarSamples} similar outcome samples.`);
  if (normalized.missingOutcomes > 0) conditions.push("Close or evaluate missing outcomes before raising commitment.");
  if (normalized.blockedActions > 0) conditions.push("Clear blocked agency actions before commitment.");
  if (sizingBlocksCommitment(input, normalized)) conditions.push("Restore positive trusted sizing capacity.");

  return unique([...conditions, ...stringArray(input.evidence?.unlockConditions)]);
}

function invalidationConditionsFor(input: ResolveInput, normalized: NormalizedResolveInput, thresholds: ResolveThresholds) {
  const conditions = [
    `Invalidate if data reliability falls below ${formatScore(thresholds.minDataReliability)}.`,
    `Invalidate if overfit risk rises above ${formatScore(thresholds.maxOverfitRisk)}.`,
    `Invalidate if belief fragility rises above ${formatScore(thresholds.maxBeliefFragility)}.`,
    "Invalidate if Agency denies the action.",
    "Invalidate if Trust or Judgement falls below the commitment threshold.",
  ];

  if (normalized.positiveOutcomes + normalized.negativeOutcomes >= thresholds.minSimilarSamples) {
    conditions.push("Invalidate if similar outcomes turn net negative.");
  }

  return unique([...conditions, ...stringArray(input.evidence?.invalidationConditions)]);
}

function decisionFor(context: ResolveContext): ResolveDecision {
  const input = context.normalized;

  if (isInvalidated(context.input, input, context.thresholds)) return "invalidate";
  if (isRejected(input, context)) return "reject";
  if (context.humanReviewRequired) return "escalate";
  if (shouldEscalate(input, context)) return "escalate";
  if (canCommit(input, context)) return "commit";
  return "wait";
}

function isInvalidated(input: ResolveInput, normalized: NormalizedResolveInput, thresholds: ResolveThresholds) {
  if (booleanEvidence(input.evidence?.invalidated) || normalized.agencyRecommendation === "invalidate") return true;
  const totalOutcomes = normalized.positiveOutcomes + normalized.negativeOutcomes;
  return totalOutcomes >= thresholds.minSimilarSamples &&
    normalized.negativeOutcomes > normalized.positiveOutcomes &&
    valueOrFallback(normalized.outcomeStability, 100) < 40;
}

function isRejected(normalized: NormalizedResolveInput, context: ResolveContext) {
  if (REJECT_RECOMMENDATIONS.has(normalized.agencyRecommendation)) return true;

  const trustProvided = normalized.trustScore != null;
  const confidenceProvided = normalized.calibratedConfidence != null;
  return trustProvided &&
    confidenceProvided &&
    valueOrFallback(normalized.trustScore, 0) < 25 &&
    valueOrFallback(normalized.calibratedConfidence, 0) < 40 &&
    context.resolveScore < context.requiredScore;
}

function shouldEscalate(normalized: NormalizedResolveInput, context: ResolveContext) {
  const thresholds = context.thresholds;
  const dataReliability = valueOrFallback(normalized.dataReliability, thresholds.minDataReliability);
  const overfitRisk = valueOrFallback(normalized.overfitRisk, 0);
  const beliefFragility = valueOrFallback(normalized.beliefFragility, 0);
  const strongJudgementWeakAgency =
    valueOrFallback(normalized.judgementReliability, 0) >= thresholds.minJudgementReliability &&
    valueOrFallback(normalized.outcomeStability, 0) >= 60 &&
    valueOrFallback(normalized.agencyTrust, 0) < thresholds.minAgencyTrust;

  return dataReliability < thresholds.minDataReliability - 20 ||
    overfitRisk > thresholds.maxOverfitRisk + 25 ||
    beliefFragility > thresholds.maxBeliefFragility + 25 ||
    strongJudgementWeakAgency;
}

function canCommit(normalized: NormalizedResolveInput, context: ResolveContext) {
  const thresholds = context.thresholds;
  return context.resolveScore >= context.requiredScore &&
    context.missingEvidence.length === 0 &&
    COMMIT_RECOMMENDATIONS.has(normalized.agencyRecommendation) &&
    valueOrFallback(normalized.agencyTrust, 0) >= thresholds.minAgencyTrust &&
    valueOrFallback(normalized.trustScore, 0) >= thresholds.minTrustScore &&
    valueOrFallback(normalized.calibratedConfidence, 0) >= thresholds.minCalibratedConfidence &&
    valueOrFallback(normalized.judgementReliability, 0) >= thresholds.minJudgementReliability &&
    valueOrFallback(normalized.dataReliability, 0) >= thresholds.minDataReliability &&
    valueOrFallback(normalized.riskScore, 100) <= thresholds.maxRiskScore &&
    valueOrFallback(normalized.overfitRisk, 100) <= thresholds.maxOverfitRisk &&
    valueOrFallback(normalized.beliefFragility, 100) <= thresholds.maxBeliefFragility &&
    valueOrFallback(normalized.similarSamples, 0) >= thresholds.minSimilarSamples &&
    normalized.blockedActions === 0 &&
    !sizingBlocksCommitment(context.input, normalized);
}

function humanReviewRequiredFor(input: ResolveInput, normalized: NormalizedResolveInput) {
  if (booleanEvidence(input.evidence?.humanReviewRequired)) return true;
  if (REVIEW_RECOMMENDATIONS.has(normalized.agencyRecommendation)) return true;
  return normalized.blockedActions > 0 && !COMMIT_RECOMMENDATIONS.has(normalized.agencyRecommendation);
}

function commitmentLevelFor(input: ResolveInput, decision: ResolveDecision, resolveScore: number, requiredScore: number): CommitmentLevel {
  if (decision === "reject" || decision === "invalidate" || decision === "escalate") return "none";
  if (decision === "wait") return "watch";

  const sizingMode = normalizeToken(input.sizingMode);
  if (["micro", "limited"].includes(sizingMode)) return "limited";
  if (resolveScore >= 90 && ["full", "normal", "large", "maxsafe", "max-safe"].includes(sizingMode)) return "full";
  if (resolveScore >= Math.max(82, requiredScore + 5)) return "graduated";
  return "limited";
}

function explanationFor(
  input: ResolveInput,
  decision: ResolveDecision,
  commitmentLevel: CommitmentLevel,
  context: ResolveContext,
) {
  const action = input.actionName?.trim() || "the proposed action";
  const primaryMissing = context.missingEvidence[0];
  const primaryUnlock = context.unlockConditions[0];

  if (decision === "commit") {
    return `Resolve can commit to ${action} at ${commitmentLevel} commitment because score ${formatScore(context.resolveScore)} meets the required ${formatScore(context.requiredScore)} and no upstream gate is blocking action.`;
  }

  if (decision === "invalidate") {
    return `Resolve invalidates ${action} because the thesis boundary failed: ${context.invalidationConditions[0]}`;
  }

  if (decision === "reject") {
    return `Resolve rejects ${action} because Agency, Trust, or calibrated confidence does not support commitment.`;
  }

  if (decision === "escalate") {
    return `Resolve escalates ${action} because ${primaryMissing ?? "an upstream review gate"} remains unresolved. ${primaryUnlock}`;
  }

  return `Resolve waits on ${action} because ${primaryMissing ?? "more evidence"} is still needed. ${primaryUnlock ?? "Keep observing until commitment thresholds are met."}`;
}

function sizingBlocksCommitment(input: ResolveInput, normalized: NormalizedResolveInput) {
  const sizingMode = normalizeToken(input.sizingMode);
  if (["none", "blocked", "deferred"].includes(sizingMode)) return true;
  if (normalized.suggestedExposure != null && normalized.suggestedExposure <= 0) return true;
  if (normalized.maxTrustedExposure != null && normalized.maxTrustedExposure <= 0) return true;
  return false;
}

function trace(
  id: string,
  label: string,
  value: number | string | null,
  score: number,
  weight: number,
  threshold: number,
  passed: boolean,
  reason: string,
): ResolveTrace {
  return {
    id,
    label,
    value,
    score: roundScore(score),
    weight,
    passed,
    threshold,
    reason,
  };
}

function weightedScore(traces: ResolveTrace[]) {
  const totalWeight = traces.reduce((sum, item) => sum + item.weight, 0);
  return traces.reduce((sum, item) => sum + item.score * item.weight, 0) / totalWeight;
}

function optionalScore(value: unknown) {
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  return clamp(Math.abs(n) <= 1 ? n * 100 : n);
}

function optionalNonNegative(value: unknown) {
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  return Math.max(0, n);
}

function valueOrFallback(value: number | null, fallback: number) {
  return value == null ? fallback : value;
}

function normalizeToken(value: unknown) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

function booleanEvidence(value: unknown) {
  return value === true || String(value).toLowerCase() === "true";
}

function stringArray(value: unknown) {
  return Array.isArray(value)
    ? value.map((item) => String(item ?? "").trim()).filter(Boolean)
    : [];
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

function createdAtFor(input: ResolveInput) {
  const candidate = input.createdAt ?? (typeof input.evidence?.createdAt === "string" ? input.evidence.createdAt : undefined);
  if (candidate && !Number.isNaN(Date.parse(candidate))) return new Date(candidate).toISOString();
  return "1970-01-01T00:00:00.000Z";
}

function formatScore(value: number) {
  return `${Math.round(value)}/100`;
}

function roundScore(value: number) {
  return Math.round(clamp(value) * 100) / 100;
}

function clamp(value: number, min = 0, max = 100) {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, value));
}

/* c8 ignore next */
import { clamp, mean, stdev } from "../math/statistics";

export type RobustnessRegime =
  | "trending"
  | "volatile"
  | "low-volatility"
  | "panic"
  | "recovery"
  | "sideways"
  | "liquidity-compression"
  | "expansion";

export type RobustnessObservation = {
  id?: string;
  index?: number;
  timestamp?: number;
  actual: number;
  predicted?: number;
  confidence?: number;
  regime?: RobustnessRegime | string;
  features?: Record<string, number>;
  participated?: boolean;
};

export type RobustnessParameterVariant = {
  id: string;
  score: number;
  baselineScore?: number;
  benchmarkScore?: number;
  passed?: boolean;
};

export type RobustnessAdversarialScenario = {
  id: string;
  score: number;
  baselineScore?: number;
  severity?: number;
};

export type RobustnessEnsembleVote = {
  id: string;
  direction: number;
  confidence: number;
  weight?: number;
};

export type LeakageCheck = {
  id: string;
  trainEndIndex: number;
  validationStartIndex: number;
  normalizedWithFuture?: boolean;
  featureTimestampIndex?: number;
  labelTimestampIndex?: number;
};

export type SignalRobustnessInput = {
  observations: RobustnessObservation[];
  trainWindowSize?: number;
  validationWindowSize?: number;
  stepSize?: number;
  minimumSamples?: number;
  parameterVariants?: RobustnessParameterVariant[];
  adversarialScenarios?: RobustnessAdversarialScenario[];
  ensembleVotes?: RobustnessEnsembleVote[];
  leakageChecks?: LeakageCheck[];
  expectedForwardSamples?: number;
  observedForwardSamples?: number;
  dataQualityScore?: number;
  seed?: number;
};

export type SignalRobustnessResult = {
  robustnessScore: number;
  overfitRisk: number;
  generalizationConfidence: number;
  structuralReliability: number;
  adaptabilityScore: number;
  uncertaintyLevel: number;
  deploymentReadiness: number;
  safetyGate: "allow" | "reduce" | "block";
  reasons: string[];
  walkForward: {
    stabilityScore: number;
    consistencyScore: number;
    degradationPct: number;
    windows: Array<{
      trainStartIndex: number;
      trainEndIndex: number;
      validationStartIndex: number;
      validationEndIndex: number;
      trainMean: number;
      validationMean: number;
      degradationPct: number;
    }>;
  };
  regimes: {
    regimeRobustnessScore: number;
    regimeDependencyScore: number;
    adaptabilityScore: number;
    regimes: Array<{ regime: string; samples: number; meanOutcome: number; score: number }>;
  };
  calibration: {
    calibrationScore: number;
    calibrationError: number;
    confidenceDecay: number;
    reliabilityCurve: Array<{ bucket: string; samples: number; predictedConfidence: number; realizedRate: number }>;
  };
  parameterSensitivity: {
    stabilityScore: number;
    fragilityScore: number;
    gradient: number;
    heatmap: Array<{ id: string; score: number; degradationPct: number; passed: boolean }>;
  };
  adversarial: {
    robustnessScore: number;
    executionRealismScore: number;
    scenarios: Array<{ id: string; degradationPct: number; resilienceScore: number }>;
  };
  participation: {
    participationScore: number;
    opportunityDensity: number;
    executableConviction: number;
  };
  ensemble: {
    consensusScore: number;
    dominancePenalty: number;
    disagreementScore: number;
  };
  leakage: {
    passed: boolean;
    violations: string[];
  };
  featureTrust: {
    trustScore: number;
    entropy: number;
    features: Array<{ key: string; trust: number; weight: number }>;
  };
  realityGap: {
    realismScore: number;
    expectedDegradationPct: number;
  };
  statisticalIntegrity: {
    score: number;
    bootstrapStability: number;
    monteCarloStability: number;
    minimumSampleScore: number;
    dataQualityScore: number;
  };
};

type NormalizedObservation = Required<Pick<RobustnessObservation, "actual" | "confidence" | "participated">> &
  RobustnessObservation & {
    order: number;
    regime: string;
  };

export class SignalRobustnessEngine {
  evaluate(input: SignalRobustnessInput): SignalRobustnessResult {
    const observations = normalizeObservations(input.observations);
    const minimumSamples = Math.max(1, Math.round(input.minimumSamples ?? 30));
    const walkForward = evaluateRollingWalkForward(
      observations,
      Math.max(2, Math.round(input.trainWindowSize ?? Math.max(12, minimumSamples))),
      Math.max(1, Math.round(input.validationWindowSize ?? Math.max(4, Math.floor(minimumSamples / 3)))),
      Math.max(1, Math.round(input.stepSize ?? Math.max(1, Math.floor((input.validationWindowSize ?? minimumSamples / 3) / 2)))),
    );
    const regimes = evaluateRegimes(observations);
    const calibration = evaluateCalibration(observations, minimumSamples);
    const parameterSensitivity = evaluateParameterSensitivity(input.parameterVariants ?? []);
    const adversarial = evaluateAdversarial(input.adversarialScenarios ?? []);
    const participation = evaluateParticipation(observations);
    const ensemble = evaluateEnsemble(input.ensembleVotes ?? []);
    const leakage = evaluateLeakage(input.leakageChecks ?? []);
    const featureTrust = evaluateFeatureTrust(observations);
    const statisticalIntegrity = evaluateStatisticalIntegrity(
      observations,
      minimumSamples,
      clamp(input.dataQualityScore ?? 100),
      input.seed ?? 17,
    );
    const realityGap = estimateRealityGap(walkForward.degradationPct, adversarial.executionRealismScore, statisticalIntegrity.score);
    const observedForwardSamples = Math.max(0, Math.round(input.observedForwardSamples ?? observations.length));
    const expectedForwardSamples = Math.max(1, Math.round(input.expectedForwardSamples ?? minimumSamples));
    const forwardSampleScore = clamp((observedForwardSamples / expectedForwardSamples) * 100);
    const componentScores = [
      walkForward.stabilityScore,
      regimes.regimeRobustnessScore,
      calibration.calibrationScore,
      parameterSensitivity.stabilityScore,
      adversarial.robustnessScore,
      participation.participationScore,
      ensemble.consensusScore,
      leakage.passed ? 100 : 0,
      featureTrust.trustScore,
      realityGap.realismScore,
      statisticalIntegrity.score,
      forwardSampleScore,
    ];
    const robustnessScore = Math.round(weightedMean(componentScores, [1.1, 1, 1, 1.05, 0.9, 0.9, 0.85, 1.25, 0.8, 1, 1.1, 0.7]));
    const uncertaintyLevel = Math.round(clamp(100 - weightedMean(componentScores, [1, 1, 1.2, 1, 0.8, 0.8, 0.7, 1.4, 0.7, 1, 1.1, 0.7])));
    const structuralReliability = Math.round(mean([
      parameterSensitivity.stabilityScore,
      leakage.passed ? 100 : 0,
      statisticalIntegrity.score,
      realityGap.realismScore,
    ]));
    const adaptabilityScore = Math.round(mean([
      regimes.adaptabilityScore,
      walkForward.consistencyScore,
      adversarial.robustnessScore,
      featureTrust.trustScore,
    ]));
    const generalizationConfidence = Math.round(mean([
      robustnessScore,
      calibration.calibrationScore,
      structuralReliability,
      forwardSampleScore,
    ]));
    const overfitRisk = Math.round(clamp(
      100 - robustnessScore +
        parameterSensitivity.fragilityScore * 0.16 +
        regimes.regimeDependencyScore * 0.12 +
        Math.max(0, 55 - calibration.calibrationScore) * 0.2 +
        (leakage.passed ? 0 : 28),
    ));
    const deploymentReadiness = Math.round(clamp(mean([
      robustnessScore,
      generalizationConfidence,
      structuralReliability,
      adaptabilityScore,
      100 - overfitRisk,
      participation.participationScore,
    ])));
    const safetyGate = leakage.passed === false || overfitRisk > 60
      ? "block"
      : overfitRisk > 30 || deploymentReadiness < 62 || participation.participationScore < 35
        ? "reduce"
        : "allow";
    const reasons = buildReasons({
      overfitRisk,
      safetyGate,
      walkForward: walkForward.stabilityScore,
      regimes: regimes.regimeRobustnessScore,
      calibration: calibration.calibrationScore,
      parameters: parameterSensitivity.stabilityScore,
      adversarial: adversarial.robustnessScore,
      participation: participation.participationScore,
      leakage,
      statisticalIntegrity: statisticalIntegrity.score,
    });

    return {
      robustnessScore,
      overfitRisk,
      generalizationConfidence,
      structuralReliability,
      adaptabilityScore,
      uncertaintyLevel,
      deploymentReadiness,
      safetyGate,
      reasons,
      walkForward,
      regimes,
      calibration,
      parameterSensitivity,
      adversarial,
      participation,
      ensemble,
      leakage,
      featureTrust,
      realityGap,
      statisticalIntegrity,
    };
  }
}

function normalizeObservations(observations: RobustnessObservation[]): NormalizedObservation[] {
  return observations
    .map((item, order) => {
      const actual = finite(item.actual);
      return {
        ...item,
        order,
        actual,
        confidence: clamp(item.confidence ?? 50),
        participated: item.participated !== false,
        regime: String(item.regime ?? inferRegime(actual, item.features)),
      };
    })
    .filter((item) => Number.isFinite(item.actual))
    .sort((a, b) => (a.timestamp ?? a.index ?? a.order) - (b.timestamp ?? b.index ?? b.order));
}

function evaluateRollingWalkForward(
  observations: NormalizedObservation[],
  trainWindowSize: number,
  validationWindowSize: number,
  stepSize: number,
) {
  const windows: SignalRobustnessResult["walkForward"]["windows"] = [];
  for (
    let start = 0;
    start + trainWindowSize + validationWindowSize <= observations.length;
    start += stepSize
  ) {
    const train = observations.slice(start, start + trainWindowSize).map((item) => item.actual);
    const validation = observations
      .slice(start + trainWindowSize, start + trainWindowSize + validationWindowSize)
      .map((item) => item.actual);
    const trainMean = mean(train);
    const validationMean = mean(validation);
    windows.push({
      trainStartIndex: start,
      trainEndIndex: start + trainWindowSize - 1,
      validationStartIndex: start + trainWindowSize,
      validationEndIndex: start + trainWindowSize + validationWindowSize - 1,
      trainMean,
      validationMean,
      degradationPct: trainMean > 0 ? clamp(((trainMean - validationMean) / Math.max(0.0001, Math.abs(trainMean))) * 100, -100, 100) : validationMean < 0 ? 100 : 0,
    });
  }
  const validationMeans = windows.map((window) => window.validationMean);
  const positiveRatio = ratio(validationMeans, (value) => value > 0);
  const consistencyScore = clamp(positiveRatio * 100 - stdev(validationMeans) * 6);
  const degradationPct = windows.length ? Math.max(0, mean(windows.map((window) => window.degradationPct))) : 100;
  const stabilityScore = windows.length
    ? clamp(consistencyScore * 0.7 + (100 - degradationPct) * 0.3)
    : clamp((observations.length / Math.max(1, trainWindowSize + validationWindowSize)) * 55);

  return { stabilityScore, consistencyScore, degradationPct, windows };
}

function evaluateRegimes(observations: NormalizedObservation[]) {
  const buckets = new Map<string, number[]>();
  for (const item of observations) {
    const bucket = buckets.get(item.regime) ?? [];
    bucket.push(item.actual);
    buckets.set(item.regime, bucket);
  }
  const regimes = Array.from(buckets.entries()).map(([regime, values]) => ({
    regime,
    samples: values.length,
    meanOutcome: mean(values),
    score: clamp(50 + mean(values) * 8 + ratio(values, (value) => value > 0) * 35 - stdev(values) * 2),
  }));
  const scores = regimes.map((item) => item.score);
  const sampleCounts = regimes.map((item) => item.samples);
  const dominantShare = observations.length ? Math.max(0, ...sampleCounts) / observations.length : 1;
  const regimeDependencyScore = clamp(dominantShare * 100 + stdev(scores) * 0.6);
  const regimeRobustnessScore = clamp(mean(scores) - Math.max(0, dominantShare - 0.55) * 35);
  const adaptabilityScore = clamp(regimeRobustnessScore - Math.max(0, stdev(scores) - 18) * 0.8);

  return { regimeRobustnessScore, regimeDependencyScore, adaptabilityScore, regimes };
}

function evaluateCalibration(observations: NormalizedObservation[], minimumSamples: number) {
  const buckets = [0, 20, 40, 60, 80].map((start) => {
    const end = start + 20;
    const values = observations.filter((item) => item.confidence >= start && item.confidence < end + (end === 100 ? 1 : 0));
    const predictedConfidence = values.length ? mean(values.map((item) => item.confidence)) : start + 10;
    const realizedRate = values.length ? ratio(values.map((item) => item.actual), (value) => value > 0) * 100 : predictedConfidence;
    return {
      bucket: `${start}-${end}`,
      samples: values.length,
      predictedConfidence,
      realizedRate,
    };
  });
  const populated = buckets.filter((bucket) => bucket.samples > 0);
  const weightedError = populated.length
    ? populated.reduce((sum, bucket) => sum + Math.abs(bucket.predictedConfidence - bucket.realizedRate) * bucket.samples, 0) /
      Math.max(1, populated.reduce((sum, bucket) => sum + bucket.samples, 0))
    : 50;
  const samplePenalty = observations.length < minimumSamples ? (1 - observations.length / minimumSamples) * 25 : 0;
  const calibrationError = clamp(weightedError + samplePenalty);
  const confidenceDecay = clamp(calibrationError * 0.75 + samplePenalty);
  const calibrationScore = clamp(100 - calibrationError);

  return { calibrationScore, calibrationError, confidenceDecay, reliabilityCurve: buckets };
}

function evaluateParameterSensitivity(variants: RobustnessParameterVariant[]) {
  if (!variants.length) {
    return { stabilityScore: 35, fragilityScore: 65, gradient: 65, heatmap: [] };
  }
  const baseline = variants.find((variant) => variant.baselineScore != null)?.baselineScore ?? mean(variants.map((variant) => variant.score));
  const heatmap = variants.map((variant) => {
    const degradationPct = baseline > 0 ? clamp(((baseline - variant.score) / Math.max(0.0001, Math.abs(baseline))) * 100, -100, 100) : 0;
    return {
      id: variant.id,
      score: variant.score,
      degradationPct,
      passed: variant.passed !== false && variant.score >= Math.max(0, (variant.benchmarkScore ?? 0)),
    };
  });
  const passRate = ratio(heatmap, (item) => item.passed);
  const positiveDegradation = heatmap.map((item) => Math.max(0, item.degradationPct));
  const gradient = clamp(mean(positiveDegradation) + stdev(positiveDegradation));
  const fragilityScore = clamp((1 - passRate) * 100 + gradient * 0.55);
  const stabilityScore = clamp(passRate * 75 + (100 - gradient) * 0.25);

  return { stabilityScore, fragilityScore, gradient, heatmap };
}

function evaluateAdversarial(scenarios: RobustnessAdversarialScenario[]) {
  if (!scenarios.length) {
    return { robustnessScore: 50, executionRealismScore: 50, scenarios: [] };
  }
  const mapped = scenarios.map((scenario) => {
    const baseline = scenario.baselineScore ?? scenario.score;
    const degradationPct = baseline > 0 ? clamp(((baseline - scenario.score) / Math.max(0.0001, Math.abs(baseline))) * 100, -100, 100) : 0;
    return {
      id: scenario.id,
      degradationPct,
      resilienceScore: clamp(100 - Math.max(0, degradationPct) - (scenario.severity ?? 0) * 0.12),
    };
  });
  return {
    robustnessScore: mean(mapped.map((item) => item.resilienceScore)),
    executionRealismScore: clamp(mean(mapped.map((item) => item.resilienceScore)) - Math.max(0, ...mapped.map((item) => item.degradationPct)) * 0.15),
    scenarios: mapped,
  };
}

function evaluateParticipation(observations: NormalizedObservation[]) {
  const participated = observations.filter((item) => item.participated);
  const opportunityDensity = observations.length ? participated.length / observations.length : 0;
  const executableConviction = participated.length
    ? clamp(ratio(participated.map((item) => item.actual), (value) => value > 0) * 75 + mean(participated.map((item) => item.confidence)) * 0.25)
    : 0;
  const participationScore = clamp(opportunityDensity * 70 + executableConviction * opportunityDensity * 0.3);

  return { participationScore, opportunityDensity: opportunityDensity * 100, executableConviction };
}

function evaluateEnsemble(votes: RobustnessEnsembleVote[]) {
  if (!votes.length) {
    return { consensusScore: 50, dominancePenalty: 20, disagreementScore: 50 };
  }
  const totalWeight = votes.reduce((sum, vote) => sum + Math.max(0, vote.weight ?? 1), 0) || 1;
  const weightedDirection = votes.reduce((sum, vote) => sum + Math.sign(vote.direction) * clamp(vote.confidence) * Math.max(0, vote.weight ?? 1), 0) / totalWeight;
  const largestWeight = Math.max(...votes.map((vote) => Math.max(0, vote.weight ?? 1))) / totalWeight;
  const dominancePenalty = clamp(Math.max(0, largestWeight - 0.45) * 100);
  const disagreementScore = clamp(100 - stdev(votes.map((vote) => Math.sign(vote.direction) * clamp(vote.confidence))) * 0.9);
  const consensusScore = clamp(Math.abs(weightedDirection) - dominancePenalty * 0.35 + disagreementScore * 0.25);

  return { consensusScore, dominancePenalty, disagreementScore };
}

function evaluateLeakage(checks: LeakageCheck[]) {
  const violations = checks.flatMap((check) => {
    const issues: string[] = [];
    if (check.validationStartIndex <= check.trainEndIndex) issues.push(`${check.id}: validation overlaps training`);
    if (check.normalizedWithFuture === true) issues.push(`${check.id}: normalization used future data`);
    if (
      check.featureTimestampIndex != null &&
      check.labelTimestampIndex != null &&
      check.featureTimestampIndex >= check.labelTimestampIndex
    ) {
      issues.push(`${check.id}: feature timestamp is not earlier than label`);
    }
    return issues;
  });

  return { passed: violations.length === 0, violations };
}

function evaluateFeatureTrust(observations: NormalizedObservation[]) {
  const keys = Array.from(new Set(observations.flatMap((item) => Object.keys(item.features ?? {}))));
  if (!keys.length) {
    return { trustScore: 50, entropy: 100, features: [] };
  }
  const features = keys.map((key) => {
    const pairs = observations
      .map((item) => [item.features?.[key], item.actual] as const)
      .filter(([feature, actual]) => Number.isFinite(feature) && Number.isFinite(actual));
    const trust = pairs.length >= 3 ? clamp(50 + correlation(pairs.map(([feature]) => feature as number), pairs.map(([, actual]) => actual)) * 50) : 45;
    return { key, trust, weight: trust };
  });
  const total = features.reduce((sum, item) => sum + Math.max(0, item.weight), 0) || 1;
  const probabilities = features.map((item) => Math.max(0, item.weight) / total);
  const entropy = clamp(-probabilities.reduce((sum, value) => sum + (value > 0 ? value * Math.log2(value) : 0), 0) / Math.log2(Math.max(2, probabilities.length)) * 100);
  const trustScore = clamp(mean(features.map((item) => item.trust)) - Math.max(0, 35 - entropy) * 0.4);

  return { trustScore, entropy, features };
}

function evaluateStatisticalIntegrity(
  observations: NormalizedObservation[],
  minimumSamples: number,
  dataQualityScore: number,
  seed: number,
) {
  const values = observations.map((item) => item.actual);
  const minimumSampleScore = clamp((values.length / minimumSamples) * 100);
  const bootstrapStability = bootstrapPositiveMeanStability(values, seed);
  const monteCarloStability = monteCarloOrderStability(values, seed + 101);
  const score = clamp(mean([minimumSampleScore, bootstrapStability, monteCarloStability, dataQualityScore]));

  return { score, bootstrapStability, monteCarloStability, minimumSampleScore, dataQualityScore };
}

function estimateRealityGap(degradationPct: number, executionRealismScore: number, statisticalIntegrityScore: number) {
  const expectedDegradationPct = clamp(Math.max(0, degradationPct) * 0.45 + (100 - executionRealismScore) * 0.25 + (100 - statisticalIntegrityScore) * 0.18);
  return {
    realismScore: clamp(100 - expectedDegradationPct),
    expectedDegradationPct,
  };
}

function buildReasons(input: {
  overfitRisk: number;
  safetyGate: "allow" | "reduce" | "block";
  walkForward: number;
  regimes: number;
  calibration: number;
  parameters: number;
  adversarial: number;
  participation: number;
  leakage: { passed: boolean; violations: string[] };
  statisticalIntegrity: number;
}) {
  const reasons: string[] = [];
  if (input.overfitRisk > 30) reasons.push("Overfit risk is above the production threshold.");
  if (input.walkForward < 60) reasons.push("Rolling walk-forward validation is unstable.");
  if (input.regimes < 60) reasons.push("Performance is too dependent on a narrow regime set.");
  if (input.calibration < 60) reasons.push("Predicted confidence is poorly calibrated to realized outcomes.");
  if (input.parameters < 60) reasons.push("Nearby parameter variants are fragile.");
  if (input.adversarial < 60) reasons.push("Adversarial distortions create too much degradation.");
  if (input.participation < 35) reasons.push("Executable participation is too sparse.");
  if (!input.leakage.passed) reasons.push(...input.leakage.violations);
  if (input.statisticalIntegrity < 60) reasons.push("Statistical integrity is below the production floor.");
  if (input.safetyGate === "allow" && reasons.length === 0) reasons.push("Robustness diagnostics are within production tolerance.");
  return Array.from(new Set(reasons));
}

function inferRegime(actual: number, features: Record<string, number> | undefined): RobustnessRegime {
  const volatility = finite(features?.volatility ?? features?.risk ?? Math.abs(actual));
  const liquidity = finite(features?.liquidity ?? 70);
  if (actual < -6 || volatility > 78) return "panic";
  if (actual > 6 && volatility > 55) return "expansion";
  if (actual > 1.2 && volatility <= 55) return "trending";
  if (actual < 0 && volatility > 45) return "volatile";
  if (Math.abs(actual) < 0.8 && volatility < 25) return "low-volatility";
  if (liquidity < 35) return "liquidity-compression";
  if (actual > 0) return "recovery";
  return "sideways";
}

function bootstrapPositiveMeanStability(values: number[], seed: number) {
  if (!values.length) return 0;
  const generator = seeded(seed);
  let positive = 0;
  const rounds = 64;
  for (let round = 0; round < rounds; round += 1) {
    const sample = values.map(() => values[Math.floor(generator() * values.length)]);
    if (mean(sample) > 0) positive += 1;
  }
  return clamp((positive / rounds) * 100);
}

function monteCarloOrderStability(values: number[], seed: number) {
  if (!values.length) return 0;
  const generator = seeded(seed);
  let stable = 0;
  const rounds = 48;
  for (let round = 0; round < rounds; round += 1) {
    const shuffled = deterministicShuffle(values, generator);
    const curve = shuffled.reduce<number[]>((acc, value) => {
      const last = acc[acc.length - 1] ?? 0;
      acc.push(last + value);
      return acc;
    }, []);
    let peak = Number.NEGATIVE_INFINITY;
    let trough = 0;
    for (const value of curve) {
      peak = Math.max(peak, value);
      trough = Math.max(trough, peak - value);
    }
    if (curve[curve.length - 1] > 0 && trough < Math.max(12, Math.abs(curve[curve.length - 1]) * 0.65)) stable += 1;
  }
  return clamp((stable / rounds) * 100);
}

function deterministicShuffle(values: number[], generator: () => number) {
  const copy = values.slice();
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(generator() * (index + 1));
    const temp = copy[index];
    copy[index] = copy[swapIndex];
    copy[swapIndex] = temp;
  }
  return copy;
}

function seeded(seed: number) {
  let value = Math.floor(seed) || 1;
  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 2 ** 32;
  };
}

function weightedMean(values: number[], weights: number[]) {
  /* c8 ignore next */
  const totalWeight = values.reduce((sum, _value, index) => sum + (weights[index] ?? 1), 0) || 1;
  /* c8 ignore next */
  return values.reduce((sum, value, index) => sum + clamp(value) * (weights[index] ?? 1), 0) / totalWeight;
}

function ratio<T>(values: T[], predicate: (value: T) => boolean) {
  return values.length ? values.filter(predicate).length / values.length : 0;
}

function finite(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

/* c8 ignore next */
function correlation(left: number[], right: number[]) {
  const count = Math.min(left.length, right.length);
  /* c8 ignore next */
  if (count < 2) return 0;
  const leftValues = left.slice(0, count);
  const rightValues = right.slice(0, count);
  const leftMean = mean(leftValues);
  const rightMean = mean(rightValues);
  const numerator = leftValues.reduce((sum, value, index) => sum + (value - leftMean) * (rightValues[index] - rightMean), 0);
  const denominator = Math.sqrt(
    leftValues.reduce((sum, value) => sum + (value - leftMean) ** 2, 0) *
      rightValues.reduce((sum, value) => sum + (value - rightMean) ** 2, 0),
  );
  return denominator > 0 ? numerator / denominator : 0;
}

import bundledGenericState from "./lexicons/generic-state.v1.json";

export type SemanticStateInput = {
  dimensions: Record<string, number>;
  context?: Record<string, unknown>;
};

export type SemanticPolarity = "positive" | "neutral" | "negative";

export type SemanticLexiconEntry = {
  word: string;
  category?: string;
  dimensions: Record<string, number>;
  polarity?: SemanticPolarity;
  intensity?: number;
  aliases?: string[];
  description?: string;
};

export type SemanticLexicon = {
  name?: string;
  version: string;
  entries: SemanticLexiconEntry[];
};

export type SemanticStateConfig = {
  lexicon?: SemanticLexicon;
  weights?: Record<string, number>;
  secondaryLimit?: number;
  minConfidence?: number;
  fallbackWord?: string;
  priority?: Record<string, number> | string[];
};

export type SemanticStateResult = {
  word: string;
  confidence: number;
  score: number;
  lexiconVersion: string;
  category?: string;
  secondary: Array<{
    word: string;
    score: number;
    confidence: number;
    category?: string;
  }>;
  breakdown: Record<string, number>;
};

export type SemanticLexiconValidationOptions = {
  allowDuplicateWords?: boolean;
};

type SemanticCandidate = {
  entry: SemanticLexiconEntry;
  score: number;
  confidence: number;
  breakdown: Record<string, number>;
};

export const DEFAULT_BUNDLED_SEMANTIC_LEXICON = "generic-state.v1";

const BUNDLED_LEXICONS: Record<string, SemanticLexicon> = {
  "generic-state": bundledGenericState as unknown as SemanticLexicon,
  "generic-state.v1": bundledGenericState as unknown as SemanticLexicon,
};

export function loadBundledSemanticLexicon(name = DEFAULT_BUNDLED_SEMANTIC_LEXICON): SemanticLexicon {
  const lexicon = BUNDLED_LEXICONS[name];
  if (lexicon === undefined) {
    throw new Error(`Bundled semantic lexicon "${name}" was not found.`);
  }

  const cloned = cloneLexicon(lexicon);
  return validateSemanticLexicon(cloned);
}

export function validateSemanticLexicon(
  lexicon: SemanticLexicon,
  options: SemanticLexiconValidationOptions = {},
): SemanticLexicon {
  if (lexicon == null || typeof lexicon !== "object" || Array.isArray(lexicon)) {
    throw new Error("Semantic lexicon must be an object.");
  }

  if (!nonEmptyString(lexicon.version)) {
    throw new Error("Semantic lexicon must include a non-empty version.");
  }

  if (!Array.isArray(lexicon.entries) || lexicon.entries.length === 0) {
    throw new Error("Semantic lexicon must include at least one entry.");
  }

  const seenWords = new Set<string>();
  for (const [index, entry] of lexicon.entries.entries()) {
    validateLexiconEntry(entry, index);
    const normalizedWord = entry.word.trim().toLocaleLowerCase();
    if (seenWords.has(normalizedWord) && options.allowDuplicateWords !== true) {
      throw new Error(`Duplicate semantic lexicon word "${entry.word}" is not allowed.`);
    }
    seenWords.add(normalizedWord);
  }

  return lexicon;
}

export function resolveSemanticState(
  input: SemanticStateInput,
  config: SemanticStateConfig = {},
): SemanticStateResult {
  const lexicon = config.lexicon === undefined
    ? loadBundledSemanticLexicon()
    : validateSemanticLexicon(config.lexicon);
  const dimensions = validateDimensionMap(input.dimensions, "Semantic state input dimensions");
  const weights = validateWeights(config.weights);
  const priority = buildPriority(config.priority);
  const candidates = lexicon.entries
    .map((entry) => scoreEntry(entry, dimensions, weights))
    .sort((a, b) => compareCandidates(a, b, priority));
  const [top] = candidates as [SemanticCandidate, ...SemanticCandidate[]];
  const minConfidence = config.minConfidence === undefined
    ? 0
    : validateUnitValue(config.minConfidence, "minConfidence");
  const fallbackCandidate = config.fallbackWord === undefined
    ? undefined
    : candidates.find((candidate) => sameWord(candidate.entry.word, config.fallbackWord as string));
  const selected =
    top.confidence < minConfidence && fallbackCandidate !== undefined
      ? fallbackCandidate
      : top;
  const secondaryLimit = normalizeSecondaryLimit(config.secondaryLimit);
  const secondary = candidates
    .filter((candidate) => !sameWord(candidate.entry.word, selected.entry.word))
    .slice(0, secondaryLimit)
    .map((candidate) => ({
      word: candidate.entry.word,
      score: candidate.score,
      confidence: candidate.confidence,
      ...(candidate.entry.category === undefined ? {} : { category: candidate.entry.category }),
    }));

  return {
    word: selected.entry.word,
    confidence: selected.confidence,
    score: selected.score,
    lexiconVersion: lexicon.version,
    ...(selected.entry.category === undefined ? {} : { category: selected.entry.category }),
    secondary,
    breakdown: selected.breakdown,
  };
}

function validateLexiconEntry(entry: SemanticLexiconEntry, index: number) {
  if (entry == null || typeof entry !== "object" || Array.isArray(entry)) {
    throw new Error(`Semantic lexicon entry at index ${index} must be an object.`);
  }

  if (!nonEmptyString(entry.word)) {
    throw new Error(`Semantic lexicon entry at index ${index} must include a valid word.`);
  }

  validateDimensionMap(entry.dimensions, `Semantic lexicon entry "${entry.word}" dimensions`);

  if (entry.polarity !== undefined && !["positive", "neutral", "negative"].includes(entry.polarity)) {
    throw new Error(`Semantic lexicon entry "${entry.word}" has an invalid polarity.`);
  }

  if (entry.intensity !== undefined) {
    validateUnitValue(entry.intensity, `Semantic lexicon entry "${entry.word}" intensity`);
  }

  if (entry.aliases !== undefined && !entry.aliases.every(nonEmptyString)) {
    throw new Error(`Semantic lexicon entry "${entry.word}" aliases must be non-empty strings.`);
  }
}

function validateDimensionMap(value: Record<string, number>, label: string) {
  if (value == null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be an object.`);
  }

  const entries = Object.entries(value);
  if (entries.length === 0) {
    throw new Error(`${label} must include at least one dimension.`);
  }

  const normalized: Record<string, number> = {};
  for (const [dimension, dimensionValue] of entries) {
    if (!nonEmptyString(dimension)) {
      throw new Error(`${label} contains an invalid dimension name.`);
    }
    normalized[dimension] = validateUnitValue(dimensionValue, `${label}.${dimension}`);
  }

  return normalized;
}

function validateWeights(weights: Record<string, number> | undefined) {
  if (weights === undefined) return {};
  const normalized: Record<string, number> = {};
  for (const [dimension, weight] of Object.entries(weights)) {
    if (!nonEmptyString(dimension)) {
      throw new Error("Semantic state weights contain an invalid dimension name.");
    }
    if (!Number.isFinite(weight) || weight < 0) {
      throw new Error(`Semantic state weight for "${dimension}" must be a non-negative number.`);
    }
    normalized[dimension] = weight;
  }
  return normalized;
}

function validateUnitValue(value: number, label: string) {
  if (!Number.isFinite(value) || value < 0 || value > 1) {
    throw new Error(`${label} must be a number between 0 and 1.`);
  }
  return value;
}

function scoreEntry(
  entry: SemanticLexiconEntry,
  inputDimensions: Record<string, number>,
  weights: Record<string, number>,
): SemanticCandidate {
  const dimensions = sortedDimensionNames(inputDimensions, entry.dimensions);
  let weightedScore = 0;
  let totalWeight = 0;
  const breakdown: Record<string, number> = {};

  for (const dimension of dimensions) {
    const weight = weights[dimension] ?? 1;
    if (weight === 0) {
      continue;
    }
    const inputValue = inputDimensions[dimension] ?? 0.5;
    const targetValue = entry.dimensions[dimension] ?? 0.5;
    const dimensionScore = round(1 - Math.abs(inputValue - targetValue));
    breakdown[dimension] = dimensionScore;
    weightedScore += dimensionScore * weight;
    totalWeight += weight;
  }

  if (totalWeight === 0) {
    throw new Error("Semantic state scoring requires at least one positive dimension weight.");
  }

  const score = round(weightedScore / totalWeight);
  return {
    entry,
    score,
    confidence: score,
    breakdown,
  };
}

function sortedDimensionNames(
  inputDimensions: Record<string, number>,
  entryDimensions: Record<string, number>,
) {
  return Array.from(new Set([...Object.keys(inputDimensions), ...Object.keys(entryDimensions)])).sort();
}

function compareCandidates(
  left: SemanticCandidate,
  right: SemanticCandidate,
  priority: Record<string, number>,
) {
  if (right.score !== left.score) return right.score - left.score;

  const priorityDelta = priorityFor(right.entry.word, priority) - priorityFor(left.entry.word, priority);
  if (priorityDelta !== 0) return priorityDelta;

  return alphabetical(left.entry.word, right.entry.word);
}

function buildPriority(priority: SemanticStateConfig["priority"]) {
  if (priority === undefined) return {};
  if (Array.isArray(priority)) {
    return priority.reduce<Record<string, number>>((result, word, index) => {
      if (!nonEmptyString(word)) {
        throw new Error("Semantic state priority words must be non-empty strings.");
      }
      result[word.toLocaleLowerCase()] = priority.length - index;
      return result;
    }, {});
  }

  const normalized: Record<string, number> = {};
  for (const [word, value] of Object.entries(priority)) {
    if (!nonEmptyString(word)) {
      throw new Error("Semantic state priority contains an invalid word.");
    }
    if (!Number.isFinite(value)) {
      throw new Error(`Semantic state priority for "${word}" must be numeric.`);
    }
    normalized[word.toLocaleLowerCase()] = value;
  }
  return normalized;
}

function normalizeSecondaryLimit(value: number | undefined) {
  if (value === undefined) return 3;
  if (!Number.isInteger(value) || value < 0) {
    throw new Error("secondaryLimit must be a non-negative integer.");
  }
  return value;
}

function priorityFor(word: string, priority: Record<string, number>) {
  return priority[word.toLocaleLowerCase()] ?? 0;
}

function sameWord(left: string, right: string) {
  return left.toLocaleLowerCase() === right.toLocaleLowerCase();
}

function alphabetical(left: string, right: string) {
  const normalizedLeft = left.toLocaleLowerCase();
  const normalizedRight = right.toLocaleLowerCase();
  if (normalizedLeft < normalizedRight) return -1;
  return 1;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function round(value: number) {
  return Number(value.toFixed(6));
}

function cloneLexicon(lexicon: SemanticLexicon): SemanticLexicon {
  return JSON.parse(JSON.stringify(lexicon)) as SemanticLexicon;
}

/* c8 ignore start */
export type SizingMode = "none" | "micro" | "small" | "normal" | "large" | "maxSafe";

export type SizingDecision = "blocked" | "deferred" | "allowed";

export type SizingConstraint = {
  id: string;
  label?: string;
  type: "hard" | "soft";
  passed: boolean;
  severity?: "low" | "medium" | "high" | "critical";
  reason?: string;
};

export type SizingInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;

  confidence: number;
  risk: number;
  utility?: number;

  availableCapacity?: number;
  requestedCapacity?: number;
  minCapacity?: number;
  maxCapacity?: number;

  constraints?: SizingConstraint[];
  context?: Record<string, unknown>;
};

export type SizingResult = {
  decision: SizingDecision;
  mode: SizingMode;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: {
    cappedBy?: string[];
    blockedBy?: string[];
    requestedCapacity?: number;
    availableCapacity?: number;
    maxCapacity?: number;
  };
};

type NormalizedCapacity = {
  value: number | undefined;
  specified: boolean;
};
/* c8 ignore stop */

const CONSTRAINT_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.9,
  medium: 0.75,
  high: 0.55,
  critical: 0.35,
};

const HARD_NON_BLOCKING_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.8,
  medium: 0.6,
  high: 0,
  critical: 0,
};

export function sizeDecision(input: SizingInput): SizingResult {
  const reasons: string[] = [];
  const cappedBy: string[] = [];
  const blockedBy: string[] = [];
  const constraints = normalizeConstraints(input.constraints);
  const confidence = normalizeRatio(input.confidence, "Confidence", 0, reasons);
  const risk = normalizeRatio(input.risk, "Risk", 1, reasons);
  const utility = input.utility == null ? undefined : normalizeRatio(input.utility, "Utility", 0.5, reasons);
  const requestedCapacity = normalizeCapacity(input.requestedCapacity, "Requested capacity", reasons);
  const availableCapacity = normalizeCapacity(input.availableCapacity, "Available capacity", reasons);
  const minCapacity = normalizeCapacity(input.minCapacity, "Minimum capacity", reasons);
  const maxCapacity = normalizeCapacity(input.maxCapacity, "Maximum capacity", reasons);
  const audit = buildAudit(requestedCapacity.value, availableCapacity.value, maxCapacity.value);
  const blockingConstraints = constraints.filter(
    (constraint) =>
      constraint.type === "hard" &&
      !constraint.passed &&
      (constraint.severity === "high" || constraint.severity === "critical"),
  );

  if (blockingConstraints.length > 0) {
    for (const constraint of blockingConstraints) {
      blockedBy.push(constraint.id);
      reasons.push(`Blocked by ${constraintName(constraint)}.`);
      if (constraint.reason) reasons.push(constraint.reason);
    }

    return {
      decision: "blocked",
      mode: "none",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons: unique(reasons),
      constraints,
      audit: {
        ...audit,
        blockedBy,
      },
    };
  }

  let normalizedSize = confidence * (1 - risk);

  if (confidence <= 0) {
    reasons.push("Confidence is zero; sizing starts at zero.");
  } else if (confidence < 0.35) {
    reasons.push(`Confidence ${formatPercent(confidence)} is low; sizing is conservative.`);
  } else if (confidence < 0.6) {
    reasons.push(`Confidence ${formatPercent(confidence)} is moderate; sizing remains limited.`);
  } else {
    reasons.push(`Confidence ${formatPercent(confidence)} supports sizing.`);
  }

  if (risk >= 1) {
    reasons.push("Risk is at maximum; sizing starts at zero.");
  } else if (risk > 0.75) {
    reasons.push(`Risk ${formatPercent(risk)} is high; sizing is reduced.`);
  } else if (risk > 0.45) {
    reasons.push(`Risk ${formatPercent(risk)} is moderate; sizing is controlled.`);
  } else {
    reasons.push(`Risk ${formatPercent(risk)} is controlled.`);
  }

  if (utility != null) {
    const utilityMultiplier = 0.8 + utility * 0.4;
    normalizedSize *= utilityMultiplier;
    if (utility < 0.4) reasons.push(`Utility ${formatPercent(utility)} reduces sizing.`);
    if (utility > 0.7) reasons.push(`Utility ${formatPercent(utility)} supports sizing.`);
  }

  const failedNonBlocking = constraints.filter((constraint) => !constraint.passed);
  for (const constraint of failedNonBlocking) {
    const severity = constraint.severity as NonNullable<SizingConstraint["severity"]>;
    const factor =
      constraint.type === "hard"
        ? HARD_NON_BLOCKING_REDUCTION[severity]
        : CONSTRAINT_REDUCTION[severity];
    normalizedSize *= factor;
    reasons.push(`${constraintName(constraint)} failed with ${severity} severity; sizing reduced.`);
    if (constraint.reason) reasons.push(constraint.reason);
  }

  if (constraints.length > 0 && failedNonBlocking.length === 0) {
    reasons.push("All sizing constraints passed.");
  }

  if (confidence >= 0.75 && risk <= 0.35 && failedNonBlocking.length === 0) {
    normalizedSize *= 1.15;
    reasons.push("Strong confidence and controlled risk support increased sizing.");
  }

  normalizedSize = clampUnit(normalizedSize);

  const basis = capacityBasis(availableCapacity, requestedCapacity, maxCapacity);
  if (basis <= 0) {
    reasons.push("Available sizing capacity is zero.");
    return finalize({
      decision: "deferred",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons,
      constraints,
      audit,
      cappedBy,
    });
  }

  let size = normalizedSize * basis;
  size = applyCap("requestedCapacity", requestedCapacity.value, size, cappedBy, reasons);
  size = applyCap("maxCapacity", maxCapacity.value, size, cappedBy, reasons);
  size = applyCap("availableCapacity", availableCapacity.value, size, cappedBy, reasons);

  if (minCapacity.value != null && minCapacity.value > 0 && normalizedSize > 0 && size > 0 && size < minCapacity.value) {
    const upperCap = smallestDefined(requestedCapacity.value, maxCapacity.value, availableCapacity.value);
    if (minCapacity.value <= upperCap) {
      size = minCapacity.value;
      reasons.push(`Raised to minimum capacity ${formatNumber(minCapacity.value)}.`);
    } else {
      reasons.push(`Minimum capacity ${formatNumber(minCapacity.value)} could not be met within caps.`);
    }
  }

  size = Math.max(0, size);
  const finalNormalizedSize = clampUnit(size / basis);

  if (finalNormalizedSize === 0) {
    reasons.push("No capacity committed after confidence, risk, constraints, and caps.");
  }

  return finalize({
    decision: finalNormalizedSize > 0 ? "allowed" : "deferred",
    size: round(size),
    normalizedSize: finalNormalizedSize,
    confidence,
    risk,
    reasons,
    constraints,
    audit,
    cappedBy,
    });
}

function finalize(args: {
  decision: SizingDecision;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: SizingResult["audit"];
  cappedBy: string[];
}): SizingResult {
  return {
    decision: args.decision,
    mode: modeFor(args.normalizedSize),
    size: round(args.size),
    normalizedSize: round(clampUnit(args.normalizedSize)),
    confidence: args.confidence,
    risk: args.risk,
    reasons: unique(args.reasons),
    constraints: args.constraints,
    audit: {
      ...args.audit,
      ...(args.cappedBy.length ? { cappedBy: unique(args.cappedBy) } : {}),
    },
  };
}

function normalizeConstraints(constraints: SizingInput["constraints"]): SizingConstraint[] {
  if (!Array.isArray(constraints)) return [];
  return constraints.map((constraint, index) => ({
    id: String(constraint.id || `constraint-${index + 1}`),
    label: constraint.label,
    type: constraint.type === "hard" ? "hard" : "soft",
    passed: Boolean(constraint.passed),
    severity: normalizeSeverity(constraint.severity),
    reason: constraint.reason,
  }));
}

function normalizeSeverity(severity: SizingConstraint["severity"]): NonNullable<SizingConstraint["severity"]> {
  return severity === "low" || severity === "medium" || severity === "high" || severity === "critical"
    ? severity
    : "medium";
}

function normalizeRatio(value: unknown, label: string, fallback: number, reasons: string[]) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was missing or invalid; using ${formatPercent(fallback)}.`);
    return fallback;
  }

  const scaled = Math.abs(numberValue) > 1 ? numberValue / 100 : numberValue;
  const clamped = clampUnit(scaled);
  if (clamped !== scaled) {
    reasons.push(`${label} was outside 0-100%; clamped to ${formatPercent(clamped)}.`);
  }

  return clamped;
}

function normalizeCapacity(value: unknown, label: string, reasons: string[]): NormalizedCapacity {
  if (value == null) return { value: undefined, specified: false };
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was invalid and ignored.`);
    return { value: undefined, specified: true };
  }
  if (numberValue < 0) {
    reasons.push(`${label} was below zero; using 0.`);
    return { value: 0, specified: true };
  }
  return { value: numberValue, specified: true };
}

function buildAudit(
  requestedCapacity: number | undefined,
  availableCapacity: number | undefined,
  maxCapacity: number | undefined,
): SizingResult["audit"] {
  return {
    ...(requestedCapacity != null ? { requestedCapacity } : {}),
    ...(availableCapacity != null ? { availableCapacity } : {}),
    ...(maxCapacity != null ? { maxCapacity } : {}),
  };
}

function capacityBasis(
  availableCapacity: NormalizedCapacity,
  requestedCapacity: NormalizedCapacity,
  maxCapacity: NormalizedCapacity,
) {
  const capacities = [availableCapacity, requestedCapacity, maxCapacity]
    .filter((capacity) => capacity.specified)
    .map((capacity) => capacity.value ?? 0);
  if (capacities.length > 0) return Math.max(...capacities);
  return 1;
}

function applyCap(
  name: "requestedCapacity" | "availableCapacity" | "maxCapacity",
  cap: number | undefined,
  size: number,
  cappedBy: string[],
  reasons: string[],
) {
  if (cap == null || size <= cap) return size;
  cappedBy.push(name);
  reasons.push(`Capped by ${name} at ${formatNumber(cap)}.`);
  return cap;
}

function smallestDefined(...values: Array<number | undefined>) {
  const defined = values.filter((value): value is number => value != null);
  return defined.length ? Math.min(...defined) : Number.POSITIVE_INFINITY;
}

function constraintName(constraint: SizingConstraint) {
  return constraint.label ? `${constraint.label} (${constraint.id})` : constraint.id;
}

function modeFor(normalizedSize: number): SizingMode {
  if (normalizedSize <= 0) return "none";
  if (normalizedSize <= 0.05) return "micro";
  if (normalizedSize <= 0.15) return "small";
  if (normalizedSize <= 0.4) return "normal";
  if (normalizedSize <= 0.7) return "large";
  return "maxSafe";
}

function clampUnit(value: number) {
  /* c8 ignore next */
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function round(value: number) {
  return Number(value.toFixed(6));
}

function formatPercent(value: number) {
  return `${Math.round(value * 100)}%`;
}

function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

/* c8 ignore next 3 */
function unique(values: string[]) {
  return Array.from(new Set(values));
}

/* c8 ignore next */
import { clamp, mean, numeric } from "../math/statistics";
import type { DetectedNeed } from "../types";
import { sizeDecision, type SizingConstraint, type SizingInput, type SizingResult } from "./engine";

export const ADAPTIVE_SIZING_LADDER = [0, 1, 2, 5, 10, 15, 25, 50, 100] as const;

export type AdaptiveSizingInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  opportunityQuality: number;
  signalConfidence: number;
  marketParticipation: number;
  riskControl: number;
  perceptionAlignment: number;
  systemTrust: number;
  discoveryStrength: number;
  risk?: number;
  requestedCapacity?: number;
  availableCapacity?: number;
  minCapacity?: number;
  maxCapacity?: number;
  needs?: DetectedNeed[];
  constraints?: SizingConstraint[];
  ladder?: readonly number[];
  context?: Record<string, unknown>;
};

export type AdaptiveSizingResult = SizingResult & {
  selectedLadderPct: number;
  ladder: number[];
  sizingRationale: string[];
};

/**
 * Adaptive sizing wraps the generic risk gate with an explainable ladder.
 *
 * The base `sizeDecision` remains responsible for hard constraints, caps, and
 * risk normalization. This adapter only chooses the largest graduated step that
 * fits inside the allowed capacity, keeping exploratory allocations possible
 * without bypassing existing safety checks.
 */
export function sizeAdaptiveOpportunity(input: AdaptiveSizingInput): AdaptiveSizingResult {
  const ladder = normalizeLadder(input.ladder ?? ADAPTIVE_SIZING_LADDER);
  const quality = ratio(input.opportunityQuality);
  const confidence = ratio(input.signalConfidence);
  const participation = ratio(input.marketParticipation);
  const riskControl = ratio(input.riskControl);
  const alignment = ratio(input.perceptionAlignment);
  const trust = ratio(input.systemTrust);
  const discovery = ratio(input.discoveryStrength);
  const needRisk = needRiskPressure(input.needs ?? []);
  const risk = Math.max(ratio(input.risk ?? 1 - riskControl), 1 - riskControl, needRisk);
  const blendedConfidence = mean([quality, confidence, alignment, trust, discovery]);
  const utility = mean([quality, participation, discovery, needParticipationBoost(input.needs ?? [])]);
  const constraints = [...(input.constraints ?? []), ...constraintsFromNeeds(input.needs ?? [])];
  const baseInput: SizingInput = {
    targetRef: input.targetRef,
    actionRef: input.actionRef,
    decisionRef: input.decisionRef,
    confidence: blendedConfidence,
    risk,
    utility,
    requestedCapacity: input.requestedCapacity,
    availableCapacity: input.availableCapacity,
    minCapacity: input.minCapacity,
    maxCapacity: input.maxCapacity,
    constraints,
    context: input.context,
  };
  const base = sizeDecision(baseInput);
  const allowedCapacity = base.decision === "allowed" ? base.size : 0;
  const selectedLadderPct = selectLadderStep(ladder, allowedCapacity);
  const finalSize = selectedLadderPct;
  /* c8 ignore next */
  const normalizedSize = normalizeByCapacity(finalSize, input.maxCapacity ?? input.availableCapacity ?? input.requestedCapacity);
  const sizingRationale = [
    `Opportunity quality ${formatPct(quality)} and discovery strength ${formatPct(discovery)} set the opportunity tier.`,
    `Signal confidence ${formatPct(confidence)}, alignment ${formatPct(alignment)}, and system trust ${formatPct(trust)} set the confidence tier.`,
    `Risk control ${formatPct(riskControl)} and detected needs keep the final step inside existing safety gates.`,
    `Selected ladder step ${formatNumber(selectedLadderPct)} from ${ladder.join(", ")}.`,
  ];

  return {
    ...base,
    decision: selectedLadderPct > 0 ? base.decision : base.decision === "blocked" ? "blocked" : "deferred",
    mode: modeForStep(selectedLadderPct),
    size: finalSize,
    normalizedSize,
    selectedLadderPct,
    ladder: ladder.slice(),
    reasons: [...base.reasons, ...sizingRationale],
    sizingRationale,
  };
}

function constraintsFromNeeds(needs: DetectedNeed[]): SizingConstraint[] {
  return needs.flatMap((need): SizingConstraint[] => {
    if (need.category === "reduce-exposure" && need.severity >= 70) {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "hard" as const,
        passed: false,
        severity: "high" as const,
        reason: need.explanation,
      }];
    }

    if (need.category === "wait" && need.severity >= 70) {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "hard" as const,
        passed: false,
        severity: "high" as const,
        reason: need.explanation,
      }];
    }

    if (need.category === "gather-evidence") {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "soft" as const,
        passed: need.severity < 60,
        severity: "medium" as const,
        reason: need.explanation,
      }];
    }

    return [];
  });
}

function needRiskPressure(needs: DetectedNeed[]) {
  return ratio(Math.max(0, ...needs
    .filter((need) => need.category === "reduce-exposure" || need.category === "wait")
    .map((need) => need.severity)));
}

function needParticipationBoost(needs: DetectedNeed[]) {
  const increase = needs.find((need) => need.category === "increase-participation");
  return increase ? ratio(increase.confidence) : 0.5;
}

function selectLadderStep(ladder: number[], allowedCapacity: number) {
  const selected = ladder.reduce((stepSelected, step) => (step <= allowedCapacity ? step : stepSelected), 0);
  if (selected > 0 || allowedCapacity <= 0) return selected;
  /* c8 ignore next */
  return ladder.find((step) => step > 0) ?? 0;
}

function normalizeLadder(ladder: readonly number[]) {
  return Array.from(new Set(ladder.map((step) => Math.max(0, numeric(step))).filter(Number.isFinite))).sort((a, b) => a - b);
}

function normalizeByCapacity(size: number, capacity: number | undefined) {
  const basis = numeric(capacity, 100);
  return basis <= 0 ? 0 : Number(clamp(size / basis, 0, 1).toFixed(6));
}

function ratio(value: unknown) {
  const parsed = numeric(value);
  return clamp(Math.abs(parsed) > 1 ? parsed / 100 : parsed, 0, 1);
}

function modeForStep(step: number): SizingResult["mode"] {
  if (step <= 0) return "none";
  if (step <= 2) return "micro";
  if (step <= 10) return "small";
  if (step <= 25) return "normal";
  if (step <= 50) return "large";
  return "maxSafe";
}

function formatPct(value: number) {
  return `${Math.round(value * 100)}%`;
}

/* c8 ignore start */
function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}
/* c8 ignore stop */

/* c8 ignore next */
export type SurvivalOutcomeClass =
  | "comfortable_survival"
  | "stressed_survival"
  | "barely_survived"
  | "failed_survival";

export type SurvivalAction = "buy" | "sell" | "hold" | "watch" | "reduce" | "exit";

export type SurvivalMemoryStatus = "empty" | "clear" | "watch" | "scarred" | "near_ruin";

export type SurvivalMemoryRecommendation = "act" | "act_with_reduced_size" | "wait";

export interface SurvivalMemoryRecord {
  id: string;
  timestamp: string;
  asset?: string;
  venue?: string;
  regime?: string;
  stateFingerprint: string;
  action: SurvivalAction;
  maxExposure: number;
  realizedReturn: number;
  maxDrawdown: number;
  maxAdverseExcursion: number;
  recoveryTimeBars?: number;
  volatilityExpansion: number;
  tailRisk: number;
  liquidityStress: number;
  structuralDanger: number;
  novelty: number;
  opportunityDensity: number;
  outcomeClass: SurvivalOutcomeClass;
  survivalCost: number;
  scarWeight: number;
  notes?: string[];
}

export type SurvivalCostInput = {
  maxDrawdown?: number;
  maxAdverseExcursion?: number;
  recoveryTimeBars?: number;
  volatilityExpansion?: number;
  tailRisk?: number;
  liquidityStress?: number;
  structuralDanger?: number;
  novelty?: number;
};

export type SurvivalClassificationInput = SurvivalCostInput & {
  realizedReturn?: number;
  survivalCost?: number;
};

export type SurvivalMemoryRecordInput = SurvivalClassificationInput & {
